window.__D("text/shaarei-orah/c002",{"p":[[2201340142,"אין ערוך לך שכולם בשוה אין ערוך אליו דהיינו שבשמים ממעל אין עוד ממש כמו מתחת לארץ אין עוד שהרי אמר אין עוד לשניהם בשוה כמ\"ש בשמים ממעל ועל הארץ מתחת אין עוד ובשמים ממעל היינו עד רום המעלות שהוא בבחי' ראשית הכל כו' עד על הארץ מתחת בסוף העשיה שניהם שוין בענין הבטול דאין עוד שזהו ענין אין ערוך לך כו' וד\"ל. וא\"כ לפ\"ז כמו שיכול להיות התהוות החכמה הרוחנית בבחי' יש בדלוג הערך כמו\"כ יכול להיות התהוות יש הגשמי דעשיה מבחי' סובב ג\"כ באותו הענין ממש ולמה יפלא יות' על התהוות יש דעשיה מבחי' סובב מהתהוות ח\"ע מאחר ששניהם שוין כי הגם שהחכמה נבדל בערך המעלה לגבי העשיה היינו מצד בחי' ההשתלשלות שזה ראש וזה סוף משא\"כ לגבי מהו\"ע שניהם שוין בדלוג הערך מאתו ית' מאחר שהתהוות שניהם הוא בא שלא ע\"י בחי' עו\"ע ממהו\"ע אלא כי הוא צוה ונבראו כנ\"ל וזהו התירוץ על הקושיא דלעיל דמשום שהוא מקיף לד' עולמות בשוה אדרבה היא הנותנת לומר שיוכל להיות ממנו התהוות יש דעשייה בענין דלוג הערך ביותר מאחר שגם בחי' ח\"ע דאצילות בא מאתו ג\"כ בבחי' דלוג הערך ביותר באותו ענין שמתהווה יש גשמי לפי ששניהם שוין לפני מהו\"ע כנ\"ל וד\"ל:\n(נב) <b>ואחר</b> כל הנ\"ל יובן בשרש ענין בחי' לבוש מל' הנ\"ל. דהנה ידוע שבחי' הארת הקו והחוט הנמשך מאור א\"ס. הוא הנמשך מבחי' מלכות דא\"ס. בחי' האחרונה. שבו הוא שמתלבש בבחי' הקו הזה. הנמשך אחר בחי' הצמצום הראשון הנקרא מק\"פ וחלל כו'. ונמצא שבחי' הארה זו ממל' דא\"ס. שלאחר הצמצום דמק\"פ נקרא רק הארה דהארה. לגבי עצמות אא\"ס כמו שהוא קודם הצמצום דמק\"פ כו'. וז\"ש כי עמך מקור חיים באורך נראה אור כידוע וזהו הנקרא בחי' ממלא כ\"ע בכללות כל ההשתלשלות דאבי\"ע. לפי שמבחי' אור זה נמשך האור והשפע בכל עולם ועולם לפי ערך קבלתו כו'. ע\"פ מאמר קו המדה. עד שבא בבחי' הגבלת אורות בכלים בציור פרצוף אדם. שזהו בחינת אדם דאצילות בכלל (ובחינת אדם זה יש בו מדרגות חלוקות. כשהוא בבחינת הקטנות נקרא ז\"א. וכשהוא בבחי' הגדלות נקרא א\"א כידוע. וכשהוא בבחינת הגדלות יותר. נקרא א\"ק כו'. וג' מדרגות הן. אדם דבריאה. אדם דיצירה כו' כמ\"ש במ\"א). והנה בבחי' פרצוף אדם יש בו בחי' ראש ותוך וסוף וימין ושמאל ואמצעי כו'. כי בחי' המוחין חב\"ד נקרא חכמה שבראש:\n<b>שבהן</b> בחינת אור וחיות גדול מכל מה שלמטה הימנו. ולמטה הימנו בחי' המדות חג\"ת שבלב ונקרא גופא ותרין דרועין שזהו ימין ושמאל ואמצעי כו'. ולמטה יותר בחינת נה\"י תרין ירכין כו'. והן ד' העולמות דאבי\"ע בכלל אצילות חכמה בריאה בינה כו'. וגם בחי' הכתר דאדם דאצילות. הוא בכלל ציור פרצוף אדם רק שהוא למעלה על כל האורות להיות כי בחי' הכתר הוא כמו העטרה על הראש. והוא בחי' גלגלתא וקרקפתא. שהיא בבחי' כלי עכ\"פ רק שהוא בחינת כלי לאור הרצון העליון שלמעלה מבחי' המוחין דחב\"ד כו' כידוע אבל נקרא גלגלת דאדם ה\"ז בציור אדם דוקא משא\"כ למעלה מבחי' הקו הזה שנמשך בציור אדם שם נא' כי לא אדם הוא בציור ראש וגלגלתא ומוחין ומדות כו' אלא הוא בחי' אור פשוט בתכלית והוא בחי' עצמות אא\"ס שלפני הצמצום הנקרא מק\"פ שנקרא עיגול הגדול המקיף לכל החלל ומק\"פ עם בחי' הקו שנמשך משם מראש לסוף בשוה ממש כי קמיה שוין ראש וסוף ממש כנ\"ל באריכות וד\"ל:\n(נג) <b>וזהו</b> בחי' לבוש מל' כמו עטה אור כשלמה ולבוש ממש וכמ\"ש ה' מלך גאות לבש כו' דהיינו שנמשך אור מבחי' מקיף וסובב הגדול שלפני הצמצום דמק\"פ הנ\"ל בבחי' לבוש מקיף להלביש על בחי' כתר ומו\"ס דא\"א"],[2201340143,"הנ\"ל עד\"מ אדם שמתעטף בטלית ע\"ג ראשו שמשים הטלית על הראש. שאז גם העטרה שע\"ג ראשו מוקפת מן הטלית מאחר שהטלית מקיפו מראשו לרגליו הרי גם עטרה שבראש בכלל והיינו בחי' הארת א\"ס שלמעלה מבחי' אדם לגמרי כנ\"ל שנעשה בבחי' מקיף ממעל לראש וגלגלתא דא\"א גם לבחי' עטרה שע\"ג הראש כו' מפני שבחי' מקיף זה מקיף לד' עולמות בשוה כנ\"ל כמו שהוא בעצמו לפני הצמצום דמק\"פ שמקיף את כל החלל שבו הקו כו' וממנו ג\"כ בא בחינת הכאת אור מקיף בפנימי. להיות מזה בחי' התהוות הכלים המגבילים את האור להיות בבחינת יש כו' וגם כל בחינת התהוות יש גשמי הוא בא מבחינת סובב זה דוקא. מפני שהוא מובדל בערך מהכל ושוה לפניו ראש וסוף כנ\"ל באריכות וד\"ל ואע\"פ שמבואר למעלה בבחי' גלגלתא וכתר שהוא ג\"כ בבחי' מקיף אבל אינו רק בבחי' מקיף בדרך פרט שזהו לגבי החכמה והמוחין המכוסים ונעלמים בפנימיות שבגלגלתא שהוא בחינת מו\"ס הנ\"ל אבל לגבי בחינת העצמות דאא\"ס שנקרא לבוש מלכות הרי גם בחי' כתר שבגלגלתא מכלל בחי' ציור אדם שהוא אור מוגבל בכלי עכ\"פ כנ\"ל. אלא שמ\"מ יש בו מבחי' התחתונה שבעצמות המאציל וכידוע שבחינת אור הכתר בכלל הרי הוא בחינת ממוצע בין המאציל לנאצלים ויש בו מבחינת התחתונה שבמאציל שזהו בחי' גלגלתא דא\"א בחי' רצון העליון ששורה בו הארת סובב הכללי ובחי' מו\"ס דא\"א הוא שרש הנאצלי' כו' וד\"ל:\n(נד) <b>וזהו</b> יביאו לבוש מלכות אשר לבש בו המלך פי' בחי' לבוש. המקיף אל כל בחי' אדם העליון. ממעל לראשו עד בחי' רגליו בהשוואה אחת והיינו בחי' המשכת אור מבחי' עצמות אא\"ס שלפני הצמצום כו' ובחינת לבוש מלכות זה יביאו למעלה ע\"י אתדל\"ת בבחי' ביטול הרצון לבעל הרצון דוקא שנקרא רעוא דכ\"ר כו' והוא ע\"י שהקדימו ישראל נעשה לנשמע כנ\"ל נעשה דוקא בבחי' עשיה בפ\"מ וכנ\"ל דשרש בחי' העשיה נמשך מבחי' סובב דוקא ודוקא ע\"י בחינת קיום המצוה בבטול רצון דוקא מפני שבטול עצמי זה שלמעלה מן הטעם מגיע למעלה בשרש ומקור הראשון דהיינו בחי' לבוש מלכות הנ\"ל שמאיר בגלגלתא כו' כנ\"ל ואח\"כ אמר ואשר נתן כתר מלכות בראשו שהוא בחי' עטרה שעטרה לו אמו כו' כעטרה ע\"ג הראש. שהיא למטה מבחי' לבוש מל' והוא בחי' כתר עליון תר\"ך עמודי אור שהן בחי' תרי\"ג ארחין דגלגלתא כו' המלובש במצות מצד עצמן כשהן עשוין מדברים גשמיים שנמשל לאבנים טובות שבעטרה כמ\"ש למעלה (אך למעלה מבואר בכ\"ז להפך דבחי' לבוש מלכות למטה מבחי' כתר מל' שלבוש מל' הוא מבחי' המצות עצמם טרם שמקיימין אותם משום דסוף מעשה שהוא הרצון המלובש בדברים גשמיים עלה בתחלת המחשבה להיות אנא אמלוך שזהו רק בחי' מלכות דא\"ס כו' אבל קיום המצוה כמו בבטול דנעשה כו' מעורר למעלה בחי' כתר דמל' דא\"ס זה והוא בחי' העטרה ע\"ג הראש שזהו נח\"ר לפניו שאמר כו' וזהו ואשר נתן כתר מלכות בראשו שהוא למעלה מבחי' לבוש מל' כמ\"ש למעלה באריכות) ובכ\"ז מובן בתוס' באור בשרש ענין ההפרש בין תורה למצות הנ\"ל שיש מעלה בזה מה שאין בזה דהיינו מצד הארת סובב הכללי ששורה בגלגלתא שהוא בחי' רצון העליון שבמצות ה\"ז למעלה משרש התורה שהוא בבחי' מו\"ס שאין שם הארת סובב זה בגלוי כ\"כ רק ע\"י צמצום ודלוג גדול כמ\"ש והחכמה מאין כו' אבל מעלה יתירה יש בתורה בשרשה במה שהיא בבחי' פנימית ולא בחצוניות כנ\"ל וד\"ל ומעתה הנה יש להבין בשרש ענין וסוס אשר רכב עליו המלך שזהו מ\"ש במ\"ת כי תרכב על סוסיך כו' וגם להבין שרש ענין מאמר רז\"ל בליליא מאי קא עביד קודב\"ה רוכב על כרוב קל שלו ושט בח\"י אלף עלמין שנא' רכב אלקים רבתים כו' א\"ת"],[2201340144,"שנאן אלא שאינן דהיינו שחסר ב' אלפים כי הנה ח\"י אלף עולמות הן בבחינת גבול והוא בבי\"ע ושרשן הוא נמשך מבחי' האצילות ושם הוא בחי' ח\"י חוליות שהן ח\"י ברכאן דצלותא שהן בחי' המשכות עליונות מאצילות לבי\"ע ע\"י הכריעה שכורע בברוך אתה הוא שנמשך בחי' שם הוי\"ה שבאצילות להיות הוי\"ה אלקינו בגלוי מאין ליש בבי\"ע שהן ח\"י אלף עולמות ואמנם שרש הראשון של המשכות הללו דח\"י חוליות הוא בבחי' המוחין עליוני' שבראש שהוא בחי' חכים ולא בחכמה ידיעא מבין וכו' וזהו ע\"י הכריעה בכפיפת הראש שכופף תחלה שזהו בחי' המשכת חכמה מוחא ואח\"כ ממילא נמשך בחי' ח\"י חוליות שבהן הולך ועובר חוט א' מן המוח שבראש כו' עד בחי' הירכין ששם חלש כח החוט הזה כו' וגם שם אין כפיפה כמו בח\"י חוליות אבל אמנם ע\"י נמשך ונשפע כל שפע אור הנמשך ונק' בחי' נצח והוד שהן בחי' כלי ההשפעה והוא ענין ג' ברכות אחרונות רצה ומודים כו' כידוע בכוונת הש\"ע וד\"ל. והנה כאשר נשפע ונמשך מאצילות לבי\"ע אזי מבחי' ח\"י ברכאן שבאצילות נמשך ומתחלק לח\"י אלף עולמות כי כל א' וא' מתחלק לאלף מדרגות בבוא האור והשפע מאצילות לבריאה שהרי בי\"ע הן בבחי' הגבול לגבי אור האצי' וע\"כ א\"א שיקבלו המלאכים הארת אור האצילות כמו שהוא באצי' אלא ע\"י שיתחלק האור לאלף ונמצא מלאך א' מקבל רק חלק האלף שאם יקבל יותר מכפי המדה יתבטל מציאותו לגמרי כענין הושיט אצבעו קטנה ביניהם ושרפם כידוע וד\"ל:\n(נה) <b>והנה</b> בחי' אור ההמשכה וההשפעה הזאת מח\"י ברכאן דאצי' בבי\"ע הוא ע\"י בחי' כרוב קל כמ\"ש רוכב על כרוב קל שלו ושט בח\"י אלף כו' פי' כרוב כרביא שהוא אדם קטן כידוע בדברי רז\"ל כתי' פני הא' פני הכרוב ופני הב' פני אדם כו' היינו פני כרוב היינו פני אדם אפי רברבי ואפי זוטרי שאפי זוטרי הוא בחי' הכרוב כרבי' ואפי רברבי הוא מ\"ש ועל דמות הכס' דמות כמראה אדם עליו כו' והענין הוא דמה שאמרו הקב\"ה רוכב כו' הוא בחי' אדם הגדול דאצי' בחי' אפי רברבי בבחי' מוחין דגדלות שאא\"ס מאיר שם בגלוי יותר כו' ובחי' אדם הקטן שנק' כרוב כרביא אפי זוטרי היינו בחי' מט\"ט דבריאה ששמו כשם רבו כו' בבחי' מוחין דקטנות ונק' נער כמ\"ש נער הייתי כו' והוא בחי' כרוב קל שלו שע\"י נמשך השפע לח\"י אלף עולמות כנ\"ל ובאור הדברים הנה פי' אדם היינו בחי' שם מ\"ה בגי' אדם והוא שם מ\"ה במלוי אלפין דאיהו אורח כל האצי' כו' דהיינו שע\"י דוקא הוא בחי' החבור והתכללות של כל האורות העליונים זע\"ז ע\"י שנמשך בחי' תוס' גלוי אא\"ס בבחי' שם מ\"ה זה וכל בחינת תוס' גלוי אור עליון ממשיך בחי' בטול עד שגם ההפכיים ומנגדים זע\"ז יתאחדו ויתחברו יחד כי נתבטל כ\"א ממציאותו ואינו מרגיש א\"ע כלל וע\"כ יכול לסבול גם הפכו ומנגדו כי מה שלא יוכל לסבול הפכו היינו מפני בחי' ההתפשטות ישותו כו' וכמשל שני שרים מנגדיים כאש ומים בבואם לפני המלך מפני אימת רוממות המלך שגבוה מאד משניהם יחדיו יתבטל כל א' מישותו ויסבול הפכו והיו לאחדים ממש וכמו\"כ בענין עושה שלום במרומיו בין מיכאל וגבריאל שר של אש ושר של מים ואין מכבין זא\"ז מפני בחי' תוס' גלוי אור האלקי עליהם שלמעלה משניהם שממשיך בחי' בטול גדול בהם עד שיתאחדו ואין מכבין זא\"ז כלל:\n(נו) <b>וכמו\"כ</b> יובן בענין בחי' שם מ\"ה דאצי' שהוא בחי' כח מה דחכמה בחי' הבטול הגדול מפני שראשית גלוי אא\"ס הוא בחכמה דוקא וע\"כ בחי' שם מ\"ה זה הוא ארח כל האצילות להיות בחי' ההתכללות והחבור בע\"ס דאצילות גם בהפכיים כמו חו\"ג לאכללא ימינא ושמאלא כו' גם להחליף כל אור בכלי המנגד שלו כמו אור החסד בכלי הגבורה כו' משום דאנת הוא דקשיר לון"],[2201340145,"ומיחד להון כו' והיינו ע\"י בחי' תוס' גלוי אא\"ס בשם מ\"ה זה שעי\"ז נמשך בחי' בטול גדול וממילא הם מתכללים ומתיחדים זע\"ז כו' וזהו ע\"י שם מ\"ה שהוא במלוי אלפין דוקא כי הנה האלף שרשו בחכמה כמו ואאלפך חכמה ותמונת אות הא' הנה כולל ב' מיני חכמה חכמה עלאה והיינו בחי' היו\"ד שע\"ג הוי\"ו שבאלכסונו וח\"ת שהוא היו\"ד שתחת הוי\"ו שזהו בחי' יח\"ת ויח\"ע והוי\"ו שבאמצע מתחברים בו ב' היודי\"ן דח\"ע וח\"ת שהן כמו ב' הפכים ממש שהרי בחי' ח\"ע מאין תמצא בבחי' בטול לאין ובחי' ח\"ת הוא הפך זה שהרי מבחי' ח\"ת שנק' חכמה שבדבור נמשך ההשתלשלות מאין ליש דוקא כמ\"ש כלם בחכמה עשית כו' ולחבר ח\"ע בח\"ת היינו ע\"י בחי' הוי\"ו שהוא אמצעי ביניהם לחברם יחד והוא עיקר ענין תמונת הא' שזהו בחי' א' דאדם שהוא בחי' החבור וההתכללות דב' יודי\"ן דח\"ע וח\"ת וע\"כ הוא ארח כל האצילות בבחי' ההתכללות בפרט כו' וז\"ש דעד דלא הוה מתקלא לא הוו משגיחין אפין באפין כו' אלא ע\"י בחי' מתקלא שהוא שם מ\"ה עיקר התיקון חזרו להיות פב\"פ ביחוד והתכללות זע\"ז כו' וד\"ל:\n(נז) <b>והנה</b> כתיב מה שמו ומה שם בנו מה שמו היינו בבחינת המוחין עצמן דחב\"ד ששם הוא עיקר בחי' תוס' גלוי אא\"ס ומבחי' המוחין דחב\"ד נמשך ההארה ומתפשט גם במדות חג\"ת ונק' מוחין דז\"א כידוע וזהו ומה שם בנו כו' והיינו בחי' אדם קדמאה אור אבא ואדם בתראה בחי' ז\"א כו' והוא בחי' אדם בפרצוף שלם במוחין ומדות ונק' בחי' מוחין דגדלות בבחי' אפי רברבי הנ\"ל שהרי בחי' מוחין דחו\"ב נמשך גם במדות דז\"א בתכלית הגדלות כמו בזקן בהיותו בן ע' שנה שנק' זקן שקנה חכמה ונק' ישראל סבא דדעתוהי סתים כו' בבחי' ח\"ס כו' וכמאמר רז\"ל בשעת מ\"ת נדמה להם כזקן כו' שבחי' המוחין הן עיקר והארת בחי' הבטול בהן בתכלית כמו עד\"מ הזקן שהוא מיושב בדעתו ביותר משום דמוחין שלו שקיט ושכיך כחמר טב על דורדיי' כו' מפני עוצם גדלות החכמה במקורה כו' ומפני זה נמשך בחי' גלוי אא\"ס במוחין דגדלות דאדם הגדול זה ביותר אבל בבחי' אדם הקטן שהוא בחי' נער מטט' אפי זוטרי כרביא הנ\"ל היינו בחי' אדם שהמוחין שלו הן בבחי' הקטנות ביותר כמ\"ש לפי שכלו יהולל איש כערך שכל התנוק והרביא שהוא קטן ביותר לגבי שכל הזקן ואדם הגדול וע\"כ ממילא גם מדותיו בקטנות מאד לגבי מדותיו של אדם הגדול מפני הארת קטנות השכל במדותיו משא\"כ בגדול שגדלות השכל מתפשט גם במדותיו כו' ומפני זה גם בחי' הבטול הנמשך ע\"י בחי' מוחין דקטנות הללו אין לו ערך לגבי בחי' הבטול שבמדות ומוחין דאדם הגדול וממילא אין בחי' ההתכללות והיחוד במוחין ומדות דאדם דקטנות כמו במוחין ומדות דאדם דגדלות וע\"כ בבחי' מוחין דגדלות מתגלה אא\"ס בגלוי רב ומאיר אור גם במדות משום דלפי שכלו יהולל איש כנ\"ל ואז ממילא יש בחי' התכללות ביותר גם במדות דאדם הגדול כנ\"ל בענין שם מ\"ה דאיהו ארח כל האצילות בפרטי פרטיות כו' משא\"כ בבחי' נער מט\"ט דבריאה שנק' רביא שמפני קטנות המוחין והמדות אין ההארה מאא\"ס שבאצילות בא שם רק בבחי' הצמצום ביותר ע\"כ ממילא אין שם בחי' ההתכללות והחבור בין ב' הפכים כמו באצילות ומ\"ש עושה שלום במרומיו כו' היינו רק שאין מכבין זא\"ז שסובלין זא\"ז אבל לא שנכללים ומתאחדים ממש כיחוד והתכללות האמתי שבמדות דאצי' כו' וד\"ל:\n(נח) <b>וזהו</b> ענין מט\"ט שנק' נער כמ\"ש נער הייתי וגם זקנתי כו' ששמו כשם רבו שהוא בחי' אדם העליון דאצי' כידוע דבחי' ו\"ק דאצי' מתלבשים בו\"ק דבריאה שהוא מט\"ט והיינו שהקב\"ה רוכב על כרוב קל כו' בחי' מט\"ט זה שע\"י נמשך השפע לכל המלאכים והעולמות שהן ח\"י אלף עולמות ומה שמתחלקין"],[2201340146,"לח\"י אלף היינו ג\"כ מפני שבבחי' הקטנות מתחלק לחלקים רבים יותר דהיינו מה שבבחי' הגדלות דאצי' הוא רק אור א' מתחלק למטה בבחי' הקטנות דנער כו' לאלף והיינו שע\"י בחי' כרוב קל זה שט בח\"י אלף כו' והיינו דוקא בלילה כמ\"ש בליליא מאי קא עביד רוכב כו' כי ביום חסד אל שהוא מדת יום שבאצי' בבחי' מוחין דגדלות דחב\"ד ומדות דאדם הגדול והיינו מ\"ש ג\"ש ראשונות הקב\"ה יושב ועוסק בתורה שניות יושב ודן כו' אבל בליליא הוא בחי' הקטנות דמל' כשמסתתרת למטה מטה שאז הוא ע\"י בחי' כרוב קל להשפיע למלאכים דוקא כי ביום הוא זמן שפע לנשמות דוקא שהן מבחי' אדם העליון וע\"כ ביום דוקא כל ענייני האדם בג' תפלות ובמזון סעודותיו בקר וערב ובעסק פרנסתו כו' משא\"כ המלאכים כל עניינם הוא בלילה דוקא ולא ביום כמו שיר שלהם הרי או' בלילה דוקא וגם זמן שפע מזונם מלמעלה הוא בלילה כי נזונים ע\"י בחי' המל' שמבררת ברורים בלילה להמציא טרף ומזון למלאכים כמ\"ש ותקם בעוד לילה ותתן טרף לביתה אלו המלאכים וחק לנערותיה הן בחי' היכלות כו' וע\"כ אמרו שהקב\"ה רוכב על כרוב קל שלו בלילה דוקא להשפיע שפע למלאכים שהן ח\"י אלפים עולמות כמ\"ש רכב אלהים רבתים כו' לפי שמקבלים מבחי' מט\"ט ב\"פ ט\"ס דא\"י ואו\"ח גי' ח\"י כמ\"ש חי חי הוא יודוך. ח\"י ברכאן דאצי' וח\"י דמט\"ט כמ\"ש כי שמי בקרבו רק שבא בו שם הוי\"ה בבחי' הקטנות מאד וע\"כ חסר בו ב' אלפין שהן ב' אלפין דואאלפך חכמה אאלפך בינה כו' שהוא בחי' הכתר שהוא מקור בחי' הגדלות דחכמה וע\"כ נקרא מט\"ט (ויש הפרש בין מיט\"ט ביו\"ד שהוא בריאה ובין מט\"ט בלא יו\"ד שהוא ביצי' כמ\"ש במ\"א) וז\"ש שנאן שאינן שנשארים בהעלם ואין למעלה כו' אבל כמו שהוא למעלה באצי' נק' רכב אלהים רבתים. י\"ס דא\"י וא\"ח בשלימות הארת הכתר בחכמה וכמ\"ש במ\"א בענין עשרים גרה השקל כו' וד\"ל):\n(נט) <b>אך</b> כ\"ז שהשפע נמשך דרך בחי' כרוב הנ\"ל היינו דוקא מאצי' לבי\"ע שהוא בבחי' רוחניות השפע עדיין להיות מזון וחיות למלאכים עליונים דבי\"ע ה\"ז ע\"י בחי' נער מט\"ט בחי' אדם רק שהוא אדם קטן כרביא בחי' הקטנות דמוחין ומדות אבל הוא בבחי' פרצוף אדם במוחין ומדות כו' כי בחי' גדלות המוחין דח\"ע עכ\"פ מאיר גם בו רק שמצומצם בו ביותר כמשל הנער ששכלו ומדותיו קטנים כנ\"ל אבל בחי' ההמשכה וההשפעה היורדת למטה מטה בהגשמה גמורה כמו בעוה\"ז השפל החומרי שהוא למטה מטה הרבה מבחי' ח\"י אלף עולמות הרוחני' הנ\"ל הנה זה נמשך ע\"י בחי' סוס דוקא וכמו שראה זכריה במרכבה סוסים אדומים וסוסים שחורים כו' שהוא בחי' כחות ההשפעה שנמשך ע\"י לעוה\"ז השפל להתלבש בגשמיות ממש כמו בני חיי ומזוני הגשמיים וכל הברכה והשפע הגשמי' בדצח\"מ וארמ\"ע כו' והיינו וסוס אשר רכב עליו המלך עד\"מ הסוס בגשמיות שכחו גדול יותר מן האדם ע\"כ יכול לישא את הרוכב למקום רחוק ביותר שלא יוכל להגיע שם בעצמו כלל וגם מרוצתו גדול' הרבה יותר ממרוצת האדם מפני גבורת כח הסוס כידוע. וכמו\"כ יובן למעלה בבחי' ירידת אור השפע מרוחניות וגשמיות בעוה\"ז השפל שהוא ע\"י בחי' גבורת סוס העליון שיוכל להוריד השפע וחיות הרוחניות למטה מטה כ\"כ עד עולם הגשמי הזה שזהו בבחי' מרוצה בכח גדול שאין זה בכח אדם כלל דהיינו שאין זה ביכולת בחי' כרוב נער מט\"ט הנ\"ל שא\"י להוריד בעצמו כ\"כ למטה מטה רק מאצי' לבי\"ע בבחי' הרוחניות בלבד כנ\"ל אבל לא בעשיה גשמית כ\"א שולח השפע ע\"י בחי' מרכבה דסוסים עליונים שהן כמו מרכבות סוסים שראה זכריה הנביא שמוליכים בחי' שפע עליונה לע' שרים שלמטה כו' וזהו כי תרכב על סוסיך מרכבתיך ישועה"],[2201340147,"שבחי' מרכבה דסוסים היו גם בזמן מ\"ת וע\"ז אמר דוקא וסוס אשר רכב עליו המלך כנ\"ל דהנה אמר רכב אלקים רבתיים כו' אד' בם סיני בקדש ולכאורה אין זה שא' סיני בקדש שייך לענין רישא דקרא רכב אלהים כו' אך הענין הוא שכש' שנמשך למלאכים עליונים שהן ח\"י אלף עולמות מבחי' רכב אלקים בחי' כרוב קל הנ\"ל כך אדנ\"י בם סיני בקדש דהיינו ע\"י בחי' אור דשם אדנ\"י המצומצם במרכבה דפני אריה כו' נמשך מהם למטה מטה לבא האור והשפע בעשיה גשמית והוא ענין בחי' ההמשכה האלקית ממש שנתלבש ובא בעשיה גשמית בעוה\"ז השפל בבחי' גלוי קולות וברקים וענן כבד ואש להמשיך התורה בעשיה גשמית לא תרצח כו' וכמו לעשות המשכן בדברים גשמיים כיריעות וקרשים גשמיים שיהיה גלוי אלקות ודברים גשמיים כ\"כ ה\"ז ע\"י בחי' מרכבה דסוסים דוקא כמו שהתלבשות אור העליון בעוה\"ז בהשפעת הגשמיי' הוא ע\"י סוסים מטעם הנ\"ל כמו שגבורת הסוס גשמי גדול מגבורת האדם להוליך למקום רחוק כו' וזהו כי תרכב על סוסיך בשעת מ\"ת מרכבותיך ישועה שיש בהן כח ואור גדול ביותר מאור הנמשך ע\"י בחי' אדם שהוא ע\"י בחי' כרוב נער מט\"ט הגם שנא' בו כי שמי בקרבו כנ\"ל וד\"ל:\n(ס) <b>אך</b> עדיין יש להבין הא גופא למה יש גבורה וכח בסוס יותר מאדם שע\"י יוכל אור העליון לירד מטה מטה כ\"כ כו' אמנם שרש הדברים הוא לפי שגי' דסו\"ס הוא ב\"פ ס\"ג והיינו בבחי' ס\"ג שלמעלה משם מ\"ה כי בחי' שם מ\"ה הוא בבחי' אדם וכנ\"ל בא' דאדם שהוי\"ו שבו מחבר יו\"ד העליון ויו\"ד התחתון והיינו אלף ואאלפך חכמה שזהו בבחי' חכמה הבאה בבחי' גלוי מאין וכמ\"ש והחכמה מאין תמצא בבחי' נקודה דיו\"ד ויו\"ד זה מתחבר למטה בח\"ת יו\"ד התחתון חכמה תתאה כמ\"ש פיה פתחה בחכמה כו' משום שנעוץ תחלתו בסופו חכמה בראש עם חכמה בסוף רק שחכמה שבראש נק' אדם גדול וח\"ת שבדבור בלבד נק' אדם קטן בחי' כרוב כו' אך כ\"ז במה שכבר בא האור והשפע מן ההעלם דכתר לחכמה שנקרא אלף דאדם כו' ואמנם בחי' אור הנעל' בכתר שלא בא עדיין בגלוי בחכמה זהו הנקרא פלא שנפלא ונעלם מלבא בגלוי כלל גם בבחי' נקודה דיו\"ד כו' ואז א\"א להיות תמונת אלף כלל רק התמונה הוא אות הס' שהוא עגול וסתום מכל צד שמורה על בחי' הפלאת האור למעלה בעצמותו בלתי יבא למטה כלל (וכמ\"ש במ\"א בענין ס' ומ\"ם שבאפרסמון כו') וכמו שבחי' פלא זה הוא למעלה בעצמות כמו\"כ גם בבואו למטה הוא סתום ונעלם והוא מ\"ש אתה אל מסתת' ובחי' הסתר זה הוא באותיות הטבע כו' וזהו ס' הב' דסוס אמנם הוי\"ו שבאמצע הוא המחבר לבחי' הסתר והעלם העליון העצמי דס' הא' לבחי' הסתר והעלם שלמטה שהוא בחי' הסתר גמור שהוא ס' הב' והיינו ב\"פ ג\"ס שהוא לאחר ירידת האור למטה בהסתר והגשמת אותיות הטבע ושרשו ב\"פ ס\"ג כמו שהיה קודם השבירה בבחי' ס\"ג דתהו שהיו כולם בבחי' הכתרים כו' וזהו עיקר ענין גבורת הסוס שממשיך מפלא העליון למטה מטה במדרגות התחתונות ששם בחי' הסתר אלקות בתכלית כנ\"ל כי כמו שוי\"ו דאל\"ף מחבר לב' יודי\"ן דח\"ע וח\"ת כמו\"כ וי\"ו דסוס מחבר מהעלם האור דח\"ע שבבחי' כתר למטה מטה בסתר המדרגות וע\"כ בחי' גבורת הסוס יותר מגבורת כח האדם דשם מ\"ה במלוי אלפין שיוכל להוריד אור עליון למטה מטה כ\"כ וממקום עליון ביותר אך לא ע\"י הסוס לבדו כ\"א ע\"י הרוכב עליו שהוא בחי' אדם שם מ\"ה משום דבחכמה אתברירו כו' ואע\"פ שהמרוצה עצמה היא של הסוס מ\"מ צריך לרוכב שירכב עליו וגבורתו הוא שמוליך את הרוכב למקום רחוק כו' וזהו כי תרכב על סוסיך במ\"ת שבחי' אדם הגדול דאצי' רוכב על בחי'"],[2201340148,"הסוסים שגבורתם להמשיך מלמעלה מבחי' החכמה למטה ביותר וע\"כ מרכבתיך ישועה בחי' שע\"ה נהורין דהאר' פנים דא\"א שלמעלה מן הח\"ע כו' כידוע ופי' ישועה הוא ג\"כ לנצח את השונא במלחמה אך כתיב סוס מוכן למלחמה ולה' הישועה דוקא וכמ\"ש לא בגבורת הסוס יחפץ ולא בשוקי האיש ירצה שכולל בזה גבורת הסוס הנ\"ל עם רוכבו שהן שוקי האיש כמו רוכב על כרוב כו' כ\"א את המיחלים לחסדו חסדו ממש כי חפץ חסד הוא מעצמו לבלתי ידח ממנו נדח כו' שבזה מתברר יותר כל הניצוצות שנפלו בנוגה ולא יחפוץ במלחמ' דסוס ורוכבו לברר ברורים כו' כמ\"ש סוס מוכן למלחמה אבל לה' הישועה דוקא הגם שמושיע ע\"י סוס ורוכבו אבל אין הישועה מצד עצמם כ\"א לה' הישועה וכמ\"ש שקר הסוס לתשועה כו' אך הנה עין ה' אל יראיו למיחלים לחסדו דוקא וד\"ל ולע\"ל כתיב ביום ההוא יהיה על מצלות הסוס קדש לה' וארז\"ל כל מה שהסוס רץ ומצל יהיה קדש לה' כו' שהוא ענין הברורים שע\"י בחי' מרכבה דסוסים כמו שראה זכריה כו' בסוף שיהיה תשלום הברור ע\"י וזהו שיהיה כל מה שהסוס רץ כו' וכ\"ז מפני שצריך להמשיך האור ממקום עליון ביותר כשבא למטה מטה ביותר כידוע שבמקום חשך צריך אור גדול יותר וגם כאן כדי שירד האור למטה מטה ביותר בעשיה צריך להיות מאור עליון ביותר לפי שכל הגבוה גבוה יותר יותר יוכל להשפיל א\"ע כו' וכמשל האבוקה הגדולה שמאיר' למרחוק יותר כו' ע\"כ א\"א לבא השפע בעשיה כ\"א ע\"י בחי' סוס ולא ע\"י בחי' כרוב דהיינו ע\"י בחי' ס\"ג שלמעלה מבחי' מ\"ה כנ\"ל מפני שבחי' כרוב הנ\"ל הממשיך אל המלאכי' אין בכחו לרוץ כ\"כ למטה כמו בחי' הסוס וע\"כ גם במ\"ת שהוצרך להשפיל האור בבחי' עשי' גשמית דמצות מעשיות ומעשה המשכן וכה\"ג ע\"כ אמר כי תרכב על סוסיך דוקא וד\"ל וזהו וסוס אשר רכב עליו המלך ששרשו למעלה מבחי' אדם ובכחו להמשיך מטה מטה ממקום עליון ביותר שהוא באותו בחי' ומדרגה דלבוש מל' שלמעלה בציור אדם כנ\"ל וד\"ל (ויביאו לבוש מלכות וסוס כו' הכל מלמטה למעלה באתדל\"ת דוקא כו' וד\"ל):\n(סא) <b>אך</b> מעתה יש להבין מ\"ש ויקח המן את הלבוש ואת הסוס כו' מה שייך זה להמן דוקא וגם למה לא הזכיר רק הלבוש והסוס ולא הזכיר כתר מל' כו' כי הנה שרש בחי' המן בקליפה מבואר למעלה שהוא למעלה מז' עכו\"מ שהן ז' מדות כו' וזהו ראשית גוים עמלק דהיינו בחי' חוצפה וגסות שהוא בחי' ס\"ג אותיות גס. אמנם הנה יש בחי' המן בקדושה לאחר הברור והוא בחי' התנשאות והגבהת הלב למעלה בעבודת ה' כמ\"ש ביהושפט ויגבה לבו כו' וכמארז\"ל שיתן עיניו למטה ולבו למעלה פי' עיניו בחי' חכמה כח מה דמשה שפלות וענוה יתירה ולבו למעלה בקצת הגבהה כו' שאל\"כ לא יערב לבו לגשת אל ה' כו' כנ\"ל וע\"כ ת\"ח צ\"ל בו חלק שמיני שבשמיני' כו' כנ\"ל וזהו שלאחר הברור נעשה מגס ס\"ג אך הנה בחי' ס\"ג דמלכי' דתהו שא' אנא אמלוך כו' ה\"ז בחי' הגבהה והתנשאות יתירה כמו לאמר אנא אמלוך אנא דוקא כו' וכיוצא בזה מצינו בכמה צדיקים מופלגים שהיו מנשאים א\"ע ביותר וכמו רשב\"י שאמר ראיתי בני עלי' והם מועטים כו' עד שא' אני ובני הם כו' וכן אמר אנא סימנא בעלמא ולכאורה זהו הפך ממש משפלות וענוה דכח מה דמשה כו' אך הענין הוא דכמו שיש בקליפה המנגד לקדושה האלקית ב\"פ ג\"ס שהוא ב' מיני גסות וחוצפה הא' מצד הטעם כמו מצד עושרו וגדולתו כמו ויספר להם המן את כבוד עשרו כו' והב' גסות וחוצפה שלמעלה מן הטעם כו' והיינו ב\"פ ג\"ס וכנגד זה לאחר הבירור דקליפה להיות בבחינה הקדושה נעשה ג\"כ ב\"פ ס\"ג כנ\"ל והיינו ב' מיני התנשאות האלקית הא' התנשאות והגבהת הלב בדרכי ה' מצד הטעם"],[2201340149,"והשגה בקרבתו לאור ה' כמ\"ש ז\"ל ולבו למעלה כו' אבל זהו רק חלק שמיני שבשמינית כו' ויותר מזה מזיק לנפשו האלקית שנעשה בחי' גס כמ\"ש כלו סג אותיות גס כו' והב' הוא בחי' התנשאות יתירה בבחי' אלקות שלמעלה מן הטעם וההשגה כמו שא' רשב\"י אנא סימנא בעלמא כו' וכה\"ג והוא בהיות שהיתה נשמתו מבחי' מל' דאצי' ממש וכידוע שבחי' מל' דאצי' נעשה ע\"י לבריאה והוא בציור אדם קומה שלימה ויש נשמות שנק' ראשי אלפי כו' ושרש נשמתו היה מבחי' כתר דמל' בחי' גלגלתא כו' ע\"כ אמר בחד קטירא אתקטרנא ביה אחידא כו' שהוא בבחינת התקשרות דרצון העצמי שלמעלה מן החכמה כו' ע\"כ היה בחי' התנשאותו בבחי' אלקות ממש דהיינו כמו בחי' התנשאות דכתר מל' למעלה וכמו התנשאות דוד המלך כו' וזהו בחי' התנשאות האמתית דבחי' יש האמתי מפני שהוא בחי' היש דקדושה האמתי מצד שהוא יש באמת בחי' מקורא דכולא וזהו כי גאה גאה גאות למעלה מגאות כי מ\"ש ה' מלך גאות לבש הוא רק לבוש מלכות בחינת התפשטות הארה בעלמא מגאות דיש האמתי מצד עצם רוממותו וזהו בחי' ס\"ג הב' שמקבל מס\"ג הא' וכידוע בענין אהיה אשר אהיה דכתר דס\"ג דבינה שרשו בכתר הכללי כו' וע\"כ תרגומו גאה על גיוותניא שהוא בחינ' המנגד להשפיל בחי' גאות דקליפה שזוהי בחי' חוצפה שלמעלה מן הטע' ג\"כ אבל היא מלכותא בלא תגא בלא כתר מפני שאין בהתנשאות זאת רק חוצפה כמ\"ש אם תגביה כנשר כי אין בחי' הארה והשפעה כלל במלכות דקליפה ונק' אין ואפס כמ\"ש כל הגוים כאין נגדו כו' והיינו ג\"כ ענין בחי' ס\"ג דמלכי' דתהו ששרשן בבחי' כתר מלכות אנא אמלוך כו' שבבחי' יש האמתי דעצמות אא\"ס שלמעלה מן החכמה לגמרי כו' וד\"ל:\n(סב) <b>וזהו</b> אשירה לה' כי גאה גאה סוס ורוכבו רמה בים פי' ע\"י בחי' ב' גאות והתנשאות שבקדוש' האלקית הנ\"ל שהוא ב\"פ ס\"ג אהיה אשר אהיה כו' כנ\"ל עי\"ז נשפל סוס ורוכבו כו' שהן ב\"פ ג\"ס דקליפה גי' סו\"ס כנ\"ל וזהו סוס ורוכבו שהוא בחי' מל' דקליפה כמו בקדושה דכתיב וסוס אשר רכב עליו המלך כו' כנ\"ל והיינו דוקא ע\"י בחי' התנשאות דיש האמתי שנק' גאה גאה עי\"ז דוקא סוס ורוכבו דקליפ' רמה בים למטה מטה בנוק' דתהומ' רבה כמ\"ש קפאו תהומות כו' וכמ\"ש אם תגביה כנשר כו' משם אורידך אורידך דוקא וכמארז\"ל כל המגביה עצמו הקדב\"ה משפילו כו' לפי שלגבי בחי' התנשאות דיש האמתי מקורא דכולא בחי' עצמות אא\"ס אין מקום כלל לבחי' התנשאות דקליפה שהוא חוצפה שבלא טעם מלכותא בלא תגא כו' וממילא יפול וכמ\"ש קומה ה' ויפוצו אויביך כו' וע\"כ נאמר בעמלק ראשית גוים אבל ואחריתו עדי אבד בתכלית הירידה שאין לה עליה כמ\"ש משם אורידך כו' ומ\"ש מבני בניו של המן כו' היינו בבחי' גאות וחוצפה שמצד הטעם שיש לה בירור בקדושה בהתנשאות אלקית דהגבהת הלב בדרכי ה' כנ\"ל אבל בחי' חוצפה שלמעלה מן הטעם אין לה תקון כלל רק אבוד ממש כי בקדוש' ה\"ז בבחי' התנשאות דיש האמתי ואין זה בקליפה כלל מאחר ששרשו אין ואפס כו' כנ\"ל וד\"ל (וזהו הענין שיתבאר בסמוך דכתר מל' לא ניתן ע\"י המן רק בעטרה שעטרה לו אמו כנ\"י דוקא כו'):\n(סג) <b>וזהו</b> ויקח המן את הלבוש ואת הסוס כו'. דהיינו בחי' המן דקליפה לאחר הברור בקדושה שנעשה מב' פעמים ג\"ס הנ\"ל ב\"פ ס\"ג דקדושה שזהו גי' סוס ע\"כ שני הדברים הללו ע\"י המן א' בחי' לבוש מלכות דקדושה שהוא מ\"ש ה' מלך גאות לבש בבחי' התפשטות ההתנשאות להיות מלך על עם כו' למטה שלמטה מבחי' התנשאות עצמותו מצד העצמות שמרומם לבדו ומתנשא מימות עולם לגמרי גם מהיות להם בחי' ראש ומלך כו' אלא שנתלבש"],[2201340150,"בבחי' צמצום דבחי' מל' כידוע והוא הנק' בחי' מל' דא\"ס שמאיר להיות בבחי' לבוש מל' (הגם שהוא בחי' מקיף לד' עולמות בשוה כנ\"ל. מ\"מ אינו רק הארה בעלמא מעצמות אא\"ס ממש כמו שהוא לפני הצמצום ומק\"פ כו' כי רק אפס קצהו מתלבש בבחי' לבוש כמ\"ש עטה אור כשלמה שזהו ה' מלך גאות לבש כו') ואף ע\"פ שמבואר למעלה שבחי' לבוש מל' זה הוא למעלה מבחי' חכמה דאדם ע\"כ הוא מקיף ע\"ג הראש כו' והרי יוכל להיות ע\"י ברור המן דקליפה כשמתברר גם בחי' חוצפה וגסות שלמעלה מן הטעם שבקדושה הוא בחי' הבטול שלמעלה מן הטעם שזהו ע\"י בחי' נעשה ונשמע כנ\"ל שעי\"ז נעשה גם בחי' כתר מל' וא\"כ הרי יש ברור ותקון גם לבחי' חוצפה שלמעלה מן הטעם וגם ע\"י בחי' ברור זה יוכל להיות בחי' עטרה וכתר מל' וא\"כ למה לא נתן המן גם הכתר מל' בראשו וה\"ז סותר לענין הנ\"ל בב\"פ ס\"ג וגס כו'. אך שרש הדברים הוא שיש ב' מיני בירורים הא' ברור להפך לכשנגדו שישתנה ממהותו כמו להפוך מרירו למיתקא ע\"י רבוי מים מתוקים שאז טעם המר נעשה בטעם אחר שהוא טעם המתיקות אבל טעם מרירות מצד עצמו רע הוא וכן כשנהפך רע לטוב הרי נעשה הרע מהות אחר שהוא במהות בחי' הטוב אבל מציאות הרע כמו שהוא בלא תקון רע הוא משא\"כ כשהרע עצמו כמו שהוא אינו רע כלל ולא שנהפך לטוב וע\"ד שא' זדונות נעשין לו כזכיות. זדונות כמו שהן וכן טוב מאד זה מ\"ה כו' וכן בענין היש וגסות כשנהפך למהות אחר שהוא מהות הבטול הרי מהות הישות וגסות כמו שהוא נשאר בבחי' רע ופרוד ח\"ו כו' משא\"כ כשהישות והגסות והתנשאות כמו שהוא איננו בבחי' רע ופרוד כלל שזהו כמו הרע עצמו שאינו רע כלל ולא שנהפך ממהות למהות כו' וגם כאן יש ב' אופנים א' חוצפה וגסות שבלא טעם כשנהפך למהות דבחי' בטול שלמעלה מן הטעם המנגדו ממש אבל מהות החוצפה זו עצמה כמו שהיא נשאר עדיין בבחי' גסות ופרוד כו' משא\"כ כמו ברור הב' דרע כמו שהוא במקומו אינו רע אלא טוב ולא שהוא במהות דבחי' טוב אלא במהות עצמו דוקא כו' גם כאן צ\"ל שבחי' חוצפה זו עצמה כמו שהיא במהות' נעשה בבחי' הקדושה שהוא בבחי' התנשאות אלקית בהתנשאות דוקא ולא בבחי' בטול וזה א\"א לומר בקדושה כלל מאחר שההתנשאות האמתי היא להיותה בחי' יש האמתי כו' שזה לא נק' חוצפה כלל כו' וד\"ל וע\"כ א\"א להיות בחי' כתר מל' למעלה שהוא בחי' ההתנשאות האמתי דיש האמתי רק ע\"י ישראל בבחי' בטול שלמעלה מן הטעם שמגיע מזה לעורר לבחי' התנשאות שמצד עצמו דוקא שלמעלה מבחי' התנשאות דלבוש מל' כנ\"ל אבל בחי' לבוש מל' יכול להיות ע\"י בחי' בירור דהמן כמו שהוא דוקא שהוא ההתנשאות בטעם ודעת כמו שמורכב בטעם גדולת המלוכה ועושר וכבוד כו' וגם בחי' סוס אע\"פ שהוא ב\"פ ג\"ס מ\"מ הרי הוא בא למטה בבחי' ס\"ג הב' ע\"י הוי\"ו שבסוס כנ\"ל שזהו בחי' יש וגסות המורכב בטעם רק שנמשך מגס שלמעלה מן הטעם כו' וע\"כ גם בחי' סוס אשר רכב עליו המלך להיותו בא למטה כו' נמשך ג\"כ ע\"י בחי' המן לאחר הברור (דהיינו בחי' ברור הב' הנ\"ל כמו שהוא במהותו כו') אבל בחי' כתר מל' בראש המלך שהוא בחי' התנשאות עצמותו אין זה בקליפה כלל שיוכל להיות ע\"י גם לאחר שיבורר במקומו רק בחי' חוצפה שלמעלה מן הטעם ואין זה שייך כלל בבחי' הקדושה מטעם הנ\"ל):\n(סד) <b>והנה</b> כתיב וילבש המן את מרדכי כו' ויש להבין מה שייך בחי' הלבשה זו דלבוש מל' ורכיבה זו דסוס ובחי' כתר מל' למרדכי דוקא אך הנה פי' מרדכי כתרגום מר דרור מירא דכיא כו' והענין הוא שיש ב' מדרגות בבחי' מרדכי כי ידוע דבחי' מרדכי למעלה הוא בחי' פנימי' יסוד אבא שבו מלובש"],[2201340151,"פנימית יסוד דע\"י כו' והיינו ענין מר דרור דרור הוא ל' חרות והוא בבחי' עולם החירות חירות ממ\"ה כו' שהוא בחי' פנימית יסוד אבא בפנימי' יסוד אמא שנק' עלמא דחירותא יובלא עלאה ונק' ג\"כ יין המשומר ממגע עכו\"מ דהיינו מיניקות החיצונים שאין שם שרש ליניקת חצונים כלל וכלל והענין הוא כידוע דשרש מציאות ז' מדות רעות דקליפה למטה הוא מצד בחי' השבירה בז' מלכי' דתהו כמ\"ש וימלוך וימת כו' וידוע שהשבירה לא היתה רק בבחי' ס\"ג אותיות ג\"ס והיינו דוקא בבחי' ס\"ג דס\"ג אבל לא בבחי' ע\"ב דס\"ג שזהו בחי' חכמה שבבינה כמאמר הבן בחכמה וחכם בבינה שבחי' פנימית בינה הרי הוא בחי' עומק המושג שנק' עמקות בינה דלא קימא לשאלא כו' שזהו למעלה מבחי' חצונית ההשגה שמוליד המדות וכמ\"ש במ\"א באריכות ובחי' פנימית בינה זו נק' מי אותיות ים שמקבלת ומתיחדת בבחי' פנימית יסוד אבא כו' וידוע שבחכמה לא היה בחי' שבירה כלל וכמ\"ש ימותו ולא בחכמה כו' כי חכמה כח מה בחי' הבטול שזהו הפך בחי' היש דבינה שמזה היה סבת השבירה והנפילה להיות בבחי' יש גמור כו' וע\"כ בחי' ס\"ג דס\"ג זה בירידתו למטה מטה הוא שרש לבחי' סוס דקליפה למטה ב\"פ ג\"ס שהוא תכלית הגסות כו' וד\"ל. אבל בבחי' ע\"ב דס\"ג דבינה ג\"כ למעלה מבחי' השבירה והנפילה דז' מדות כו' ע\"כ נקרא עלמא דחירות בחי' יובלא עלאה שאין שם מקום ושרש לרע וכמ\"ש לא יגורך רע כו' והוא יין המשומר ממגע עכו\"מ והיינו חירות ממ\"ה כמו לעתיד ממש שיבולע המות לנצח משום דואת רוח הטומאה אעביר כו' וע\"כ נאמר אז לא ירעו ולא ישחיתו כו' וגר זאב עם כבש כו' וכמ\"ש במ\"א בענין תבת נח כו' וד\"ל:\n<b>ואמנם</b> אין זה רק מצד הארת אין וכח מה דשם ע\"ב דאור אבא שמאיר בפנימית אור אמא שהוא בחי' ע\"ב דס\"ג מפני בחי' היחוד שלהם בבחי' הפנימית דוקא וזהו בחי' מרדכי כמו תרגום דמר דרור דהיינו כמו שהארת פנימית יסוד אבא באמא באצי' עדיין שבו בחי' פנימית יסוד ע\"י כו' אשר ע\"כ גזרו או' דיעקב אבינו לא מת כו' וד\"ל:\n(סה) <b>והנה</b> בחי' ומדרגה הב' במרדכי הוא מה שתרגומו של מר דרור הוא מירא דכיא שזהו בחי' יסוד אבא זה עצמו כשיורד ונשפל יותר למטה מטה עד בחי' היכלות דנגה דבי\"ע לברר ברורים ע\"י תו\"מ לאהפכא מרירו למתיקו כו' שזהו משום דבחכמה דוקא אתברירו וע\"ז נא' הנה ה' יוצא ממקומו שיסוד אבא יוצא מהיכל אמא הפנימי' הנ\"ל לחוץ ממש בנגה דבי\"ע לברר כו' (אשר אין זה בכח אמא עצמה כמ\"ש במ\"א) והיינו שרש ענין חכמה שבתורה שירדה למטה מטה כ\"כ בדברים גשמיים להבדיל בין טמא לטהור כו' כשר פסול כו' שזהו עיקר ענין הברורים דנגה דעשיה כידוע וזהו שנק' מירא דכיא כי דכיא הוא תרגום של טהור בלה\"ק כידוע ומשום שבחכמ' אתברירו לטהר ולהעלות לרפ\"ח ניצוצות שנפלו ע\"י השבירה שבבחי' ס\"ג כו' ע\"כ נק' דכיא ומה שנק' מירא דכיא ל' מרירות לפי שמתלבש בדכיין ומסאבין שאין טהור אלא כשיוצא מגדר הטומאה כידוע והמסאבין המה בחי' כתרין דמסאבותא שעליהם או' אשכלות מרורות למו בחי' גבורות הקשות בתכלית כו' וזהו ששה חדשים בשמן המור דמר דרור ומירא דכיא הנ\"ל שמתלבש למט' לברר ברורים דנוגה דוקא וכמ\"ש חכמות בחוץ תרונה ח\"ע שנמשך בח\"ת לברר ברורים בחוץ כו' (וכמ\"ש במ\"א לפי שבאמת בחי' כח ירידת ח\"ע ממקומו בהיכל אמא למטה לברר לבחי' נגה שנק' מירא דכיא ה\"ז למעלה מעלה גם מבחי' יסוד אבא למעלה שנק' מר דרור כי זה היכולת והכח לירד למטה כ\"כ ולברר ולהפוך חשוכא לנהורא כו' הוא בהכרח ממקום עליון יותר מגופה של חכמ' עלאה כמו"],[2201340152,"שהיא במקומה באצי' עדיין וכמ\"ש במ\"א באריכות שכח המברר דחכמה עושה בחי' תוס' אור בחכמה עצמה כמשל מי שחכמתו עמדה לו לתקן איזה דבר שנתקלקל או שיוכל לתקן המעוות והטעו' שנפל או שימציא טרף מזונו כו' זה בא מכח ומקור של חכמתו העצמית כו' וד\"ל וע\"כ מכריזין בג\"ע אשרי מי שבא לכאן לג\"ע ותלמודו בידו שהן ההלכות שהלך ויצא ה' ממקומו בפנימית היכל אמא לברר למטה כו' שבעבור זה יתוסף אור בנשמתו להשיג בכחו יותר מזיו השכינה כו' וד\"ל:\n(סו) <b>וזהו</b> ג\"כ מ\"ש כל הנביאים עתידין להבטל חוץ ממגלת אסתר וכן ההלכו' שהוא בחי' אסתר ומרדכי (כמ\"ש למעלה באריכות בענין מרדכי ואסתר מן התורה מנין כו') כי הנביאים שרשן רק בבחי' נו\"ה המאירי' במל' לפי שעה באותו הזמן שכנ\"י בגלו' כו' משא\"כ ההלכות שבחכמה אתברירו כל משך זמן הגלות ששרשן למעלה מן החכמה עצמה מטעם הנ\"ל וד\"ל וכמו\"כ זהו ענין מ\"ש אסתר מן התורה מנין שנא' ואנכי הסתר אסתיר פני כו' כי הנה ידוע כי בחי' מל' דאצי' מסתתרת בראש הבריאה והיינו מה שבחי' מלכות דאצי' נעשה בבחי' ע\"י לבריאה בבחי' כתר והעלם שנק' הסתר וזהו הנק' אסתר אך א' דאסתר ל' להבא כמ\"ש אסתיר פני ביום ההוא הענין הוא דלעתיד כתיב הנה אלקינו זה שבחי' בינה הנק' אלקינו יבא לידי גלוי ונק' זה והיינו ההתגלות מעלמא דאתכסייא כו' מן העולם ועד העול' אך זהו רק בחי' בינה דבריא' למל' דבריאה וכה\"ג אבל בחי' ע\"י דבריאה ע\"ז א' אסתיר פני ביום ההוא דבינה כו' כי בחי' ע\"י שבבינה לא יתגלה גם לעתיד שיאמרו אלקינו זה כו' וזהו אסתיר פני ביום ההוא בחי' הפנימית שבמל' דאצי' שהן שרש הע\"ס דמל' דאצי' כמו שהיא מקבלת מבחי' ע\"ס דאצי' עצמן כידוע דמבחי' מל' שבכתר דאצי' נמשך בחי' כתר שבמל' דאצי' ומבחי' מל' שבחכמה דאצי' נמשך בחי' חכמה שבמל' דאצי' וכיוצא בזה בכל פרטי האורות דמל' כו' וכ\"ז לא יבא לידי בחי' גלוי לעתיד גם לאחר שיהי' בחינת אלקינו זה גלוי אור הבינה במל' וזהו ענין א' דאסתר כו' שגם לעתיד תהיה בהעלם דהיינו גם ביום ההוא אסתיר פני כו' וזהו שרש ענין אסתר מן התורה כו' וד\"ל:\n(סז) <b>ולהבין</b> באור זה בהיות ידוע שהעוה\"ב שרשו בבחינת בינה כי ביו\"ד דחכמה נברא העוה\"ב מאין ליש וז\"ש להנחיל אוהבי יש שהוא בחי' בינה שהיא בבחי' יש דהשגה אך לא בחי' יש גמור שהוא בחי' ס\"ג אלא בחי' יש שבא מצד בחי' התענוג המאיר בהשג' דוקא שהרי עיקר התענוג מן השכל הוא כשמשיגו דוקא וזהו הנקרא התגלות ע\"י בבינה דוקא שזהו ענין גלוי התענוג שלמעלה מן החכמה שמאיר בגלוי בבינה והשגה יותר מבחכמה כמ\"ש במ\"א וזהו שרש ענין העוה\"ב שהנשמות נהנין בהשגה בתענוג מורגש בבחי' יש דוקא אך בחי' תענוג מורגש זה אינו בחי' יש גמור כי מאחר שמתענגים על ה' בבחי' העונג האלקי ה\"ז בחי' בטול וכלות הנפש בתענוג זה כו' וע\"כ ה\"ז התענוג דומה קצת לבחי' התענוג העליון הפשוט כמו שהוא למעלה מן החכמה שהוא בבחי' יש האמתי כו' ולמעלה מעלה נקרא בחי' שעשועי המלך בעצמותו כו' ולמטה נקרא בחי' עתיק דבריאה שקצת הארה ממנו מתלבש ומתגלה בבינה דבריאה כו' וז\"ש אהיה אשר אהיה כו' והנה מאחר שהנשמות שהן מבחי' עלמא דאתגליא מאין ליש גמור נהנין בבחי' הענג העליון שבבינה שהוא ענין העוה\"ב כנ\"ל הרי האור נמשך מבינה למל' שהוא מן העולם ועד העולם מעלמא דאתכסיא לעלמא דאתגליא וזה שאמר הנה אלקינו שבבינה עלמא דאתכסיא בא לידי גלוי בבחי' זה לנוכח כו' והטעם שנקרא אתכסיא לפי שזהו בבחי'"],[2201340153,"פנימית בינה שנקרא עולם החירות כנ\"ל שהוא למעלה מבחי' חצונית בינה בחי' ס\"ג דס\"ג אלא הוא בחי' ע\"ב דס\"ג כנ\"ל ומה שהעוה\"ב נקרא יש אינו מצד ההשגה כי שם הוא למעל' מן ההשגה רק בחי' עומק המושג כו' אלא מצד התענוג המורגש בבחי' יש כנ\"ל וד\"ל וזהו ענין מרדכי ואסתר מרדכי הוא בחינת פנימי' יסוד אבא דבריאה או דאצי' שהוא פנימי' יסוד ע\"י כנ\"ל ואסתר הוא בחי' פנימית אמא דבריאה או דאצי' שבה מוסתר בחי' עתיק דבריאה או דאצי' אך מה שנק' אסתר אע\"פ שאדרבה שבחי' ע\"י מתגל' דוקא בבינה שהוא העוה\"ב כנ\"ל הענין הוא דהגם שבחינת ע\"י מתגלה בבינ' אין זה רק בבחי' ההשגה הבאה לנשמות שיהיו נהנין כו' אבל אין זה רק קצת הארה בעלמא מבחי' הארת עצם התענוג הפשוט שמוסתר ונעלם הוא לעולם גם בהיות בחי' ההתגלות דע\"י בבינה כמו בעוה\"ב שיהיה אלקינו זה כו' וזהו אסתיר פני ביום ההוא פי' גם ביום ההוא שנקרא אתכסיא ועתיד להגלות בחי' הארת ע\"י שבאה לנשמות בעוה\"ב גם אז יהיה מוסתר בה בחי' אור עצם התענוג הפשוט שנקרא בחינת עתיק דבריאה או דאצי' והוא הנקרא בחי' סתימא דכל סתימין שגם מן סתימין הוא סתום ונעלם דהיינו גם מבחי' פנימית או\"א שבינה ג\"כ נק' אתכסייא להיות' למעלה מבחי' השגה כנ\"ל וכן בחי' פנימית אור אבא בחינת מרדכי כו' גם מהן נק' סתימא שהרי לעתיד שיהיה גלוי ההעלם דבינה במל' מ\"מ יהיה אורו מוסתר ביום ההוא דבינה כו' משום שבחי' עצמות התענוג כמו שהוא נבדל הוא בערך מן החכמה ובינה כו' דאפי' אור צח כו' אוכם הוא לגבי עה\"ע ולית מחשבה תפיסא ביה אפי' מחשבה וחכמה הקדומה כו' מפני שאין תענוג פשוט זה מורכב בבחי' חכמה וטעם כלל וכלל כמ\"ש במ\"א וד\"ל:\n(סח) <b>וזהו</b> שאמרו כל הנביאים עתידין להבטל חוץ ממג\"א כו' וכן ההלכות שהוא בחי' מרדכי כו'. כי הנה בחי' אסתר שמסתתר בבריאה שנק' ע\"י דבריאה שרשה הוא בחי' עתיק דאצילות כו' וזהו ענין אסתיר פני כו' וכמ\"ש ופני לא יראו שנקרא סדכ\"ס לפי שבבחי' מל' דאצי' הרי בחי' כתר שבה שנק' כתר מל' והוא בחי' ע\"י דבריאה שרשו מבחי' מל' שבכתר דאצי' הנק' עתיק דאצי' וע\"כ נק' בחי' פני' לגבי האור דט\"ס הנמשך מבחי' מל' דאצי' בבריאה וכמו\"כ נקרא פני' בבחי' כתר דעתיק דאצי' מפני שבחי' מל' דא\"ס ג\"כ כלול מי\"ס ובחינת הכתר שבו ג\"כ כלול מי\"ס ובחינת מלכות שבכתר שבו נעשה בחינת כתר דעתיק דאצילות כמו שמבחינת מל' שבכתר דאצי' נעשה בחי' כתר מל' דאצי' בבריאה כו' (ומה שבחי' מל' דכתר נק' פני' היינו משום דנעוץ תחלתן בסופן דמל' שבכתר הוא מחשבה דאנא אמלוך שעלה ונכלל ברצון ותענוג הפשוט כו' והוא שנעשה רצון בגלוי למלוכה כו' וד\"ל) וזהו כל הנביאים בחינת נו\"ה שבכל פרצוף עתידים להבטל כי עכשיו מבחי' נו\"ה שבעליון משפיע למל' כמו מבחי' נו\"ה דז\"א למל' וכמו\"כ מבחי' נו\"ה דכתר וע\"י באו\"א כו' אבל לע\"ל יהיה עליית המל' בכתר ולא תקבל מנו\"ה דז\"א וכמו\"כ בחי' או\"א לא יקבלו מנו\"ה דע\"י כו' אבל אסתר לא תבטל כי תתעלה בבחי' כתר וע\"י עצמו שנקרא סדכ\"ס ע\"כ נק' אסתר אסתיר פני כו' וענין בטול הנביאים דנו\"ה היינו שיסתלקו למעלה כי מאחר שלא ישפיעו למטה ע\"כ ממיל' בטלים ונכללים בגופו של המשפיע שהרי נק' ירכין כו' וכמו ענין אם תשיב משבת רגלך שהוא בחינת הסתלקות נה\"י משום שנאמר אל יצא איש ממקומו כו' כמ\"ש בלק\"ת וד\"ל. וכן ההלכות שהן בחי' מרדכי כנ\"ל. כי הנה במרדכי נאמר ויהי אומן את הדסה היא אסתר בת דדו כו' דהיינו מה שבחי' ח\"ע פנימית יסוד אבא יוצא ממקומו באצי' למטה בבריאה כו' שנקרא אסתר שמסתתרת שם כו' ונק' הדסה כמו"],[2201340154,"שושנה בין החוחים כו' וע\"י בחי' הבירורים שבח\"ע מתברר בחי' מל' בחי' ב\"ן. דמ\"ה מברר ב\"ן היא בת דדו ששרשה בבחי' ע\"י מבחי' מל' שבכתר וע\"י כנ\"ל שהח\"ע מאין תמצא ג\"כ משם כנ\"ל ולפי שע\"י הברורים דח\"ע יש עלייה לח\"ע למעלה ממקומו כנ\"ל באריכות והוא בבחי' פנימית ע\"י שאא\"ס מאיר שם ע\"כ אין לו בטול כו' והיינו שההלכות דוקא אין להן בטול שזהו מה שח\"ע מלובש בדברים גשמיים כו' וזהו שנקרא מר דרור למעלה ומירא דכי' למטה כנ\"ל הכל ע\"י בחי' הברורים כי מר דרור הוא בחי' העוה\"ב עולם החירות כנ\"ל בחי' יובלא עלאה שאין זה רק לנשמות שהיו בבחי' הברור בעוה\"ז ע\"י תו\"מ גשמיים כו' וד\"ל:\n(סט) <b>וזהו</b> מה שנקרא אמן את הדסה כו' דהיינו מה שמברר ומעלה לכל הנשמות שנק' הדסה בפרט וכמ\"ש ובזה הנערה באה אל המלך שהוא בחי' עלית הנשמה הנק' נערה ופי' ובזה היינו על ידי העמוד המחבר מעלה ומטה הנערה באה כו' והוא כאשר ששה חדשים בשמן המור שהוא בחי' גבורות דאבא כי שמן הוא בחי' ח\"ע שמוכרח לצמצם ולעיין בכח הדין שבחכמה איך להעלות ולתקן שזהו בחי' גבורות שבחכמה דוקא וששה חדשים בבשמים כו' היינו בחי' גבורות דאמא כמ\"ש אני בינה לי גבורה כו' והסיכה שתסוך הנשמה האלקית בשמן המור שהוא בחי' גבורו' דאבא מעלה ריח חזק בבחי' הגבורות שתוכל להעלות עי\"ז וטעם לששה חדשים דוקא היינו לנגד ו' מדות שבה שתטהרם מכל סיג שנפל מצד השבירה כו' וששה חדשים בבשמים בבחי' ריח הנכנס בתוך הגוף וכמ\"ש וריח אפך כו' נרד וכרכם כו' וסיבת שמן המור הוא בבחי' מקיף דחכמה כמו ידי נטפו מור כו' שפתותיו כו' נוטפות מור כו' והבשמים הם בחי' או\"פ דבינה שהנשמה נהנית ממש מן הריח כו' והוא בחי' גבורות דאמא (וששה חדשים היינו ו' אלפי שנין שבח\"ע אתברירו כו' וששה חדשים בבשמים כו' הוא בג\"ע העליון שהנשמות נהנין כו' ובזה הנערה באה כו' באלף הז') וכאשר כל נשמה תהיה ו\"ח בשמן המור וו\"ח בבשמי' כו' ובזה הנערה באה כו' בזה הוא בחי' יסוד אבא שהוא העמוד שכלול י\"ב חדשים הללו שנקרא ז\"ה להיותו בחי' מחבר מעלה ומטה כי בכל העלאה וחבור שמתחתון לעליון הימנו יש עמוד המחבר עליון ותחתון והוא בחי' יסוד שנקרא צדיק יסוד עולם וכמ\"ש כי כל בשמים כו' דאחיד כו' כמו העמוד שמג\"ע התחתון לג\"ע העליון וכאשר הנשמה עולה ובאה דרך העמוד הזה אז נשכח ממנה כל בחי' התענוג האלקי שהיה לה בג\"ע התחתון כי כמו שיש נהר דינור שבו טובלין הנשמות לשכוח חיזו דהאי עלמא תענוג הגשמי כו' שאל\"כ לא יוכל לקבל ענג האלקי שבג\"ע התחתון כן יש עמוד שע\"י ישכחו הנשמות התענוג שבג\"ע התחתון וא\"ל לא יוכלו לקבל ענג העליון ממנו הרבה שבג\"ע העליון שהוא תענוג נפלא ביותר למעלה מעלה בערך מן התענוג שבג\"ע התחתון וכ\"ה עוד עליית הנשמות מג\"ע העליון לאצי' כמו מיכאל כה\"ג מקריב נשמות כו'. ובין כל תחתון לעליון הימנו יש בחי' עמוד שבו עולין כל הנשמות והיינו ובזה הנערה באה אל המלך כו' עד בחי' התענוג הפשוט שבעצמו' המאציל שמשם נמשך מקור כל התענוגי' העליוני' שבחכמה ובינה כו' וענין התענוג הזה שנמשך משם הוא הנקרא טעמי תורה וכוונת המצות וסודותיהן שבזה יתענגו בענג נפלא ועצום כמ\"ש ישקני מנשיקות פיהו כו'. ואמנם אין זוכים לקבל התענוג הנפלא הזה כ\"א שיוקדם להם תחלה ששה חדשים בשמן המור וו' חדשים בבשמים כו' שהוא בחי' מרדכי מר דרור כו' ומירא דכיא שהוא בחי' ההלכות הנגלות לנו שבח\"ע אתברירו לאהפכה חשוכ' כו' כנ\"ל שבזה דוקא הנערה באה וכמו שמכריזין אשרי מי שבא לכאן ותלמודו שלמד בעוה\"ז דוקא בידו שאז יוכל לקבל בחינת טעמי תורה כו' וע\"כ נקרא מרדכי אמן את הדסה כו' אשר ע\"כ אין ההלכות"],[2201340155,"בטלות לעתיד מפני שיהיה עליית העולמות עד אין שעור כמ\"ש ז\"ל ת\"ח אין להם מנוחה כו' בעוה\"ב שנאמר ילכו מחיל אל חיל כו' ובכל העלאה צריך לבחי' מרדכי שנקרא אמן את הדסה כו' שבזה דוקא הנערה באה עד רום המעלות בבחי' עצמות התענוג הפשוט כו' דהיינו מה שנקרא אסתר בחי' סדכ\"ס כמ\"ש אסתיר פני כו' הנה היא באה להכלל בעצמות כו' כידוע דנשמות ישראל עלו במחשבה הפשוטה כו' ולכך כל הנביאים יבוטלו רק אסתר ומרדכי לא יבוטלו גם בהגלות נגלות לעתיד מבחי' סובב הכללי כמ\"ש ונגלה כבוד ה' כו' משום דבחי' אסתר ומרדכי הן בבחי' העצמות שנקרא מאור ולא אור וכל אור יש לו בטול והתכללות כו' אבל בחי' מאור עצמו אין לו בטול והתכללות כו' וד\"ל:\n(ע) <b>ומעתה</b> יש להבין מ\"ש וילבש המן את מרדכי כו'. דהנה ידוע שבי\"א סממני הקטרת הנה י' סמנים הן להעלות הטוב שבי\"ס דקליפה והי\"א הוא הלבונה שהוא בחי' המקיף שלהם וכידוע שי\"א ארורים דקליפה מתבררים ע\"י י\"א סממני הקטרת אמנם בחי' הלבונה הוא בחי' מקיף שמאיר מן הקדושה עליהם והוא מה שאנו רואים שגם עכו\"מ יש להם האר' האלקית רק שמאיר על נפשם מרחוק ולא מקרוב וכמ\"ש רם על כל גוים כו' אתגאי על גיוותניא כו' והיינו מאי דקרו ליה אלהא דאלהיא שהגם שבקריאה זו אינם ממשיכים במוחם ולבם גלוי אלקות כלל משום דרק קרו ליה בדבור בלבד ועכ\"פ בבחי' ההודאה מודים הם כו' וההודאה הזאת ג\"כ אינה מאירה בגלוי רק בהעלם מאיר בנפשם כאדם המודה על דבר המופלא ונעלם הימנו הרבה שהגם שקורא בשמו מ\"מ מופל' הוא ונעלם מאתו כו' וכמ\"כ מאי דקרו ליה אלקא דאלקיא בבחי' אח\"פ ממש מ\"מ מופלא הוא ונעלם מהם לגמרי רק מ\"מ ענין בחי' הודאה זו היינו מפני הארת בחי' מקיף דקדושה עליהם והוא בחינת הלבונה כו' וד\"ל. וכמו\"כ יובן גם בבחי' לבוש מל' העליון שהוא בחי' הגאות והתנשאות האלקית דה' מלך גאות לבש נמשך בבחינת מקיף על כל פנים בהמן ג\"כ כשהוא לאחר הברור כמו בהגבהת הלב בדרכי ה' כו' שהוא בחי' הגאות שצריך גם ת\"ח כו' ומעטרא ליה כסאסאה כו' כנ\"ל וזהו שהלביש המן למרדכי כי המן נקרא ראשית גוים כו' שמקבל בבחי' מקיף וע\"כ ע\"י יוכל להיות בחינת המשכת לבוש מל' להלביש את מרדכי כו' וד\"ל:\n(עא) <b>אך</b> עדיין יש להבין מה צריך מרדכי דוקא לבוש זה וע\"י המן שהוא בחי' התנשאות כו' הענין הוא לפי ששרש מרדכי מר דרור ומירא דכיא כנ\"ל ה\"ז בבחי' פנימית ח\"ע כמו שהיא ממקורה בבחי' אין וכמ\"ש והחכמה מאין כו' וירידת ח\"ע למטה מטה לברר ברורים דנגה הוא בחי' מירא דכיא כנ\"ל אמנם הנה כדי שיהי' בכח ח\"ע להתצמצם ולירד כ\"כ למטה ולהיות לו כח ועוז גדול כזה לברר ולאהפכא חשוכא כו' והגם שהחכמה נקרא אור כידוע והאור מאיר הוא את החשך כו' היינו שנדחה החשך מפני האור אבל לא שיהפך החשך עצמו לאור כו' כי איך יהיה יכולת באור להפוך חשך לאור ובודאי אין זה רק מבחי' מקור האור שהוא בבחי' מקיף לאור דח\"ע ונק' מקיף דכתר בחכמה כו' וזהו בחי' מקיף דחיה בכלל והוא בחי' הלבוש שצריך מרדכי בחי' פנימי' יסוד אבא שע\"י דוקא יש בו כח לירד מטה מטה ולבר' וכמ\"ש או יחזי' במעוזי מעוזי מפעיל כי התורה עצמה נק' עוז כידוע ומעוזי בחי' מקיף דח\"ע כו' והוא בחי' לבוש מל' דא\"ס שמאיר בראשית הקו והחוט שנקרא אור כמ\"ש יהי אור כו' בבחי' מקיף ולבוש והוא הנמשך ע\"י בחי' המן דקדושה מטעם הנ\"ל וד\"ל:\n<b>וכן</b> סוס אשר רכב עליו המלך ג\"כ ע\"י המן שמרכיב למרדכי בחי' ח\"ע דהיינו שירד אור ח\"ע למטה מטה כ\"כ שהוא מעוצם ההסתר שבנוגה כו' אשר אין זה בכח"],[2201340156,"מרדכי מצד עצמו כי הוא רק בבחי' א' דחכמה יו\"ד וי\"ו יו\"ד שבא' אבל מבחינת מקיף הנעלם דיו\"ד דחכמה שהוא ס' דסוס שיבא למטה בסתר המדרגה כנ\"ל בענין ו' דסוס ב\"פ ס\"ג כו' איך יהיה ע\"י בחי' חכמה דמרדכי שם מ\"ה כו' אלא ע\"י המן דוקא ששרשו בבחי' מקיף דחכמה הוא המרכיב למרדכי על בחי' סוס אשר רכב עליו המלך להיות מגיע ע\"י סוס האור דח\"ע לברר למטה מטה ולהפך גם החשך לאור משום דס' הא' דסוס הוא מ\"ש ישת חשך סתרו שלמעלה מבחי' אור דחכמה ע\"כ בבאו למטה יוכל להפוך גם בחי' הסתר וחשך גמור דקליפה לאור כו' וז\"ש במ\"ת כי תרכב על סוסיך כו' כנ\"ל וע\"כ דוקא ב' דברי' הללו דלבוש מל' ורכיבת הסוס היו ע\"י המן שהוא דוקא המלביש לבוש מל' את מרדכי ומרכיבו על סוס אשר רכב עליו המלך בזמן מ\"ת להיות בח\"ע אתברירו גם עכשיו כו' ולפי שב' דברים הללו הן הן בבחי' מקיף ולבוש דחכמה כו' וד\"ל:\n(עב) <b>אך</b> מ\"מ עדיין יש להבין למה בחי' כתר מל' לא היה ע\"י המן מאחר דקרו לי' אלקא דאלקיא כו' אמנם הנה ידוע דבחי' הקו והחוט הוא שנמשך אחר בחי' הצמצום דמק\"פ שנקרא חשך סתרו והוא בחי' סתר להעלים עצמות אא\"ס אבל לאחר הצמצום והחשך נאמר מגלה עמקו' מני חשך והוא בחי' גלוי האור דקו הזה שהוא בא מבחי' פנימית ועצמות אא\"ס דוקא והיינו שבחשך סתרו נאמר אסתיר פני ואח\"כ בא לידי גלוי בקו וחוט כו' וא\"כ הגם שבחינת צמצום זה הוא בחינת מקיף והעלם דאור הקו כו' אבל שרשו של בחי' קו זה הוא למעלה מבחינת הצמצום הזה והוא בבחינת פנימית דאא\"ס כו' ומשם נמשך שרש כנ\"י שנקרא הסתר אסתיר פני כו' ע\"כ כל שאינו בהסתר פנים אינו מהם כי נתעלם האור תחלה ואח\"כ מאיר כו' והיינו בחי' כתר מלכות כי בחי' מל' דא\"ס שמאיר על הקו אחר הצמצום הרי מתלבש בבחינת לבוש והעלם כו' משא\"כ אא\"ס עצמו שלפני הצמצום שמאיר ובא בבחי' גלוי בקו כנ\"ל ומשם נמשך האור על בחי' העטרה וכתר שע\"ג ראש דא\"ק שהוא בראשית הקו כו' (ואע\"פ שמבואר למעלה דלבוש מלכות מלביש על העטרה וכתר דא\"ק או א\"א כו' אבל שרש בחינת המקיף דעטרה מאחר שנק' כתר מלכות הרי גם למעלה שרשו בבחי' כתר דמל' דא\"ס שהוא למעלה מבחינת לבוש מל' דא\"ס שמאיר אחר הצמצום בבחינת מקיף על הקו כו') ולפ\"ז אין כח להיות ניתן כתר מל' בראשו רק ע\"י ישראל דוקא מקדשי שמך במס\"נ כמו נעשה בבטול הרצון שלמעלה מן החכמה שבאור וקו כו' וזהו מפני שישראל עלו במחשבה הפשוטה שלפני הצמצום ואח\"כ יצאו לידי גלוי בבחינת קו שזהו מבחינת פנימי' ועצמיו' דאא\"ס דוקא כי חלק ה' עמו ממש ישראל עם קרובו כו' אשר אין שרש שם להמן כלל וכלל גם לאחר הברור שנעשה בבחינת הקדושה כמו בבחינת גבהות הלב בדרכי ה' כו' כי שרש המן אינו מגיע רק בבחינת מקיף דחיה שהיא החכמה אבל לא במקיף דיחידה (וכמ\"ש במקום אחר בענין בבואה דבבואה לית להו והלבונה הוא רק מקיף דחיה כו') אבל בחינת אמתת הבטול מכל וכל דכנ\"י הוא מגיע בבחי' מקיף דיחידה שלמעלה ה\"ז בבחי' אין האמתי שא\"א לבא לידי גלוי אור להיות מאיר בבחינת כתר ועטרה כו' כ\"א ע\"י תכלית הבטול ולא ע\"י בחינת יש וגסות כלל וכלל ותכלית הבטול אינו אלא בישראל דוקא מצד שרשן בבחי' העצמות ממש כנ\"ל והיינו בעטרה שעטרה לו אמו במ\"ת דוקא שהן כנ\"י שא' נעשה ונשמע ע\"י נעשה נמשך בחי' עטרה בבחינת גלגלתא שהוא שרש המצות כנ\"ל וע\"י ונשמע נמשך האור בבחי' מו\"ס שהוא מקור התורה כו' שזהו כללות הכתר שנקרא תר\"ך עמודי כו' שמחבר עצמות אא\"ס למטה מטה וזהו ואשר נתן כתר מלכות בראשו נתן כבר שזהו בזמן מ\"ת כמ\"ש וקבל היהודים את אשר החלו לעשות בזמן מ\"ת כנ\"ל וד\"ל:"],[2201340157,"(עג) <b>ולהבין</b> זה בתוספת באור הנה יש להקדים תחלה בשורש ענין המצות דהנה יש במצות ב' דברים הא' המצות עצמן דהיינו גופי הדברים שבהן נעשה המצוה כגון אתרוג שנעשה מצוה בלקיחתו אותו מן האילן לשם מצוה גם טרם שקיים בו המצוה בפ\"מ בנטילתו ולקיחתו עם הלולב בזמנו וכן קלף של תפלין שנקרא מצוה כשנכתבו בו ד' פרשיות וכו' גם בטרם שמקיים מצות תפלין בהנחה וכן צצית של צמר קודם שלובשו וכה\"ג הרי הדברים הללו שנתקדשו למצוה שהוא כמו פרי האתרוג וקלף וצמר גשמי דבחי' נגה הוא בבחי' יש נפרד כידוע והנה ידוע שבחי' התהוות היש בכל השתלשלות עו\"ע שבבחינת ממלא שם מאיר מבחי' סובב דוקא כמ\"ש למעלה דהיינו מבחינת המקיף שמקיף לד' עולמות בהשוואה אחת וכמ\"ש למעלה בענין כי הוא צוה ונבראו כו' כמו ויאמר אלקים יהי אור הגם שאותיות יהי אור מהוות את האור אבל אין זה רק בחי' חיות הרוחניות דאור אבל מציאותו הגשמי בבחי' יש גמור נתהווה ע\"י הצווי דויאמר אלקים כו' כמ\"ש כי הוא צוה כו' וזהו ויהי אור שכן היה כמו שצוה ועד\"מ מלך שמצוה וגוזר שאין בצווי זה בחי' המשכת כחו ופעולתו רק בחי' צווי בדבור בהאר' בעלמא מרחוק בהעל' כי אינו רק צווי בעלמא רק שזה הצווי בא מבחי' ההתנשאות דמלוכה שהמלך יגזור ויקום כן כדבריו וזהו ויהי כן משא\"כ בלא בחי' התנשאות דמלוכה אין הצווי כלום כו' ומאחר שאין זה רק צווי בעלמא הרי צווי זה שוה בכל התהוות העולמות באין הפרש בין עליון לתחתון רוחניות וגשמיות שוין בזה כמו שאין הפרש בין כשמצוה המלך לעשות דבר גדול ביותר בין כשמצוה לעשות דבר קטן הכל אינו רק בבחי' צווי בעלמא שבא מצד בחי' ההתנשאות ומאחר שהוא מתנשא מכולם בשוה קטן וגדול שוין לענין הצווי שלו כו' וכמ\"כ למעלה במ\"ש כי הוא צוה ונבראו כל העולמות עליונים ותחתונים רוחניות וגשמיות ואין הפרש כלל ביניהם בענין צווי זה מאחר שבא מרחוק על כולם בשוה ממש לפי שהוא המלך המרומם המתנשא מימות עולם לגמרי כמ\"ש קטן וגדול שם הוא וכן כתיב כחשיכה כאורה כו' עד שגם הקליפות הטמאות גם הם מקבלים מבחינת צווי זה להיות בבחינת יש נפרד גמור כו' והוא בחינת הארת הסובב המקיף לד' עולמות בשוה להיות בבחינת יש לכולם מאיר בשוה וכמ\"ש כל אשר חפץ ה' עשה בשמים ובארץ בשוה כו' וז\"ש את השמים ואת הארץ אני מלא דלית אתר פנוי מניה כו' הכל בהשוואה ממש מטעם הנ\"ל וד\"ל אך הנה בחינת צווי זה הוא רק בחי' חצוניות הארה בעלמא כנ\"ל הגם ששרשו בבחינת רצון כמ\"ש כל אשר חפץ ה' עשה כו' ורצון זה בא מצד בחינת ההתנשאות דמלוכה כי משום שאין מלך בלא עם כו' ולמעלה היינו בחינת סובב כ\"ע שמתנשא מימו\"ע ונקרא בחינת לבוש מל' שהוא אשר עלה במחשבה הקדומה אנא אמלוך כו' אך פנימית רצון זה דמלוכה זה הוא מפני שנתאוה הקב\"ה להיות לו דירה בתחתונים דוקא שהן ענין המצות מצד עצמן כנ\"ל כמו בחי' רצון העליון המלובש במצות אתרוג דהגם ששרש התהוות היש דאתרוג בא מבחינת סובב אבל אינו רק בהעלם ובחצוניות כנ\"ל אבל בבחינת רצון העליון שבו כשנתקדש למצות אתרוג מאיר בו בגלוי מבחינת לבוש מלכות מבחינת הפנימית שבו כו' וכ\"ה בכל הדברים שבהן נעשה המצוה שהן בבחינת יש דנוגה כו' וד\"ל אבל מדרגה הב' במצות היינו ענין קיום המצות אשר יעשה אותם האדם בגופו ובמאודו כמו שלובש צצית ומניח תפלין וכה\"ג שמבטל רצונו מפני רצון העליון ובחי' בטול זה שלמעלה מן הטעם והמוחין ממשיך מלמעלה ג\"כ בחי' הרצון הפשוט שלמעלה מבחי' מו\"ס שהוא ענין בחי' עטרה שע\"ג הראש כו' ששם הוא ההארה מבחינת עצמות אא\"ס ממש שלמעלה גם מבחינת פנימית"],[2201340158,"המחשבה דאנא אמלוך כו' שהוא מה שנתאוה להיות לו דירה בתחתונים שאין זה רק לפי מדרגת אור אותו רצון העליון המלובש במצוה זו משא\"כ ענין בחי' קיום המצו' מצד בטול הרצון כנ\"ל ע\"ז אמרו נח\"ר לפניו שאמר ונעשה רצונו כו' וזהו למעלה מבחי' הרצון העליון שבמצוה שע\"י זה נעשה לו דירה והשראה למטה כו' וזהו בחינת העטרה שעטרה לו אמו בזמן מ\"ת ע\"י ישראל כשאמרו נעשה ונשמע כנ\"ל וד\"ל:\n(עד) <b>ולהבין</b> זה בתוספות באור יש להבין תחלה בענין הנ\"ל במ\"ש כי הוא צוה ונבראו כו' דלכאורה יש סתירה לזה מ\"ש בדבר ה' שמים נעשו וברוח פיו כל צבאם הרי גם התהוות בחי' היש דשמים הגשמיים נעשה ונתהווה מבחינת דבר ה' דוקא שהוא בחינת האותיות האלקיים הנמשכים בבחי' ממלא דוקא בתוך כל נברא כמו כח הפועל בנפעל כידוע ואם נאמר שדבר ה' זה הוא צווי דבר מלך כמו דבר מלך שלטון שהמלך בדבורו גוזר ואומר ונעשה כדבריו וכן דבר ה' גזר שיהיה בחי' התהוות שמים גשמיים כמ\"ש ויאמר אלקים יהי רקיע כו' ויהי כן והיינו מ\"ש כי הוא צוה ונבראו כנ\"ל ואין פסוק זה דבדבר ה' שמים נעשו עשיה גשמית סותר כלל למ\"ש כי הוא צוה כו' אבל סיפא דקרא זה ודאי סותר שהרי אמר וברוח פיו כל צבאם הרי רוח פיו זה אינו רק הבל בעלמא ואותו בחי' רוח וההבל האלקי שנקרא רוח פיו ית' הוא המהווה לכל צבאם ועל בחי' רוח והבל זה לא שייך לומר שהוא בחינת צווי כמאמר הדבור אלא הוא רק הבל הדבור בלבד וא\"כ ודאי סותר למ\"ש כי הוא צוה כו' שהוא מבחי' סובב כנ\"ל וההבל ורוח פיו ודאי בא בבחי' ממלא וא\"כ גם רישא דקר' במ\"ש בדבר ה' שמים נעשו ודאי הכוונה על בחי' אותיות דבור העליון מצד עצמו כמו מאמר אותיות יהי אור מהווה האור ואותיות דמאמר יהי רקיע מהווה רקיע ולא מצד בחי' הצווי שבדבור ומאמר זה כדי שלא יקשה רישא לסיפא וד\"ל:\n(עה) <b>אך</b> הענין יובן בהקדמה א' הידוע שבכל דבר יש בחינת חומר וצורה שנקרא אור וכלי שזהו כמו נפש וגוף ממש וגם בשמים וארץ וכל צבאם יש בכ\"א מפרטי הנמצאים בחי' חומר וצורה ואין התהוות החומר והצורה ממקור ושרש א' אלא התהוות הצורה שהוא בחי' האור והחיות הרוחנית שלו ממקור מיוחד שהוא מקור אל כל בחי' ההשתלשלות בבחי' הרוחניות והוא מ\"ש כלם בחכמה עשית שזהו בחי' חכמה שבדבור העליון בי' מאמרות וכמו במאמר יהי רקיע הרי בחינת החכמה שבאותיות וצרופים הללו הוא מקור האור והחיות הרוחנית דרקיע הגשמי הנקרא שמים וז\"ש בדבר ה' שמים נעשו בדבר ה' דוקא שהוא מאמר דיהי רקיע בבחי' החכמה שבו אך זהו דוקא התהוות בחי' הצורה הרוחנית דרקיע זה אבל בחי' חומר היש הגשמי דרקיע זה יש לו מקור אחר גבוה מזה והוא בחי' סובב כו' שלמעלה מבחינת החכמה שבי' מאמרות שמשם נמשך כל בחינת התהוות החומר הגשמי של כל הנמצאים שנשתלשלו בדבר ה' ורוח פיו כו' וז\"ש כל אשר חפץ ה' עשה כו' וכן כי הוא צוה ונבראו כו' ושרש הדברים הוא לפי שגם בעולם האצילות יש בחינת חומר וצורה שנק' אור וכלי בבחי' האצי' ושרש התהוות האורות הוא מבחינת אור החכמה שרש כל הא\"פ ושרש התהוות הכלים הוא מבחי' המקיף של כל הא\"פ שנמשך מן אור החכמ' ולמטה כו' ולזה הטעם גם בהתהוות הכלים מאיר א\"מ מבחוץ לכלים וא\"פ מאיר מבפנים לכלים כו' וד\"ל אך א\"כ מהיכן יש חבור וקשר לכלי עם האור להיות האור מוגבל בכלי והכלי תקבלנ' ותגבלנו מכל צד כו' מאחר שמקור ושרש התהוות הכלים הוא מבחי' המקיף שלמעלה מבחינת"],[2201340159,"מקור ושרש האורות ואין למקיף חבור עם הפנימית מאחר שהוא סובב ומקיף עליו מלמעלה כו' ועוד יש להבין דלכאורה היה מהראוי להיות להפך שמבחי' אור המקיף שהוא עליון יותר היה ראוי שיהיה מקור להתהוות כל אור ומבחי' א\"פ שלמטה הימנו יהיה מקור להתהוות הכלי המצומצם המגביל את האור כמו שבחי' א\"פ מצומצם הוא לגבי המקיף כו' אך הענין הוא שאין התהוות הכלים מצד עצם אור המקיף מאחר שהמקיף בלתי מוגבל והכלי הוא בחי' מגביל דוקא ואיך יתהוה מוגבל מבלתי מוגבל כו' אלא הענין הוא שמבחי' כח המגביל שבמקיף הוא שנעשה מקור להתהוות הכלי המגביל כי המקיף הוא מגביל הא\"פ מבחוץ מכל צדדיו כמו החומה שמקפת העיר ועד\"מ רוחני יותר זהו שכל המשפיע שמקיף לשכל התלמי' הקטן הימנו שמגבילו מכל צד כמו העגול הגדול שמקיף לקטן שבתוכו כו' וע\"כ ממנו בא התהוות הכלי ג\"כ שהיא המגביל לא\"פ מכל צד כו' וע\"כ המקיף שורה ע\"ג הכלי מבחוץ שזהו בבחי' ההגבלה וההיקף שמבחוץ אבל הא\"פ שורה בבחינת הגבלה שבכלי מבפנים שהוא חלל בית קבולו כו'. ואמנם עדיין אין זה מובן במה שיש שייכות לכלי להתחבר לאור להגבילו בתוכו ומבחוץ כו' אך זהו מצד שיש חבור למקיף עם הפנימי כי הגם שהמקיף מקיף על הא\"פ מלמעלה מ\"מ אפס קצהו נכנס להאיר בו בגלוי רק שבלתי מתיישב בו ונשאר בבחי' מקיף עליו וה\"ז בא בבחי' מטי ולא מטי נוגע ואינו נוגע כמו ורוח אלקים מרחפת ע\"פ המים שהוא נוגע ואינו נוגע כו' כמ\"ש בע\"ח דמבחינת מול\"מ דמקיף הוא שרש התהוות הכלי להגביל את האור שהוא בחי' הכאת המקיף בפנימי דוקא שיש חבור למקיף בפנימי רק שבלתי מתיישב בו כי אין הא\"פ מכילו ע\"כ מקיפו מבחוץ וכו' ומזה נעשה בחי' הכלי שהוא מקיף מבחוץ לאור וגם מקבלו בתוכו במקצת והוא א\"פ המוגבל בתוך הכלי כו' וכמו שיש חבור למקיף עם הפנימי ע\"י בחי' ההכאה דא\"מ כו' כן יש חבור לכלי עם האור והיו לאחדים במה שיאיר בכלי תמיד ולא יסתלק האור מן הכלי וגם הכלי מגבילו שלא יצא אור שפעו יותר מכפי המדה שהוא בחי' צמצום והתפשטות הסתלקות והמשכה שנקרא רו\"ש ששרשו בבחינת מול\"מ שבבחי' מקיף עם הפנימי כו' רק ששם מטי תחלה בחי' התפשטות ואח\"כ לא מטי הסתלקות ובאור וכלי רצוא תחלה מצד האור שמסתלק תחלה ואח\"כ הוא שוב בכלי אבל מצד הכלי הוא להפך שתחלה ממשיך הכלי את האור לתוכה ואח\"כ מגבילו בבחי' צמצום כו' והיינו לפי ששרש הכלי מבחינת מקיף שתחלה מטי כו' ומזה ראיה גמורה שאין הכלי בחי' מקבל מן האור אלא שרשו למעלה הימנו שהרי זהו הכלל שמלמעלה למטה נמשך מבחי' מול\"מ ומלמטה למעלה בבחי' רו\"ש כמ\"ש במ\"א ואם היה הכלי בבחי' מקבל שהוא מלמטה למעלה היה ראוי להיות בבחי' רו\"ש והאור בבחי' מול\"מ אלא הדבר מוכרח שהכלי למעלה מן האור ע\"כ ממשיך האור ואח\"כ מצמצמו כמו המקיף שהוא מאיר מלמעלה למטה והאור שהוא מקבל מן המקיף מלמטה למעלה ע\"כ הוא בבחי' רו\"ש כמו אור הנר שעולה תחלה ואח\"כ יורד ונח כו' וד\"ל:\n(עו) <b>אך</b> הנה באצי' הרי אמרו דאיהו וחיוהי חד איהו וגרמוהי חד שזהו ענין יחוד אא\"ס באורות וכלים שנקרא חיוהי וגרמוהי בשוה ממש בענין האחדות והיחוד שהרי כמו דאיהו וחיוהי חד כן ממש איהו וגרמוהי חד משום דבחי' הכלים דאצי' הגם שהן מגבילין את האור ומצמצמים אותו אין זה בחי' צמצום והגבלה ממש כצמצום והגבלת הנבראים שהרי הכל באח\"פ דהארת הקו וחוט מאיר בכל האצילות כמשל האדם שחיות נפשו עם אברי גופו מתאחדים כא' כך כמו חסד דרועא ימינא כו' איהו וגרמוהי חד ממש וזה שנקרא הגבלה"],[2201340160,"וצמצו' היינו רק שלא יתפשט האור האלקי יותר מכפי המדה כענין שאמר לעולמו די וכמ\"ש במ\"א אבל מאצילות לבריאה ויצירה כו' הרי ידוע שמבחינת למ\"ד כלים דז\"א נעשה בחי' נר\"ן של האורות דע\"ס דבי\"ע נשמה בבריאה ורוח ביצי' כו' דהיינו מבחי' הגבלת הכלים דאצי' נמשך ומתהווה בחי' אור דבריאה כמו מבחינת כלי החסד דאצילות המגביל ממנו דוקא נמשך בחי' אור החסד דבריאה שהוא מקור להיות התהוות בע\"ג ממש כמו נשמת אברהם והוא ע\"י בחי' הכלי דאור חסד הבריאה המגביל בבחי' הגבלה ממש מאחר שהוא שרש נשמת אברהם מאין ליש ממש כו' וכן הולך האור בהשתלשלות מבריאה ליצי' ומיצירה לעשיה עד התהוות יש גמור מבחינת כלים דמלכות דעשיה כו' כמ\"ש במ\"א וד\"ל ועכ\"פ בכל עולם ועולם הנה בחינת הכלים שהוא בחינת המגביל את האור בבחינת יש ודבר מה כו' שרשו מבחי' המקיף המכה ומאיר בפנימי כנ\"ל עד שגם בחינת החומר של גלגל הרקיע הגשמי שרשו מבחינת המקיף דאורות דמל' דעשיה ובחי' הרוחניות שלו שנקרא נפש הגלגל נמשך מבחינת הא\"פ דמל' דעשיה ומקור הראשון דבחינת המקיף דמל' דעשיה הוא מקיף דמל' דאצי' עד מקיף דכתר דאצי' עד בחינת מקיף הכללי בחינת סובב כו' שהוא מקיף הראשון שנוגע ואינו נוגע בבחינת א\"פ הראשון כו' וד\"ל:\n(עז) <b>ובכ\"ז</b> יתורץ הקושיא דלעיל בענין ב' פסוקים דכי הוא צוה כו' ובדבר ה' שמים נעשו דסתרי אהדדי לכאורה שבאמת אין כאן סתירה כלל וכלל ששניהם אמת דמ\"ש בדבר ה' שמים נעשו וברוח פיו כו' זהו דוקא בבחי' עשיה לעשות הרוחניות שהוא האור וחיות דרקיע שנקרא נפש הגלגל כמ\"ש כלם בחכמה עשית שהחכמה הוא בחינת מקור הראשון של כל האור והחיות הרוחניות הבא בהשתלשלות בבחינת א\"פ כו' אבל בחינת חומר היש הגשמי של הרקיע שנקרא כלי וגוף הגלגל שרש התהוותו מבחינת המקיף המאיר בא\"פ הראשון דחכמה שהוא בחינת סובב כ\"ע שנאמר בו כי הוא צוה כו' הוא ל' נסתר וכידוע בענין אתה הוא דאתה א' עד ת' דהיינו כ\"ב אותיות וה' מוצאות שבדבור ששרשו בחכמה דאבא יסד ברתא וע\"כ אתה בבחי' החכמה כמ\"ש כי אתה אבינו כו' וכמ\"ש בזהר להיות שהחכמה באה בגלוי לנוכח כמ\"ש והחכמה מאין תמצא מבחינת ראשית הגלוי כידוע אבל הוא ל' נסתר הוא בחינת המקיף ואתה מקבל מהוא כמ\"ש אתה הוא כו' וזהו כי הוא צוה כו' והיינו כי ה' הוא האלקים שהוא המחבר הוי\"ה ואלקים בחינת אור וכלי כו' וכמאמר אנת הוא דמקשר לון כו' וזהו מפני חבור דהוא באתה מקיף בפנימי בבחי' מול\"מ כנ\"ל וד\"ל והיינו כמו ויאמר אלקים יהי רקיע הרי בחינת אמירה זו מצד עצמה בצרופי אותיות המאמר הוא בבחי' החכמה מקור כל הא\"פ כנ\"ל ומזה נתהווה בחינ' רוחניות החיות דרקיע אך בחי' הצווי דאלקים זה שצוה וגזר אלקים באמרו יהי רקיע ה\"ז בא מבחי' סובב ומקיף הראשון כו' שע\"ז נאמ' כי הוא צוה ונבראו כנ\"ל שבזה הצווי שוין הכל מראש וסוף וגם הקליפו' מתהווין מצווי זה ג\"כ כמו שאין הפרש בין חשך לאור כו' והוא כמו התהוות בחי' נוגה דבי\"ע עד שגם בחי' נוגה דעשיה שרובו רע כו' וגם קליפות הטמאות לגמרי רוחין ושידין דאתבריאו בע\"ש ביה\"ש כו' אע\"פ שבחי' צרופי אותיות שבבחי' א\"פ בהתהוות רוחניות שלהם הוא בתכלית הצמצום וההסתר עד שנק' חשך גמור מ\"מ בענין התהוות יש שלהם שוים הם עם היותר עליונים כו' ולפ\"ז מ\"ש בזהר דגופין דשדין לא אתבריאו בביה\"ש דע\"ש משום דאתקדש יומא כו' קדוש היום הוא שהפסיק הארת והמשכת הסובב ולא הפסיק הארת והמשכת דממלא כו' לפי שעיקר בחי' השבת הוא מ\"ש כי בו שבת וינפש בבחי' הסובב כו' שאם בחי' הסתלקות זאת בבחי' ממלא כו' הרי היה הכל"],[2201340161,"חוזר למקור הראשון כו' וא\"כ זה סותר למ\"ש בע\"ח דעיקר השבת הוא בפנימיות העולמות ולא בחצוניות אשר ע\"כ העולם הוא במציאות יש ודבר רק בחי' פנימיות החיות עולה מתחתון לעליון כו' אך הענין הוא דגופין דשדין לא נבראו משו' דאתקדש יומא בין המשכת א\"פ להמשכ' א\"מ משום דהצורה מתהווה תחלה כו' וד\"ל ולא מטעם שהשבת הוא בבחי' סובב כו' אך זה גופא למה הפסיק קדוש היום בין המשכת א\"פ להמשכת א\"מ מבואר במ\"א משום דהוו מחרבי עלמא לתוקף הדין הקשה וליואי אתקינו פגמא דא כי השלימו לקו השמאל להמתיק לבחי' הגבורות הקשות ביותר שמסתעפים למטה מטה כמו בקליפות הטמאות כו' וכמ\"ש במ\"א באריכות וד\"ל:\n(עח) <b>ולהבין</b> בתוספות באור ההפרש בין מצות ת\"ת למצות מעשיות בענין המבואר למעלה בענין תכלית חכמה כו' ללומדיהם לא נאמר כו'. להיות ידוע בשרש התורה שהיא רק מבחי' ממלא כ\"ע דהיינו בבחי' הארת אא\"ס בחכמה שנק' ראשית הגלוי בבחי' ממלא כידוע ואוריית' מח\"ע נפקת אבל שרש המצות שהן מלובשים בדברים גשמיים דיש דנגה כמו קלף דתפלין וצמר דצצית וכה\"ג שבהן יש הארה בהעלם עכ\"פ מבחי' סובב להיות בבחי' היש כו' כמ\"ש למעלה באריכות אבל הנה יש להבין בזה דלכאורה הרי מובן מענין זה שבחי' היש של כל הנמצאים שרשו מבחי' סובב כו' א\"כ כל מה שצ\"ל בבחי' יש יותר יותר מאיר שם מבחי' סובב בגלוי כו' ולפ\"ז יש חלוק והפרש מדרגות גם בבחי' סובב שלמעל' בעולמות העליוני' יותר שאינם בבחי' יש כ\"כ אין בחי' סובב מאיר שם כ\"כ כמו בעולמות התחתונים הנפרדים בבחי' יש יותר שבהם מאיר בחי' סובב בגלוי יותר עד שבכלל יש הפרש גדול בין בחי' גלוי הארת סובב למעלה מעלה בראשית ההשתלשלות ראשית הגלוי שהוא בחי' החכמה שמאין תמצא בבחי' יש שאם לא היה הארת סובב לא היה החכמה בבחי' יש כלל אלא היתה כלולה בעצמות המאציל כמ\"ש למעלה באריכות ובין הארת סובב למטה מטה כמו בדברי' גשמיים שבעוה\"ז השפל מכולם שהן בבחי' יש ודבר ממש שבהן מאיר אור הסובב הרבה יותר מהארתו בבחי' החכמה כשמתהווה ליש וזה דבר שא\"א לומר שבחי' סובב מאיר יותר ביש גשמי מביש רוחני כו' אלא הוא מאיר בכלם בשוה ממש שהרי נק' סובב כ\"ע ובחי' סובב ה\"ה בחי' מקיף לכלם בשוה וכמ\"ש בע\"ח דבחי' מקיף הכללי מקיף לד' עולמות דאבי\"ע בשוה ממש כידוע וד\"ל:\n(עט) <b>אך</b> להבין כ\"ז הנה תחלה יש להקדים ענין ההפרש בין בחי' פנימית לבחי' מקיפין בכללות ההשתלשלות דהנה ידוע בע\"ח שמתחלה היה אא\"ס ממלא כל החלל כו' ואח\"כ צמצם א\"ע ונעשה מק\"פ וחלל כו' ונמשך בבחי' קו וחוט וכו' וא\"כ גם בחי' קו זה שהוא מקור כל האורות פנימים כידוע גם הוא נמשך מבחי' אא\"ס שלפני הצמצום שנק' מקיף וסובב הכללי כידוע ולפ\"ז אין הפרש בין פנימיים למקיפין שכמו שהמקיפים שבקו זה נמשך מבחי' סובב הכללי כן ממש גם בחי' הפנימיי' שבקו זה נמשך מבחי' סובב מאחר שכל בחי' אור הקו הזה נמשך מבחי' סובב רק שנמשך אחר הצמצום וזה א\"א לומר שהמקיפים נמשכו מבחי' סובב שלא ע\"י צמצום דמק\"פ כו' שהרי ידוע שכל המקיפים מבחי' הקו הזה שהוא נעשה אחר הצמצום הראשון דוקא (ומ\"ש בע\"ח דקו זה מתעגל וחוזר ומתעגל כו' שזהו בחי' המקיפים ואשר נמשך בבחי' יושר הוא הנקרא בחי' פנימיים כו' זה גופא יש להבין למה יהיה מעלת המקיפים גבוהים מן הפנימיים מאחר שממקור ושרש א' יוצאים שהוא בחי' הקו ושרש א' להם במקור הראשון שלפני הקו) וגם עוד יש להבין בעיקר ענין המבואר למעלה בענין התהוות יש גשמי שהוא נמשך מבחי' סובב שהוא בחי' אין ממש"],[2201340162,"כידוע והלא נאמר בדבר ה' שמים נעשו וברוח פיו כו' שהן י' מאמרות שבהן דוקא נבראו כל העולמות מאין ליש ממש שזהו בחי' צרופי אותיות דבור העליון שיש בהן בחי' הבל הקול והוא שנקרא דבר ה' ורוח פיו ממש כמו מאמר יהי אור הרי צרופי אותיות הללו דיהי אור מזה נתהווה מציאות היש דאור בבחי' יש גשמי שהרי נא' ויהי אור וכן ממאמר יהי רקיע נעשה הרקיע כו' כידוע וכ\"ז ה\"ה דוקא בבחי' ממלא כ\"ע שזהו בחי' כח האלקי שיורד ונמשך בצרופי אותיות בדרך עו\"ע מראש עד סוף כידוע וכמ\"ש בס\"י ה' אבנים בונות ק\"ך בתים כו' שזהו האור המלובש בתוך כל עלמין ממש להוותם מאין ליש דוקא וכמ\"ש ואתה מחיה את כלם מא' ועד תי\"ו וה' מוצאות כו' מחיה ממש מאין ליש וגם בחי' המדות העליונות דאצי' המאירים ומלובשים בצרופי אותיות די' מאמרות הללו הרי גם הן באים בבחי' ממלא דוקא וכמו ביום הא' יהי אור שבמאמר זה מלובש ומאיר מבחי' חסד דאצי' כמו עד\"מ חסד שבלב האדם שמאיר בדבורו בבחי' אור וחיות ממש וכמו\"כ ביום הב' במאמר יהי רקיע נתלבש ומאיר בחי' אור הגבורה דאצי' כו' ובתוך המדות הללו מאיר בחי' המחשבה והשכל ובתוך השכל מלובש הרצון והתענוג כו' שכ\"ז ה\"ה בא בבחי' התלבשות בתוך כ\"ע בבחי' ממלא דוקא (וגם מ\"ש ישראל עלו במחשבה שלמעלה מבחי' הדבור די' מאמרות ג\"ז הוא בבחי' ממלא רק שהוא בחי' פנימי' ורוחנית הדבור די' מאמרות כמו באדם למטה שהמחשבה היא פנימי' הדבור כו' ואפשר שעלו במחשבה הקדומה שלפני הארת הקו והחוט שהוא בחי' עצמות אא\"ס ממש שהוא למעלה מן המחשבה שבדבור ונקרא מחשבה א' פשוטה באח\"פ כו' כמ\"ש במ\"א):\n(פ) <b>והנה</b> להבין כ\"ז יש להקדים ב' הקדמות. הקדמה א' בענין בחי' ההמשכה וההשפעה שנמשך מבחי' עצמות אא\"ס ב\"ה שיש בזה ב' מיני המשכות והשפעות הא' בחי' ההמשכה והשפעה שנמשך מעצמות אא\"ס בבחי' א\"ס ממש מפני שזהו ענין ובחי' גלוי אור עצמותו ע\"כ זאת ההארה באה ג\"כ בבחי' א\"ס ממש. והב' הוא בחי' המשכה והשפעה הבאה להיות האור בבחי' גבול ומדה ונק' מאמר קו המדה כו' ובאור הדברים הנה באמת ענין ופי' דסובב כ\"ע הרי א\"א לבאר מהותו באופן המושג לנו לעין השכל שהוא רק כמו הארת אור עליון ביותר המאיר בבחי' היקף מסביב ומרחוק מכל צד וכה\"ג שהרי אין כל אור עליון האלקי נמשל לבחי' זיו ואור ממש כמו אור וזיו השמש וכה\"ג לא מניה ולא דוגמתו כו' רק מה שנק' בשם אור הוא שם המושאל בלבד והוא על היותו ממשיך בחי' אור וחיות האלקי למקבלים וכידוע שכל מה שהמקובלים קוראים בשם אור הוא רק בחי' רוחניות חיות ושפע ולא בחי' אור וזיו ממש וא\"כ גם בבחי' מהות דסובב זה כאשר אנו אומרים בו בחי' אור כמו בחי' הארת אור דסובב זה למטה כמו להקיף לכל העולמות כו' כנ\"ל ה\"ז ג\"כ בחי' שפע והמשכת חיות רוחני המחיה ממש לכל העולמות ולא כמו זיו ואור השמש בלבד אלא הוא בחי' אור וחיות שמחיה את הכל בבחי' חיות ממש ומה שנק' הארת סובב דוקא היינו שבחי' חיות ושפע זו נמשך ומתפשט מבחי' ומדרגה עליונה הנק' סובב כו' שזהו בחי' ההמשכה שנמשך ונתפשט שלא בדרך השתלשלות והתלבשות בבחי' עו\"ע אלא מחיה את כל העולמות בשוה ואפי' חומריות העוה\"ז וגסותו הוא מחיה ממש כמו שמחיה לעולמות היותר עליונים שלפני עולם האצי' ממש בהשוואה א' כו' וזהו שהוא מאיר ומקיף לכלם בשוה אבל בחי' הארה זו הרי היא בחי' אור וחיות דוקא וז\"ש דלית אתר פנוי מניה ממש שהוא בחי' סובב זה דכתיב ביה את השמים ואת הארץ אני מלא בשמים ובארץ בשוה ממש כו' וכידוע וד\"ל:\n(פא) <b>אך</b> א\"כ יש להבין ד\"ז על בוריו יותר שלפי הנראה מזה הרי בחי' הארה דסובב זה מחיה ממש אפי' לחומריות העוה\"ז וכו' א\"כ מהו ההפרש בינו לבחי' ממלא כ\"ע שגם הוא מחיה את הכל וכמ\"ש ואתה מחיה את כלם כו' ולמה נק' בשם הארת סובב דוקא שהוא רק בבחי' מקיף מרחוק בלבד מאחר שהוא מחיה ממש כנ\"ל. אמנם הנה כתיב כל אשר חפץ ה' עשה בשמים ובארץ בימים וכל תהומות כו' דמשמע מזה שחפץ ה' שוה הוא בכל אשר עשה ואין חלוק בזה בין עולמות עליונים ותחתונים כלם חפץ ורצון א' עשה כו' וזה פלא לכאורה והנה יש להקדים תחלה ענין ובחי' מחשבה הקדומ' שבעצמות אא\"ס אנא אמלוך שנק' בחי' מל' דא\"ס כידוע והוא הנק' ג\"כ בשם רעוא דכ\"ר דהיינו כאשר עלה ברצונו הפשוט כו' כי המחשב' נק' רצון כידוע ועליית מחשבה זו דאנא אמלוך נק' רעוא דכ\"ר אע\"פ שאנא אמלוך הוא רק רצון פרטי מורכב בענין המלוכה הזאת דאנא אמלוך כו' אך בשביל רצון זה דאנא אמלוך הוא שעלה ברצונו הפשוט להיות לו רצון להשתלשלות העולמות בכללות והוא הנק' רעוא דכ\"ר פי' רצון לרצון כו' ובאור הדברים הנה מובן מבחי' מל' דאצי' בבריאה שז\"ש מלכותך מלכות כ\"ע וידוע שזהו עד\"מ מלכותא דארעא שמלכותו מתפשטת על כל אנשי המדינה דהיינו בחי' התנשאותו ואימתו מוטלת עליהם עד שבטלים כולם אליו לרצונו בכל אשר יגזור אומר עליהם כו' וכמו\"כ למעלה בבחי' מלכותא דרקיע בחי' מל' דאצי' הוא בחי' התנשאות אור האלקי שמתנשא ומרומם על כל העולמות והכל בטלים אליו בתכלית הבטול כו' אבל לכאורה אין זה מובן כלל דהלא אין המשל דומה עם הנמשל שהמשל דהתנשאות מלך ב\"ו הרי לא נמשך ע\"י זה בחי' אור וחיות להיות מזה התהוות מציאות אנשי המדינה כי אין עצמות המלך מתפשט ומתלבש בהם כלל רק בחי' ממשלתו בלבד הוא שמתפשט עליהם ומציאותם נמצא במהות בפ\"ע גם טרם שמושל עליהם אבל בנמשל למעל' בבחי' מל' דאצי' הרי ידוע שמבחי' ההתנשאות דמל' דאצי' מזה דוקא נמשך בחי' אור וחיות לכל הנבראים כמ\"ש ואתה מחיה את כלם וכידוע אלא צ\"ל שבאמת אין הנמשל רק בענין של בחי' המלוכה בלבד שהוא בחי' ההתנשאות אבל אינו דומה עם המשל ממש שהרי בבחי' מלוכה זאת הוא מחיה את כלם וכמ\"ש ה' מלך גאות לבש כו' וכידוע דמבחי' מל' דאצי' נעשה בחי' מקור החיות של כל עולם הבריאה וכן מבחינ' מל' דבריאה נמשך בחינ' מקור החיות של כל עולם היצירה וכן ממל' דיצירה בעשיה וא\"כ זה האור והחיות הגם שהוא בבחינת התנשאות מ\"מ מאיר ומחיה ממש רק שהוא מאיר ומחיה לכל העולם בבחי' מקיף וסובב מאחר שהוא בחי' ההתנשאות כו' וזהו בדרך פרט כמו ממל' דאצי' בבריאה הוא בחי' מקיף לבריאה וז\"ש בע\"ח דמבחי' מל' דאצי' נעש' כתר לבריאה כו' וכן ממל' דבריאה נעשה כתר ליצירה כו' ובחי' כתר זה הוא בחי' הרצון הפרטי שנמשך להיות ממנו התהוות כל אותו העולם כמו בחי' רצון העליון לברוא עולם הבריאה כמ\"ש בזהר כד סליק ברעותיה למברי עלמא כו' הנה זה הרצון הוא המחיה ומהוה אותם מאין ליש והרצון הזה בא ונמשך מבחי' מל' דאצי' שזהו מה שעלה ברצונו להיות מלך על עם נפרד כו' ע\"כ נמשך רצון לברוא כו' וא\"כ ה\"ז האור והחיות שנמשך מצד בחי' מל' דאצי' הוא בא בבחי' מקיף לעולם הבריא' אבל הוא עיקר מקור החיות הנמשך מן הרצון לברוא כו' וז\"ש ולכבודי בראתיו כו' כבודי הוא בחי' המל' בראתיו נעשה רצון לבריאה כו' וכן ממל' דבריאה נעשה כתר ליצירה כו' וז\"ש מלכותך מלכות כ\"ע כו' והנה מובן עכ\"פ מזה שכל בחי' מל' שבעליון שנעשה כתר לעולם התחתון מאיר ומחי' אותו בבחי' מקיף שהוא ענין ההארה הבאה בהשוואה א' לכל פרטי הנמצאים שבאותו עולם"],[2201340163,"התחתון לראש וסוף בשוה ממש וטעם הדבר כי גם הרצון הזה אשר נמשך להיות מקור החיות לעולם זה הוא בא בבחי' כללות הרצון השייך לזה העולם לכל הנמצאים שבו כמו כל אשר חפץ ה' עשה כו' ואח\"כ מתחלק לרצונות פרטיים לכל נמצא ונברא בפרט כו' וזהו הנק' בחי' סובב לעולם זה בפרט דהיינו בחי' כתר שכותר בבחי' מקיף וסובב בהשוואה א' לכללות עולם זה מראשו לסופו ביחד כו' שכמו שיש בחי' סובב כ\"ע בכללות כל ההשתלשלות דקו וחוט כו' ונק' מקיף הכללי כידוע שזהו בחי' מל' דא\"ס שנעשה כתר לא\"ק כו' כן יש בחי' סובב בפרט בכל עולם ועולם דאבי\"ע דהיינו שמבחי' מל' שבעולם העליון נעשה בחי' כתר וסובב לעולם שלמטה הימנו כנ\"ל וד\"ל:\n(פב) <b>ומעתה</b> הנה יובן ג\"כ בבחי' סובב כ\"ע בכלל שהוא נמשך מבחי' מל' דא\"ס דהיינו בחי' מחשבה הקדומה דאנא אמלוך כו' כנ\"ל שזהו ג\"כ ממש ע\"ד הנ\"ל בבחי' מל' דאצי' בבריאה ומל' דבריאה ביצירה כו' רק שבחי' מחשבה זו דאנא אמלוך שנק' מל' דא\"ס הוא בבחי' כללות יותר דהיינו בחי' ההתנשאו' אלקית שכלול בבחי' עצמות אא\"ס עדיין וזהו שעלה במחשבה הקדומ' אנא אמלוך פי' מחשבה הקדומה היינו בבחי' העצמות ממש שנק' קדמון לכל הקדומים ופי' מחשבה זו הוא בחי' הרצון שהרצון נק' מחשבה כידוע אך נק' רצון קדום בחי' העצמות עדיין כו' והנה כמו שמבואר למעלה במשל דהתנשאות מלוכה למטה שאין הנמשל דומה עמו להיות שמבחי' מלוכה שלמעלה נמשך בחי' אור וחיות ממש כו' כן יובן ג\"כ בכללות בחי' המלוכה שבמחשבה זו דאנא אמלוך שבעצמות אא\"ס ממש שהוא בחי' מאיר ומחיה ממש לכל ההשתלשלות דאבי\"ע רק שהוא מאיר ומחיה לכלם בשוה והוא בחי' מקיף הכללי שמקיף לד' עולמות בשוה ממש ונק' סובב כ\"ע בכללות הכל וכמו שמבואר למעלה בענין מל' דאצי' בעולם הבריאה שנמשך בבחי' מקיף וסובב בפרט לעולם הבריאה שמאיר בו בהשוואה אחת מראשו לסופו כו' כי גם הרצון שנמשך שם הוא בכללות באותו עולם כו' כנ\"ל וכן יובן ג\"כ בכללות יותר בבחי' מל' דא\"ס שנעשה בחי' מקיף וסובב כללי לכל הד' עולמות דאבי\"ע שהוא מאיר ומחיה לכללותם יחד בהשוואה א' בראש האצי' עם סוף עולם העשיה כו' להיות שבחי' הרצון העליון שנמשך מבחי' מחשבה זו דאנא אמלוך כו' הוא בא בבחי' כללות ביותר ונק' רעוא דכ\"ר כנ\"ל כי בשביל רצון ומחשבה זו דאנא אמלוך כו' הוא שנעשה בחי' רצון כללי להיות ממנו מקור לכל ההשתלשלות בכלל דהיינו בחי' רצון לרצון והוא הנק' רעוא דכ\"ר כו' כי הנה בחי' רצון הבא בגלוי להאציל לעולם האצי' ונק' כתר דאצי' שנמשך ממל' דא\"ק וכה\"ג הרי צריך להיות בתחלה רצון והסכמה שיהיה לו רצון זה וא\"ל לא יעל' ברצונו להאציל כלל וכן בחי' הרצון העליון שבא בגלוי לברוא עולם הבריאה כו' הרי צ\"ל תחלה בחי' רצון לרצון זה הפרטי וא\"ל לא היה עולה ברצונו בגלוי לברוא כו' וכן להיו' לו לרצון בגלוי לעול' היצי' כמ\"ש בראתיו יצרתיו כו' הנה מקור כל הרצונות הללו הוא הנקרא רעוא דכ\"ר שהוא אשר הוסכם ברצון קדום שיהיה לו רצון להשתלשלות העולמות בכלל וממילא נמשכין אח\"כ בחי' רעוין פרטיים כמו הרצון להאציל והרצון לברוא כו' עד שאפי' בחי' ומדרגה היותר תחתונה שבסוף עולם העשיה עלה תחלה בהסכם ורצון הקדום שנק' רעוא דכ\"ר או מחשבה הקדומה כו' ואין הפרש בין התהוות הרצון להאציל להתהוות הרצון שבסוף העשיה להיות יש גשמי כמו כל אשר חפץ ה' עשה ממש כו' לכלם מחי' בשוה ממש מבחי' רעוא דכ\"ר שהוא בא מצד בחי' מחשבה דאנא אמלוך הנק' מל' דא\"ס וז\"ש בע\"ח שמאיר ומחי' לכל העולמות דאבי\"ע בשוה ממש שהרי כמו שעלה ברצונו הפשוט שנק' מחשבה"],[2201340164,"ורצון קדום להיות עולם האצי' כמו\"כ ממש עלה ברצונו הפשוט הזה להיות עולם הבריאה ועולם היצירה עד בחי' ומדרגה היותר תחתונה שבסוף העשיה כו' וא\"כ אין הפרש בין בחי' התפשטות הארה וחיות שנמשך ממחשבה ורצון קדום זה לעולם האצי' בין הארתו והתפשטותו בבי\"ע להיות עשיה גשמית דהיינו מאחר שהיה רצונו הקדום להיות עשיה גשמית ממש כמו שהיה רצונו הקדום להיות בחי' האצי' וא\"כ גם בחי' עשיה גשמית מקבל בחי' אור וחיות דמל' דא\"ס שהוא בחי' רצון ומחשבה הקדומה כמו שמקבל עולם האצי' ממש בשוה ונמצא שבחי' התפשטות מלכותו ית' העצמות שנקרא מל' דא\"ס הוא בכל העולמות בשוה אפי' בחומריות העוה\"ז וגסותו וז\"ש דלית אתר פנוי מניה כו' מניה ממש לפי שבבחי' מל' דא\"ס עצמו שוין מעלה ומטה ממש ונק' סובב כ\"ע בכלל רק מפני שרצונו הקדום שבעצמות ה\"ה בבחי' א\"ס ממש שאינו בא בגלוי למט' בעולמות אלא הוא סתום ונעלם בבחי' העלם העצמות שנק' סתימו דכל סתימין כו' ע\"כ נק' בחי' הארה זאת בשם סובב כ\"ע שאינו מאיר רק בבחי' מקיף אמנם אין הפירוש דסובב שהוא סובב ומקיף מלמעלה בלבד ואינו מאיר ומחיה כו' אלא שהחיות והשפע הוא בא בבחי' סובב שאינו בבחי' גלוי אלא בהעלם אבל הוא מאיר ומחיה ממש שהרי נק' מחשבה הקדומה ופי' מחשב' ורצון היינו בחי' אור וחיות ממש כי כאשר עלה במחשבה ורצון הרי זה הרצון והמחשבה הוא מקור להמשכת האור והחיות ממש להיות הדבר חי במציאות כך וכך כמו שעלה ברצונו ולא כמו רצון האדם שלא יפעול וימשוך חיות לדבר מה שרוצה אבל בחי' רצון העליון הוא המחיה ממש כי מיד שעלה ברצונו שיהיה כך וכך מיד נמשך האור והחיות כך וכך כמו ויאמר אלקים יהי אור שחפץ ה' שיהיה מציאות אור מיד ויהי אור וכה\"ג בכל התהוות העולמות היותר עליונים עד רום המעלות כמו להיות התהוות אור האצי' מיד שעלה ברצון ומחשב' הקדומ' לזה מיד נמשך מקור התהוו' אור האצי' רק שבחי' הרצון הקדום מאיר בהעלם בבחי' סובב ומקיף מאחר שנקר' רצון לרצון בכללות כנ\"ל אשר ע\"כ הוא מאיר ומחיה לכל העולמות בשוה מטעם הנ\"ל וד\"ל (ויובן כ\"ז עד\"מ כאשר הוחלט ברצון המלך לבנות פלטרין גדולים וכה\"ג שתכלית רצון זה הוא רק שיהיה הפלטרין בנוי בשלמות כמו שהעלה ברצונו מכבר וא\"כ ה\"ז רצון כללי בלבד אך הנה כלול בו כל פרטי הרצונות הבאים בו בגלוי אח\"כ שהרי לאחר שעלה ברצונו בכלל שיהיה לו בנין פלטרין זה מוכרח שיתחיל במלאכתו בפ\"מ ה\"ז רצון שני הבא בגלוי להתחיל מלאכתו עכ\"פ ולאחר שהתחיל מוכרח שיעלה רצון ג' איך ובמה לעשותו אם באבנים או בעצים ובאיזה ציור וכה\"ג ואח\"כ בעסקו במלאכת הבנין מתחדשים לו רצונות רבות פרטיות לכל דבר מלאכ' שבו בפרט כמו לקירותיו ולחלונותיו ודלתותיו והרצפה עד כלות גגו וכל פרטי חלקיו הקטנים הגם שהם דברים טפלים לטפלים כמו העפר שבקרקע שתחת הרצפה או העפר שע\"ג הקורה וכה\"ג לכל א' בא רצון בפרט כי א\"א שיושלם שלמות ענין הבנין בלעדם והרי גם הן נכללים בכלל הרצון השלם שעלה ברצונו תחלה מכבר שיהי' לו בנין פלטרין ומאחר שבלעדם לא נשלם הרצון הכללי הזה א\"כ הרי אין הפרש כלל לענין שלמותו של הרצון הקדום בין עיקר תחלת רצון המלאכה לגמר רצונותיו הקטנים בסופו בגמרו בדברים הטפלים וכה\"ג כי כלם בשוה עלו ברצון הקדום כי ודאי כאשר עלה והוחלט אצלו שיהי' לו בנין פלטרין ידע שא\"א לבנין בלא מעזיבה שע\"ג הקורה או עפר שבקרקע הרצפה וכה\"ג וא\"כ עלה ברצון הקדום שיהיה גם מעזיבה בבנין פלטרין וכה\"ג וא\"א לומר שמה שיש שרש לרצון בעיקר הבנין ברצון הכללי הוא יותר נעלה משרש הרצון האחרון הקטן בעשיית הרצפה וכה\"ג"],[2201340165,"מאחר שכל עיקר ענין רצון הכללי הקדו' הוא רק שיהי' לו פלטרין א\"כ מה לו ענין הפרש בין רצון שבתחלת מלאכתו לרצון שבסוף מלאכתו הכל ברצון א' הוא רוצה דהיינו כמו שרוצה בעיקר הבנין מטע' שעלה כבר ברצונו כן הוא רוצה בדבר הצריך לבנין בסופו מטעם שכבר עלה גם זה ברצונו תחלה ועל שניהם יגזור אומר ברצון א' פשוט שהוא מפני אשר כבר עלה ברצונו שיהי' לו פלטרין כמו שא\"א להיות בלי שיגזור על תחלת מלאכתו כן א\"א שיהיה גמרו מבלי שיגזור על מלאכת סופו וע\"ד דוגמא הגם שיסודות הבנין צריכים הוצאה מרובה ועל חלקיו הטפלים שברצפה וגם בסופו הם בהוצאה מועטת מאד על שניהם יחול הרצון הכללי בשוה ולא יחול הרצון הכללי ביסוד הבנין בבחי' פנימית יותר מבגגו ורצפה שלו אע\"פ שמצד בחי' גלוי הרצון יחול ביסוד ועיקר הבנין בפנימית יותר כו' מפני שלענין כללות הרצון שעלה תחלה שיהיה לו פלטרין אין הפרש בין תחלתו לסופו כלל ושניהם עלו בשוה ברצונו בענין כללות רצונו בדבר זה וד\"ל:\n(פג) <b>או</b> יובן עד\"מ אחר כיוצא בזה כמו כאשר הוחלט רצון פשוט וכללי באדם שיעסוק במו\"מ אחד להרויח בו ממון אשר כל פרטי עסקיו מתחלתו לסופו וגמרו כולם כא' נסקרו בעלות רצונו תחלה בכלל לעסוק במו\"מ זה בלי הפרש מצדו בין ענין פנימית העסק ועיקרו לחצונית הטפל שבו כמו בקבוץ הממון הון רב לקנות הסחורה וכה\"ג שזהו העיקר והיסוד אבל הצטרכות הנסיעה בכל פרטי דברים קטנים הטפלים לנסיעה לקנות שהנסיעה עצמה טפל לעיקר העסק והרי כל המצטרך לנסיעה טפל לטפל כו' מ\"מ הגם שמצד גלוי הרצון ודאי יש בעיקר העסק בפנימי' שלו רצון פנימי הרבה יותר מרצון הקל בחצונית העסק כמו דברים הטפלים לנסיעה וכה\"ג אבל מצד בחינת הרצון הכללי שכבר הוחלט אצלו שיעסוק במו\"מ זה כדי להרויח שוין הן פנימית העסק וחצוניותו ממש שכשם שלא יושלם תכלית הרצון הזה בלא פנימית העסק כמ\"כ לא יושלם בלא חצוניות שלו שהוא הנסיעה ושניהם עלו בשוה בתחלה ועל שניהם יגזור אומר בשוה ממש שכמו שיחפוץ בקבוץ הממון כמ\"כ יחפוץ בהכנת הנסיעה מאחר שכל עיקר רצון זה הוא ריוח הממון מה לו ענין הפרש בין פנימית העסק לחצוניותו כו' וזה ודאי שאם לא היה לו רצון קדום זה לעסוק בבנין או מו\"מ לא היה רוצה בכל פרטי הרצונות שבהן מתחלתן לסופן כו' אשר ע\"כ נק' רצון קדום זה בחי' רצון לרצון בין בפרט בין בכלל דהיינו שכל רצון בפרט שבבנין ומו\"מ היה לו רצון קדום לזה הרצון בפרט וא\"ל לא היה רוצה בו אח\"כ וגם הוא רצון לרצון בכלל לכל רבוי רצונות פרטיות שיהיה נולדים אח\"כ הוא בחי' מקור כללי להם שהרי מצד כחו של רצון זה הרי הוא מוליד בנפשו רצונות פרטיים רבים עד שישלים רצונו זה הקדום בכלל הענין ואין כל חדש ברבוי רצונות הללו הנולדים אח\"כ כי כולם היו תחלה ברצון הקדום וכולם בהשוואה אחת בלי חלוק מדרגות בזה כלל מטעם הנ\"ל וד\"ל ואמנם הנה מובן עוד דהגם שהרצון הקדו' הוא מקור כל הרצונות שאח\"כ בכלל ובפרט ועל כולם בשוה כו' מ\"מ אין הארתו אח\"כ בהגלות נגלות הרצונות הפרטיים רק בבחי' ההעלם בהם ולא בגלוי דהיינו דהגם שבודאי לא היה לו רצון הגלוי הזה בפרט הענין אם לא שקדם תחלה ברצון הקדום ומכחו הנה הוא בא כו' אבל בחי' כח זה שמאיר ברצון גלוי זה מחמת כחו של רצון הקדום אינו רק בבחי' ההעלם ובחי' מקיף אשר ע\"כ מצד בחי' הגלוי הרי יש בחי' פנימי יותר ברצון שבתחלת הענין ועיקרו יותר מרצון שבחצוניות הענין וטפל שבו כו' אבל אם היה מאיר ברצונות הפרטיי' בגלוי גמור בכחו של רצון הקדום הרי לא היה הפרש כלל ביניהן גם מצד גלוי הרצון מטעם שבבחי' רצון הקדום כולן שוין כנ\"ל וד\"ל אבל מה שמאיר עכ\"פ בבחי' ההעלם ה\"ה מאיר"],[2201340166,"ומחיה לכל הרצונות מגדול ועד קטן לכולם בשוה דוקא כמובן מכל הנ\"ל וד\"ל וזהו כל אשר חפץ ה' עשה בשמים ובארץ בימים וכל תהומות כו' שבחי' חפץ ורצון הקדום שבעצמות המאציל בחי' מחשבה הקדומה הנ\"ל עשה את הכל בחפץ ורצון א' לכולם בשוה וכולל את הכל בשוה בלי חלוק מדרגה בזה בין עולמות עליונים לעולמות התחתונים בשמים ובארץ בימים וכל תהומות כו' מטעם הנ\"ל וזהו למה יאמרו הגוים איה נא אלהיהם שהוא בלתי מושג להם ע\"כ אומרים איה להיותו בבחי' סובב כ\"ע ממש ואינו מושג לא בעולמות עליונים ולא בתחתונים אבל באמת אלקינו בשמים כל אשר חפץ עשה פי' משום דמה שהוא בבחי' סוכ\"ע היינו לפי שבחי' רצון העליון הזה שבעצמות הוא בבחי' א\"ס ממש וע\"כ נקרא סוכ\"ע שאינו מושג כלל ובלתי מתלבש בבחי' גלוי בעולמות רק בבחי' ההעלם אבל עכ\"פ בבחי' ההעלם כל אשר חפץ עשה שנמשך משם רצונות פרטיים לכל פרטי ההשתלשלות וכנ\"ל דכמו שהיה רצונו להאציל כו' כמ\"כ היה רצונו להיות בחי' עשיה גשמית כו' וא\"כ גם בחי' עשיה גשמית מקבלת אור וחיות בהעלם מרצונו וחפצו הקדום בעצמות וזהו כל אשר חפץ עשה כו' ומפני שהוא בבחי' סובב בהעלם ע\"כ ואלקינו בשמים בבחי' סובב כל אשר חפץ ברצונו הקדום עשה את הכל והוא בחי' רעוא דכ\"ר הנ\"ל הנקרא מחשבה הקדומה דאנא אמלוך בחי' מל' דא\"ס שמקיף לד' עולמות דאבי\"ע בשוה ממש כמ\"ש בע\"ח וכנ\"ל וד\"ל:\n(פד) <b>והנה</b> מעתה יש להבין בחי' ומדרגה השניה הנמשך מעצמות אא\"ס בבחי' גבול ומדה דוקא ולא בבחי' א\"ס כנ\"ל וזה פלא לכאורה איך יומשך בחי' גבול ומדה מעצמות אא\"ס שהוא בעצם בבחי' א\"ס בלתי ב\"ג כו' אך הנה ידוע בע\"ח שבחי' המשכת הקו והחוט שנמשך מעצמות אא\"ס שהוא ע\"י בחינת צמצום עצמות אא\"ס תחלה דהיינו שנסתלק ונכלל עצמות אא\"ס ונכלל ועלה בעצמותו ומהותו ממש (שלמעלה מבחי' אור וזיו כו') ונעשה כמו מק\"פ וחלל כו' ואחר הצמצום הזה הוא שהאיר בבחי' קו וחוט כו' ובאור הדברים הנה מצד בחי' עצמות אא\"ס ממש כמו שהוא לפני הצמצום הזה מאחר שהוא בבחי' א\"ס ממש לא היה נמשך כלל דרך שעור ומדה כמו המשכת הקו ולהיות נאצל במדה עשר ספירות עשר ולא תשע עשר ולא י\"א כו' כי מאחר שהוא אור פשוט בתכלית הפשיטות והוא בבחי' א\"ס ממש הרי אינו בגדר אור וספי' פרטית עדיין וכמ\"ש לאו מכל אנון מדות כלל ע\"כ ממנו לא היה נמשך אור וספי' בפרט כלל גם לא בחי' קו וחוט להיות מקור לי\"ס וראשיתן כו' וגם אם היה נמשך להיות מקור הספירות בפרטיהם לא היה נמשך בבחי' שעור ומדה אלא היה נמשך רבוא רבבות אורות וספירות לאין קץ ושעור כלל ובאופן ומהות אחר שאינו בגדר ומהות אורות וספי' הנאצלים כמו חו\"ב ומדות כו' מאחר שזה האור והשפע היה בא מכח עצמות אא\"ס ממש שהוא בלתי מדה ומושלל מכל מציאות אור וספי' כו' אשר ע\"כ כדי שיומשך בחי' קו וחוט שהוא בחי' קו המדה למדוד שעור השפע בבחי' ע\"ס פרטיות וי' כלול מי' כו' א\"א שיהיה זה כ\"א ע\"י בחי' צמצום אור עצמותו תחלה דהיינו שלא יומשך האור בבחי' א\"ס ממש אלא יומשך בבחי' גבול ומדה דוקא ואז נמשך בחי' הקו הזה שהוא המודד כל שעור ומדה בנאצלים כו' ובחי' צמצום עצמות אא\"ס והסתלקותו כדי שיהיה נמשך בבחי' שעור ומדה זה הכח נמשך ג\"כ מעצמות א\"ס ב\"ה שהוא כל יכול ויש בו בחי' זו ג\"כ לצמצם אור עצמותו שלא יומשך בבחי' א\"ס כו' והוא ענין הכח של בחי' הדין והצמצום שהיה תחלה בעצמו ששיער בעצמו בכח להיות גלוי פועל האור והשפע בבחי' גבול ומדה ולא בבחי' א\"ס והיינו עיקר בחינת הצמצום שלפני הקו כידוע ומבואר במ\"א בענין המאמר בריש הורמנא דמלכא גליף גליפו בטהירו עלאה דהורמנא"],[2201340167,"דמלכא הוא בחי' רצון ורשות שהוא בחי' עליית רצון קדום הנ\"ל שבעצמות אא\"ס שלפני הצמצום שנק' סוכ\"ע כו' ובו גליף גליפו וחקיקה שהוא בחי' הצמצום הראשון שבטהירו עלאה שלפני הקו עד שנעשה ונמשך בבחי' קו וחוט כו' וד\"ל:\n(פה) <b>והנה</b> בחי' ראשית הגלוי דבחי' קו וחוט הזה שהוא בחי' קו המדה נמשך תחלה בבחי' החכמה שהוא להיות נאצל אור החכמה לפי שהחכמה היא בחי' ראשית כל המציאות שהרי אנו רואים גם למטה בעולם העשיה הרי כולם בחכמה נעשו וגם האדם נעשה בחכמה כמ\"ש אשר יצר את האדם בחכמה והוא חכמה הנפלאה הנראה בנתוח אברי האדם וסדר מהלכם שנלאו בו כל חכמי הרופאים לעמוד עד סוף החכמה העמוקה ההיא לפי שחכמה אלקית היא וכן בחלקי החי כמו בבהמות ועופות וחיות וטרף מזונם יש בזה חכמה אלקית וחלקי הצומח כעשב ואילן וכל תבואת הארץ והארץ וכל אשר בה יש בזה חכמה אלקית שבה נעשה הכל כמ\"ש ה' בחכמה יסד ארץ כונן שמים בתבונה שגם רקיעים וגלגלים העליונים בתבונה ובחכמה אלקית נעשו שהרי נלאו בהם כל חכמי התכונה לעמוד ע\"ס ענין החכמה האלקית שבמהות הגלגלים ובסדר מהלכם כו' עד שגם בבריות הפחותים ביותר יש בהן הארת חכמה האלקית כמו בזבוב ותולעת ועד כל חלקי הרמש שבאדמה ומתחת לארץ כולם בחכמה עשית כו' ועד\"ז גם כל עולם היצירה ועולם הבריאה הרוחני בחי' אדם שבהן ובחי' דצ\"ח שהן המלאכים העליונים שבהם וכל צבא השמים ושמי השמים העליונים הרוחניים כולם בחכמה נתהוו ועד\"ז גם עולם הנאצל וכל אשר בו מבחי' אדם שבו ורקיעים ועד חלק הדומם שבו כולם בחכמה נאצל והוא ע\"י בחי' הקדומה שנמשך בראשית גלוי הארת הקו כו' (ונק' א\"ק אדם דבריאה כו') אך כל זה האור שנמשך בבחינת החכמה שהיא ראשית כל ההשתלשלות שבקו וחוט כו' הרי היא בחי' הארה מצומצמת מאד הבאה בבחי' גבול ומדה לגבי בחי' עצמות אא\"ס ממש כמו שהוא בבחי' א\"ס ממש כנ\"ל אשר ע\"כ הוצרך להיות בחי' צמצום ומק\"פ הנ\"ל כדי להיות בחי' ההמשכה בבחי' מדה וגבול שהוא ענין ראשית גלוי הארת הקו בחכמה כו' כנ\"ל וד\"ל:\n(פו) <b>אך</b> הנה כ\"ז הוא להיות בחי' התהוות עצם האור וכח מהות ומציאות דחכמה שהוא בבחי' הקו והחוט דוקא אחר בחי' צמצום ומק\"פ הנ\"ל לפי שמבחי' סובב שלפני צמצום הקו לא היה באפשר להיות בחי' התהוות צמצום אור ומהות פרטי כמהות אור וכח החכמה שהיא בבחי' גבול לגבי בחי' עצמות אא\"ס שהוא בבחי' א\"ס ממש כנ\"ל וכמו\"כ בכל בחי' האורות שנאצלו ע\"י בחי' הקו וחוט הזה הוצרך להיות ע\"י בחי' צמצום ומק\"פ בתחלה מטעם הזה אבל כדי להיות בחי' הכלים של האורות שנאצל ע\"י הקו הזה שהן בחי' הגבלת האור שמוגבל בתוך הכלי ומסתיים אורו וכח מציאותו ע\"י הכלי כמו ע\"ד דוגמא שאו' לאדם עד פה תבא ולא יותר כו' הנה בחי' המקור להתהוות זה המהות של הכלי שיגביל את האור הנה הוא בחי' סוכ\"ע שלפני צמצום הקו דוקא ולא מבחי' הקו כו' וכמ\"ש בע\"ח דשרש התהוות הכלים הוא מבחי' מקור המקיפים ושרש הא\"פ הוא ממקור כל הא\"פ שהוא בחי' הקו כו' והטעם הוא לפי שבבחי' סובב ומקיף הכללי הנ\"ל שם הוא בחי' רצון העליון שהוא בחי' רצון ומחשב' הפשוט' דאנא אמלוך שנק' רעוא דכ\"ר כו' ששם שוים מקור האצי' עם סוף העשיה כנ\"ל וכאשר עלה ברצונו הפשוט הזה שיהיה כללות ההשתלשלות בבחי' ע\"ס באורות פרטיים כנ\"ל בהכרח שעלה ברצון זה דוקא שיהיה בחי' גבול ושעור להתפשטות כל אור אחרי התהוותו ואצילותו מן הקו כו' שאם לא יהיה לאור הנאצל שעור ומדה בהתפשטות הרי מתפשט בלי גבול ואז א\"א שיהיה נאצל אור השני שאחריו"],[2201340168,"שנק' ענף המסתעף הימנו שכל זמן שאור העליון מאיר נכלל בו האור התחתון ואין לו מקום ותפיסה להיות עולה בשם בפ\"ע כלל כמו ע\"ד דוגמא אור החכמ' שהחסד נמשך ומסתעף הימנ' ונק' החסד ענף החכמה כידוע הרי כל זמן שאור החכמה אינו כלה ומסתיים איך יאיר אור החסד בבחי' מציאות אור בפ\"ע אלא צריך בהכרח שיתצמצם אור החכמה ויכלה כח התפשטותו שזהו ענין בחי' ההגבל' עד פה תבא ולא יותר כו' אז יוכל להיות התהוות מציאות החסד במהות וכח בפ\"ע וכמו\"כ הנצח שהוא ענף החסד א\"א שיתחיל אור הנצח בלי שיוגבל ויצומצם אור החסד תחלה וזהו הנק' בחי' הגבלת האור שהוא ע\"י בחי' הכלי המגבילו ומצמצמו שלא יתפשט יותר ונמצא שלא הי' בחי' השתלשלות ע\"ס כלל אם לא ע\"י בחי' הכלי' שכל כלי מגביל אורו ומצמצמו עד שיוכל להסתעף הימנו אור וספי' האחרת כו' וד\"ל:\n(פז) <b>ואמנם</b> א\"א לומר שבחי' כח של הכלי המגביל את האור הוא בא ונמשך מבחי' הקו הנ\"ל שהרי כל עיקר בחי' הקו הוא רק להיות מקור לכל התהוות מציאות האור ומהות עצם כחו בלבד ואדרבה ממנו יהיה מקור כח התפשטות האור בלי שעור וגבול אך בחי' כח הגבלתו הנק' כלי שרשו מלמעלה מעלה מבחי' הקו דהיינו מבחי' הרצון הפשוט הנ\"ל שעדיין אינו בחי' מקור למקור כלל רק שעלה בעצמות רצונו שיהיה כך וכך כנ\"ל בענין רצון קדום באורך וכאשר עלה ברצונו הזה שיהיה השתלשלות ע\"ס הרי בהכרח שעלה ברצונו זה שיהיה כל אור מוגבל בהתפשטותו כדי שיוכל להיות המשכת אור וספי' האחרת כו' כדי שיוכל להיות תכלית רצונו הזה הפשוט שהוא בחי' אנא אמלוך כו' לפי שאין מלך בלא עם ואם כל אור היה נכלל בעליון הימנו הרי חוזר כל ההשתלשלות להכלל בעצמות אא\"ס כמו שהיה לפני הצמצום וזהו הפך רצונו הקדום שהוא מחשבה דאנא כו' אשר ע\"כ צמצם א\"ע להאיר רק בבחי' קו כו' אלא מפני בחי' מחשבה זו עלה ברצונו הפשוט בהכרח שיהיה בחי' סיום להתפשטות כל אור ואור כדי שיוכל להיות בחי' השתלשלות חח\"נ וכה\"ג כו' וד\"ל. וא\"כ הרי מובן שכל התהוות האורו' בעצם מציאותן ומהותן הוא מבחי' הקו והחוט שהוא אחר הצמצום ומק\"פ מטעם הנ\"ל אבל שרש כח המגביל כל אור נמשך מבחי' אא\"ס עצמו שלא בדרך קו כו' אלא מחמת שעלה ברצונו הפשוט כך שאל\"כ לא יהיה בחי' השתלשלות כנ\"ל וד\"ל. (וה\"ז ממש ע\"ד הנ\"ל בענין רצון הקדום ששוה אצלו הרצון לאצי' כמו הרצון לעשי' כמשלי' הנ\"ל ברצון הבנין ומו\"מ וכה\"ג וכן בבחי' הרצון הקדום הזה להיות בחי' הגבלת האור כו' שוה אצלו ממש בחי' הגבלת אור עליון דחכ' להגבל' אור היותר תחתון כו' מאחר שכללות המכוון בזה אינו רק כדי שיהיה בחי' ההשתלשלות עו\"ע כו' וכנ\"ל במשלים באריכות) וזהו ענין בחי' מדרגה השני' שהוא בחי' ההשפעה והמשכה הנמשך מעצמות אא\"ס דוקא להיות בבחי' קו המדה שהיא בחי' כח הגבול והמדה לכל אור אחרי התהוות אצילותו כנ\"ל וזה דוקא נמשך מעצמות אא\"ס שלא ע\"י בחי' קו וחוט כנ\"ל ואע\"פ שזה פלא לכאורה איך ימצא שפע גבול מכח אא\"ס שהוא בלתי בע\"ג כו' והענין הוא משום דאא\"ס כל יכול ויש ביכולתו ג\"כ ליתן כח להגביל כל אור ושפע ואין זה מפני שאין יכולת הכח להיות מתפשט יותר אלא שעלה ברצונו הפשוט כך שיהיה בבחינת גבול שלא יתפשט האור יותר כמו שאומר וגוזר עד פה תבא שהגבלה זו אינה אמיתת מצד עצמה רק ע\"פ מאמר וצווי זה שגזר אומר שלא יתפשט יותר וכמארז\"ל שאמר לעולמו די כו' וז\"ש חק נתן ולא יעבור כו' וא\"כ יוכל להיות בחינת כח הגבלה הזאת מעצמות אא\"ס ואדרב' מפני שעלה ברצונו הפשוט כך ע\"כ זה הכח המגביל הוא נמשך דוקא מעצמות אא\"ס ולא ע\"י צמצום ומק\"פ הנ\"ל שצמצום ומק\"פ זה א\"צ רק בשביל להיות"],[2201340169,"כח ומהות האור שהוא בבחי' גבול ממש לגבי העצמות משא\"כ כח ההגבלה הזאת הרי היא באה מכח אא\"ס בעצמו שגזר אומר לעולמו די כו' שא\"צ לזה בחי' צמצום ומק\"פ כלל כי כח זה נמשך מעצמותו דוקא וכידוע דבחינת חו\"ג כלולים בעצמות אא\"ס שלפני הצמצום וזהו אא\"ס למעלה עד אין קץ ולמטה עד כו' כמ\"ש במ\"א וד\"ל:\n(פח) <b>אך</b> הנה לפי הנ\"ל בשרש התהוות הכלים שזהו מבחי' סובב דוקא ששם הרצון בבחינת א\"ס ממש כנ\"ל א\"כ איך יתכן שבחינת אא\"ס מאיר בבחינת הגבלה שהוא בחינת יש וכידוע דכל אור הוא בחי' רוחניות של אותו המציאות להיות כחו ומציאותו בלבד אבל בחינת ההתגלות שכבר נגלה הדבר במציאות דבר מה בבחינת יש של הדבר ההוא הוא בחי' כלי המגביל ומתאר את האור כמו בחינת אור החכמה היינו בחינת האור והחיות הרוחני של מציאות השכל והחכמה אך מה שניכר במציאות יש ודבר מה הוא בחינת כלי של אור החכמה וע\"כ מצד בחינת הכלי נקרא חכמה בה\"א כמ\"ש במ\"א באריכות וא\"כ יפלא איך מאיר הארת אין האמיתי שלמעלה מהיות גם בחינת מקור למקור להשתלשלות מציאות דבר מה רק ע\"י בחינת צמצום ומק\"פ כנ\"ל להיות מכחו דוקא בחינת היש של כל מציאות כו'. אמנם הנה זה הדבר יובן ע\"פ ההקדמה הב' והוא מ\"ש בע\"ח דמבחינת הכאת אור המקיף בפנימי משניהם יחד נתהווה שרש בחינת הכלים שהוא בחינת הישות של כל מציאות כנ\"ל. ובאור הדברים הנה מבואר למעלה שבאמת הרי כל ההשתלשלות נמשך מבחינת אותיות די' מאמרות כמו באותיות יהי אור נעשה מציאות האור ואותיות דיהי רקיע כו' והאותיות והצרופים שבהבל הפה ה\"ז בבחינת ממלא דוקא כנ\"ל וגם בחינת המדות והחכמה והרצון והתענוג שבאים בהתלבשות בי\"מ הכל הוא בבחי' ממלא דוקא אך אעפ\"כ עיקר קיום מציאות היש של כל ההשתלשלות הוא נמשך מבחי' סובב שלפני הצמצום דוקא והוא מה שכפל הדבר אחר שכבר אמר יהי אור שבודאי אותיות הללו המציאו את האור מאין ליש חזר ואמר ויהי אור דויהי אור זה נמשך מלמעלה מבחינת הי' מאמרות והוא מבחינת סובב דוקא לפי שבחינת היש של האור שרשו נמשך מבחינת סובב דוקא מטעם הנ\"ל שכך עלה ברצונו להיות בחינת מגביל לכל דבר עד פה תבא כו' כדי שיוכל להיות מציאות אחר כו' וז\"ש כי הוא צוה ברצון הקדום וכבר נבראו כך ממילא כו' חק נתן ולא יעבור ולכאורה לאו רישיה סיפיה דמה ענין חק נתן למה שאמר ברישיה כי הוא צוה כו' אלא מפני שתחלה עלה ברצונו הקדום שיהיה כך וכך במדה והגבלה וז\"ש כי הוא צוה כו' וחק וגבול נתן שם ברצונו הקדום כו' עד\"מ המצייר ומחליט במחשבתו לעצמו עדיין איך שיהיו אופני ציור הבנין כל דבר ודבר במדה וגבול ואח\"כ גוזר ומצוה לעשות כך וכך הרי כל הגבלת דבר ודבר שבצווי המאמר הוא נמשך מאשר הונח ועלה ברצונו ומחשבתו כבר שיהיה הגבלת הציור באופן כך וכך דוקא כו' וד\"ל. ונמצא מובן שמבחינת רצון הקדום שעלה כבר הוא שמאיר בי\"מ להיות כל דבר ודבר במדה כו' שהוא בחינת ההגבלה בבחינת יש (כמו להיות תמונת ישות של האור באותו האופן שהוא עכשיו בגוון לבן ואדום וממשו וכל חלקי טבעו כמו שהוא כך עלה ברצונו כבר ולא יהיה באופן מציאות אחר וכן הרקיע יהיה עגול כדורי ויהיה מורכב מאש ומים כו' וכה\"ג בכל ציור הגבלת התמונה של כל הנבראים כמו העוף בב' כנפים וב' רגלים והבהמה בארבע רגלים והאילן והעשב בתמונתם שהוא בחינת היש התוארי כו' וכמ\"ש במ\"א וד\"ל) וזהו ויאמר ויהי כן שבכל הי\"מ והיינו בחינת המשכת והארת המקיף בבחינת סובב בפנימי שהוא בחינת ממלא להיות"],[2201340170,"בחינת ההגבלה והיש שלכל דבר אחרי התהוותו בבחינת ממלא דוקא ואעפ\"כ נק' בחי' סובב לפי שהוא מקיף לד' עולמות בשוה כי הוא הנותן כח לכל דבר ודבר להיות לו בחינת כלי מגביל כנ\"ל מראש ההשתלשלות עד סופו בהשוואה א' ממש וד\"ל:\n(פט) <b>ויובן</b> זה עד\"מ מבחינת כח ההיולי שבאדם שהוא אינו נתפס בגדר וסוג מציאות דבר מה עד שאינו עול' בשם דבר מה כלל ואעפ\"כ הרי ממנו נמצא כל הכחות הגלויות באדם גם אחרי התהוותם הרי בכל פרטי חלקיהם מאיר שם מבחינת כח ההיולי הפשוט להיות קיום מציאותו בבחינת יש ודבר מה כו' כמו בחינת כח היולי דחכמה שהוא כח נעלם בלתי נתפס עדיין במציאות דבר חכמה בפרט ואינו עולה בשם חכמה רק שהוא כח היולי של כל מיני חכמה דהיינו לכשילמוד כל חכמה מיד ישכיל ויחכם הרי באותו כח היולי דחכמה תלויה כל מיני חכמה שיתלמד והוא הנותן כח לכל חכמה וחכמה בפרט אחרי התהוותה בכל פרטי חלקיה וראיה לדבר שאם אין כח ההיולי טוב ואינו מסוגל כ\"כ ללמוד החכמה הרי הגם שמייגע את עצמו להשיג איזה שכל אין לו קיום כי לא ישיג היטב מפני חסרון כח ההיולי ויש משכיל היטב מפני טוב כח ההיולי שלו כו' וזהו עיקר ההפרש בין החכם לשוטה כידוע וכמ\"כ בשאר כח היולי כמו כח היולי דאומנות שכח ההיולי טוב לכל מיני אומנות לכשילמד לעשות אותם שיהיה אומן טוב בהם ויש חרש חכם שכח היולי שלו למלאכת החרש בלבד ויש שכח היולי שלו טוב למלאכת האריגה בלבד וכה\"ג בלמוד החכמות יש שכח היולי שלו טוב רק לחכמה מיוחדת כמו חכמת הרפואה ולא לאחרת כו' ויש חכם שכח היולי שלו טוב ומסוגל לכל מיני אומנות וכל מיני חכמות לכשילמוד א\"כ הרי בכל פרט ופרט של החכמה והמלאכה שפועל ולומד עיקר קיום מציאות ישותה הוא דוקא מכח ההיולי כו' ואעפ\"כ לא נראה ונגלה ענין המשכה והשפע' בגלוי מכח ההיולי שהרי הוא נעלם ואינו נתפס במציאות שם דבר חכמה ומלאכה כלל וגם מה שהוא בחינת מקור מציאותו הוא בהעל' ולא בגלוי כלל ושוה הארתו בכל מה שילמוד חכמה או מלאכה בלי הפרש לחלק בזה לומר שבלמוד חכמת הרפואה מאיר יותר מבלמוד חכמת התכונה מאחר שכח היולי א' הוא והוא עצמו מושלל מענין מציאות חכמה לגמרי רק שמכחו נמצאו הרי כל מיני חכמה א' הוא כו' וכן בכח היולי לכל מיני מלאכת אומנות מאיר הוא בכולן בשוה כו' וכה\"ג יובן בכללות בחינת כח ההיולי שבנפש שממנו נמצאו כל מיני כחות שבאדם הגלוים כמו ראיה ושמיע' והילוך וריח וכה\"ג ואמתת מציאותם תמיד נמשך מכח ההיולי הכללי כו' וד\"ל ונמצא מובן עכ\"פ שאע\"פ שיש לכל כח וכח פרטי אור וחיות בגלוי בפ\"ע מ\"מ מאיר בכל א' מהם מבחינת כח ההיולי הכללי ושוה הארתו בגדול וקטן כמו אור וחיות של כח השכל הוא מהות בפ\"ע ואור וחיות של כח הראיה הוא מהות בפ\"ע וכן אור וחיות של כח הריח וכח השמיעה וכה\"ג בשאר כחות האברים כולם פנימיים וחצוניים יש לכל א' אור וחיות הגלוי בו מ\"מ כלם מקבלים מבחינת כח ההיולי שבנפש הנעלה שהוא מאיר ונותן כח לכל אור וחיות שבכל כח וכח בפרט אחרי התהוותו דהיינו שהוא נותן כח לאור הראיה לראות ולכח השמיעה לשמוע ולחוטם להריח וכה\"ג לכח השכל להשכיל כו' ולכולם בשוה ממש מטעם הנ\"ל וד\"ל:\n(צ) <b>והנמשל</b> מכל זה יובן למעלה בבחי' סוכ\"ע שמקיף לד' עולמות כו' ומאיר בכל ההשתלשלות מחכמ' ולמטה מטה אחרי התהוותם דוקא להיות מציאות היש שלהם הנקרא בחי' כלי דהיינו גם אחרי התהוות של בחי' אור החכמה למעלה שזהו כמו אור השכל שבאדם הנה מאיר בו מבחי' סובב"],[2201340171,"להיות החכמה במציאות יש בכל פרט שבה שנקרא כלי המגביל לאור כנ\"ל וכן לכל מציאות האורות שנמשכו מבחי' הקו מראשו לסופו בסוף עולם העשיה בכולן מאיר מבחי' סובב דוקא כמו כח ההיולי שממנו נמצאו כל הכחות והוא הנותן כח לכל בחי' ובחי' אחרי התהוותה כו' וד\"ל אבל גוף התהוות החכמה ממקורה הוא נמשך דוקא מבחינת הקו והחוט ולא מבחינת סובב כי מבחי' סובב שלפני הקו א\"א להיות שום התהוות דבר מה אפי' מהות דאור וכח החכמה כנ\"ל אם לא על ידי צמצום ומק\"פ בתחלה שאז נמשך ע\"י בחי' קו כו' וד\"ל (וכמו במשל דכח ההיולי הנ\"ל הנה הגם שממנו נמצא כל מיני חכמות שלומד כנ\"ל מ\"מ מה שממציא איזה שכל וסברא בפרט ענין דבר חכמה זהו נמשך ע\"י הלמוד והעיון מכח ומקור השכל שמאיר באותה שעה רק שזה עצמו לא היה ביכולתו כלל אם לא בחי' כח ההיולי שלו שהוא טוב ומסוגל לכשילמוד שיתחכם כו' וכ\"ה בכח היולי דאומנו' כו' דמה שיכול אומנות בפרט זהו מצד הלמוד שלמד אומנו' זו וא\"א לומר שמה שמצייר הכלי הוא נמשך מכח ההיולי מאחר שאינו בגדר וסוג מלאכה כו' רק אעפ\"כ מה שיש ביכולתו ללמוד מלאכה אומנות זו הוא מכח ההיולי שהוא טוב ומסוגל לזה כו' עד שמציאות קיום האומנות הזאת הוא מכח ההיולי אבל לא גוף התהוות למוד האומנות כו' וד\"ל):\n(צא) <b>ומעתה</b> יש לתרץ הקושיא דלעיל בהפרש שבין התהוות יש דחכמה מסובב כו' ובין התהוות יש גשמי מבחי' סובב שאם מאיר יותר מבחינת סובב ביש גשמי א\"כ אין זה בשוה כו' דהנה באמת אין הפרש כלל לגבי בחינת רצון הקדום שבעצמות הנקרא סובב להיות בחי' יש וכלי המגביל לבחי' חכמה ראשית כל כו' לבחי' התהוות יש וכלי המגביל לסוף ההשתלשלות כמו להיות עשב ופרי גשמי וכה\"ג ששניהם עלו בשוה ברצון הקדום כנ\"ל (במשל דבנין פלטרין או עסק מו\"מ כו' וגם כמובן ממשל דכח ההיולי הנ\"ל ששוה אצלו ליתן כח לכל בחינה העליונה עם בחי' היותר תחתונה שכמו שנותן כח לשכל שבמוח כמ\"כ נותן כח להלוך שברגל בשוה ממש עד שאנו או' שכל מה שנפעל בגלוי יש בכל כחות האדם כמו מה שרואה בעין והולך ברגל וכו' הכל נמשך בבת א' בשוה מבחי' כח ההיולי הכללי להיות נראים ליש אחר התהוותם מאור וחיות הנפש כו' וד\"ל) ונמצא מובן מכל הנ\"ל שא\"א להיות התהוות הגשמיות ממש מבחינת הרוחניות כלל שכל רוחני לא יהווה מהות היש הגשמי וא\"כ מוכרח לומר שהתהוות הגשמיי' נמשך דוקא מבחי' סובב כנ\"ל וראי' לד\"ז מבחי' החכמ' שהיא בחי' הראשית כו' והנה הגם שבחי' החכמה יורדת למטה מטה ברבוי השתלשלות מאצילות לבריאה כו' עד עוה\"ז השפל מ\"מ לא נמצא מזה בחינת התהוות גשמי ממש כמו דברים הגשמיים ממש אלא מתהווה בעוה\"ז בחי' שכל וחכמה האנושית שלנו והוא שיוכל להיות השכלה והשגה בענינים גשמיים אבל מ\"מ בחי' השגה והשכלה זו רוחנית היא רק שאינו משיג ומשכיל רק לדברים הגשמיים אבל לא שמתהווה עצם הדבר הגשמי מבחינת החכמה עליונה (אע\"פ שנאמר כלם בחכמה עשית היינו בחי' החכמה שמלובשת בבחי' השפעת הרוחניות של כל הנמצאים כו' שזה נמשך מבחי' הקו כו') לפי שבחי' החכמה נמשכה בבחינת רוחניות האור דבחי' ממלא שהוא בחי' הקו כו' וא\"א להיות מזה רק בחינת רוחניות ג\"כ רק שיורד בירידות המדרגות עד שמתהווה להיות רוחניות מצומצמת דשכל האנושי שאין לה ערך לבחי' ח\"ע כו' אבל בחי' התהוות הגשמית ממש לא נתהוו' מבחינת החכמה אלא מבחינת סובב דוקא שהוא מה שעלה ברצון הקדום להיות בחי' יש וכלי מגביל כו' ודוגמא לדבר הנה ידוע שכל נפשו' בהמו' הטהורות נמשכו מבחי' פני שור שבמרכבה ונפשות בהמות הטמאות נמשכו מבחי'"],[2201340172,"מרכבה הטמאה שנז' בפ' שמיני כמו גמל ארנבת ושפן וכו' והנה כ\"ז אין ההתהוו' מבחי' מרכבה העליונה רק בבחי' הנפש בלבד דהיינו בחי' הרוחניות של נפש הבהמות הטהורות כו' אבל בחינת הגשמיות של גוף הבהמה בעור ובשר ודם כו' זה לא נתהווה כלל מבחינת רוחניות האור והחיות של המרכבה כו' אלא שרשו נמשך מאשר עלה ברצון הקדום שיהי' בחי' יש וכלי חומר גשמי להגביל את האור והחיות בכל הנמצאים שבכל ההשתלשלות מראשו לסופו כנ\"ל ונמצא מה שנמצא מציאות הגשמיות להלביש לרוחניות הוא נמשך מלמעלה מבחינת מקור הרוחניות וכמו כן בחלק הצומח כמו האתרוג שצומח מן האילן וכה\"ג הנה ודאי ששרש וכח החיו' הרוחני של פרי האתרוג הנה הוא נמשך מבחי' המזל העליון הרוחני שמלובש בכח הצומח שבאילן ע\"פ מאמר תדשא הארץ כו' ועץ עשה פרי כו' וכמו שאמרו אין לך עשב מלמטה שאין לו מזל כו' אבל גופו ומהותו של גשמיות האתרוג שהוא ישותו וגסותו הנראה לעין הוא נמשך מבחינת סובב דוקא שלמעלה מבחינת מקור הרוחניות והחיות של אתרוג זה הנמשך ע\"פ מאמר ועץ עשה פרי כו' שאינו אלא בבחי' ממלא כנ\"ל וד\"ל:\n(צב) <b>ולהבין</b> מ\"ש מהר קח את הלבוש ואת הסוס כו'. והנה יש להבין מהירות זאת לאיזה טעם הוא כי לכאורה למה צריך למהר הדבר כ\"כ וכו'. אך הנה ר\"ת דאת הלבוש ואת הסוס הוא אותיות אהו\"ה והוא שם הידוע אהו\"ה היוצא מר\"ת דפסוק את השמים ואת הארץ כו' שהוא גי' טוב שזהו בחי' יסוד מדרגת יוסף צדיק עליון דאחיד בשמיא ובארעא כו' כמ\"ש כי כל בשמים ובארץ כו' כמ\"ש בכתבי האר\"י ז\"ל (ולזה אמר מהר משום דבחינת שפע דיסוד יוצא ונמשך במהירות דוקא וכמ\"ש עד מהרה ירוץ דברו ומהרה בה\"א שזהו בחי' השפע המגיע לבחי' הנוק' וז\"ש עד מהרה גי' ר\"נ שהוא נר שבת כידוע בעשר הויו\"ת דדכורא שהוא גי' ר\"ס כמ\"ש כי סר לראות כו' ובחי' הנוק' שאינה מקבלת רק חלק הגבורות הוא מספר ק\"ל כידוע בענין נשים דעתן קלות כו' אבל בחינת גבורות שביסוד מגיע לנוק' ואז נק' מהרה בה\"א כו' גי' ר\"נ מפני שה\"ח וה\"ג כלולים ביסוד כא' וה' פעמים ה' הוא כ\"ה וי' פעמים כ\"ה גי' ר\"נ וזהו וחסידיך יברכו כה וכן פי' חנו כה כידוע אבל מהר הוא בחי' דכר בחינת יסוד שזהו מקודם בואם לנוק' שחסר ה\"א כו' וד\"ל) ובאור הדברים הנה יש להקדים תחלה דהשמים הן בחי' לבוש לארץ להלבישה ולהקיפה מכל צדדיה שהרי נאמר נוטה שמים כיריעה ולכן נק' רקיע שפרוש כיריעה ע\"ג הארץ כמו הלבוש שהוא בחי' מקיף לאדם מכל צד (ומאחר שא' נוטה שמים כו' משמע שהארץ נבראת תחלה ואח\"כ נטה עליה הלבוש דשמים כיריעה כמו עד\"מ שעושה אדם אהל לשבת שנוט' היריעה על הארץ כו' וזהו טעם מ\"ד שהארץ נבראת תחלה שנאמר ביום עשות ה' אלקים ארץ ושמים וטעם מ\"ד שהשמים נבראו תחלה שנא' את השמים תחלה מפני שבחי' המקיף קדם תחלה כו' ומ\"ד הג' דשמים וארץ כא' נבראו שנאמר קורא אני עליהם יעמדו יחדו היינו מ\"ש את השמים כו' ואז ר\"ת אהו\"ה דאחיד בשמיא ובארעא שמחברם וכוללם יחד כו' וד\"ל) אך בחי' הלבוש אע\"פ שהוא בחינת מקיף אבל הוא בחי' מסתיר ומעלים לגוף האדם כו' וכדוגמא זאת הן בחינת מחשבה ודבור שאנו רואים שאותיות הדבור באים בגלוי צרופים שונים ומחולקים ברבבות אופנים שונים אבל מחשב' אחת כוללם יחד בסקיר' אחת ומקפת ומלבשת מלמעלה לכל התחלקות צרופי אותיות הללו מראש לסוף הכל בבת אחת וכמו שידוע באדם שחושב מחשבה אחת לבד וכשמביאה בדבור תתחלק לרבבות צרופים שונים וגם בהיות ההתחלקות בדבור ומחשבה זו מקיפם מכל צד ומכ\"ש בהיות הדבור כלול במחשבה שמוקף"],[2201340173,"בתוך המחשבה כו' וכ\"ה ענין השמים והארץ דהארץ כגרגיר חרדל מוקף בעגול כדור השמים שהשמים מקיפים כל מה שיש בארץ בהתחלקות רבות מראשה לסופה בעגול אחד כמו יריעה א' כו' וכמו\"כ יובן ג\"כ ענין הלבוש והסוס דהנה הסוסים הם בחינת אותיות שנק' סוס כמו שהסוס בטל לגבי רוכבו כמו\"כ אותיות הדבור בטלים לגבי המחשבה המקיפם שנק' שמים כנ\"ל (וכן בי' מאמרות אותיות יהי אור בטל לגבי המחשבה הכללית כו') וזהו את הלבוש שהן השמים שהן בחי' מקיפים כלליים לארץ ואת הסוס הוא בחי' הארץ שהן בחי' האותיות וכמו שיש ר\"ת באת השמים ואת הארץ שהוא בחי' יסוד בחינת צדיק עליון דאחיד בשמיא ובארעא כנ\"ל כמו\"כ יש בחינת ומדרגה המחבר הלבוש והסוס וזהו ר\"ת דאת הלבוש ואת הסוס כו' וז\"ש מהר קח את הלבוש כו' למרדכי היהודי כו' ופי' קח את כו' שיקח אותם לחברם יחד כנ\"ל וכ\"כ כי כל בשמים ובארץ דאחיד כו' (ופי' מהר שיהיה אור השפע הולך במהירות לטעם הנ\"ל שבחי' יסוד נקרא צדיק ונקרא טוב כמ\"ש אמרו צדיק כי טוב כו' וכלול חו\"ג אך הגבורות שביסוד מתגברים ביותר בכללות השפע דוקא כמו גבורות גשמים שיורדים בגבורה והוא בחי' גבורה שבחסד כמ\"ש גשם נדבות תניף אלהים שממתיק לה\"ג דאלקים והוא ה\"א דמהרה שעד שם ירוץ דברו דדכורא כמו לרוץ אורח כו' וזהו מהר אותיות רמה כי ג' ידות הן יד הגדולה ויד החזקה שהן בחי' חו\"ג כידוע ויד רמה הוא בחי' ת\"ת ויסוד שכלול מחו\"ג והגבורות גוברים וכמ\"ש מלפני אדון חולי ארץ כו' ובהפוך באת זלע\"ז כתיב ידינו רמה ולא ה' פעל כל זאת כו' וכשהקדושה גובר על סט\"א כתיב סוס ורוכבו שהן דכר ונוק' דקליפה רמה בים כו' וגם כאן מהר קח את הלבוש ואת הסוס שהוא בחי' דכר ונוק' דנגה שהן שמים וארץ דנגה דכתיב אלביש שמים קדרות כו' כשנהפך לטוב ע\"י בחי' הברורים כמשי\"ת בעז\"ה וד\"ל):\n(צג) <b>והנה</b> כתיב יביאו לבוש מלכות אשר לבש בו המלך וסוס אשר רכב עליו המלך ואשר נתן כתר מל' בראשו פי' ואשר נתן כתר מל' בראשו של הסוס כי הנה מבואר למעלה שהאותיות נק' סוסים ובחי' התלבשות והסתר אלקות בגלות בע' שרים דנגה נקרא רוכב על סוס כמו הנה ה' רכב על עב קל ובא מצרים עננים למרכב וכן זכריה ראה המרכבה דסוסים שחורים ולבנים כו' והן בחינת אותיות שנפלו בשבה\"כ מרפ\"ח נצוצים דתהו וידוע שהיה השבירה בבחי' ס\"ג וב\"פ ס\"ג גי' סוס והוא בחי' ב\"ן דנגה שנקרא אותיות כשלאחר הברור דרפ\"ח כו' בבטול היש הנפרד לאין כו' עולה לשרשו בבחי' ס\"ג דתהו אז נעשה בחי' סוס דקדושה וע\"ז נא' כי תרכב על סוסיך בחי' אותיות מרכבותיך ישועה שיש עלייה לרוכב למעלה ממדרגתו והוא בחי' ס\"ג דתהו שלמעלה מבחינת מ\"ה שהו' הרוכב המבר' לב\"ן כו' כנ\"ל וזהו וסוס אשר רכב עליו המלך בחי' מ\"ה שמברר לב\"ן דנגה בזמן הגלות ואמנם עלייתו למעלה מעלה עד בחי' כתר מל' כי כאשר מתהפך חשוכא לנהורא כו' נעשה מזה בחי' כתר למלך העליון וכמ\"ש בעטרה שעטרה לו אמו בחי' עטרת תפארת הכתר בראשו וכמשל עטרת הכתר שעושין אותה מאבנים טובות שהגם שהאבן הוא בחינת דומם אבל אחר הזדככותו מאיר ומבהיק ביותר עד שנעשה לעטרת תפארת בכתר המלך כו' כמו\"כ מבחינת אותיות דנגה שנקרא אבנים כשעולין לשרשן בבחי' ס\"ג דתהו נעשים בחי' עטרת תפארת בראש המלך בחי' ז\"א וכמ\"ש במ\"א בענין סנדל' קושר כתרים לקונו מתפלות ישראל דוקא שהוא מבחינת האותיות דהבל נוגה כשנהפך חשוכא לנהורא בתשובה מעומקא דלבא כו' וזהו ואשר נתן כתר מל' בראשו דסוס לאחר הברור שלו להורות שמכח וגבורת הסוס"],[2201340174,"נעשה כתר המלך וכמ\"ש וסוס מוכן למלחמה כו' דהיינו מה שרכב עליו המלך לברר ברורים דנגה כו' וכמ\"ש ה' איש מלחמה כנ\"ל וד\"ל ובחינת לבוש מל' הוא בחינת המקיף העליון כמ\"ש ה' מלך גאות לבש בחינת התנשאות כמו המלך המרומם כו' והן כמו השמים שמקיפים לארץ וכנ\"ל דארץ הוא בחינת סוס וכמ\"ש והארץ הדם רגלי והשמים שמים לה' כמ\"ש יושב בשמים כו' ונק' לבוש מל' כמו הלבוש שמקיף לאדם כו' כנ\"ל ומ\"ש יביאו לבוש מל' היינו בחי' הברור דשמים דנגה שנאמר בהן אלביש שמים קדרות ושק כו' בחי' הסתר והעלם אך לאחר הברור נעשים בחי' לבוש מל' לתפארת ולכבוד כי עיקר התפארת הוא בלבושים דוקא וכמ\"ש ר\"י קארי למאני' מכבדותא כו' וזהו שלאחר הברור דלבוש דנוגה צוה להלביש את מרדכי היהודי היושב בשער המלך שהוא בחינת יסוד אבא ויסוד ע\"י שיושב בשער המלך בחינת מלכות דאין סוף כמ\"ש ה' מלך גאות לבש כו' וד\"ל וזהו מהר קח את הלבוש כו' דהמן זה שרשו בבחי' דעת דקליפה כמ\"ש ראשית גוים עמלק כו' דז' עכו\"מ הן בבחי' המדות חג\"ת והדעת ראשית הז' מדות רעות והוא כולל חו\"ג שהן שמים וארץ שהוא בחי' לבוש וסוס דנגה לאחר הברור ולזה צוה לו דוקא ליקח הלבוש והסוס ולהלביש את מרדכי להיות יחוד בחינת ת\"ת ומל' דקדושה כו' שעיקר התפארת הוא בלבוש המלך ועיקר הכבוד הוא ברכיבת הסוס אשר רכב עליו המלך ואשר ניתן כתר מל' בראשו וכ\"ז שייך למרדכי היהודי אחר הברור משום דבחכמה אתברירו שהוא בחינת מרדכי בחינת יסוד אבא שעליו נאמר אשר דבר טוב על המלך כו' וד\"ל:\n(צד) <b>ומעתה</b> הנה יש להבין טעם המהירות שאמר מהר קח כו' במהירות דוקא אך הנה יש להקדים תחלה מארז\"ל ע\"פ בעתה אחישנה אם בעתה מהו אחישנה אלא זכו אחישנה לא זכו בעתה דוקא כו' ובאור הענין הנה כתיב קץ שם לחשך שהקליפות וסט\"א נק' חשך המסתיר ומעלים לאור האלקי עד שיוכלו לומר ידינו רמה כו' והוא להיות שאור האלקי מסתתר עליהם בתכלית ההסתר וההעלם עד שאין הקליפות מקבלים רק מבחינת אחוריים וחצוניות דחצוניות ולכן נקרא אלהים אחרים שמקבלים מבחי' אחוריים דקדושה דהיינו בחי' פסולת השפע העליונה דקדושה הנופל בבחינת מותרות ונובלות כו' כידוע אך הנה גם לבחינת פסולת ואחוריים יש שעור ומדה כמה יהיה וכמה יומשך למטה לחצונים והיא ע\"פ מאמר קו המדה שנותן קצבה ושעור לכל ההשתלשלות כידוע וזהו ע\"פ רצון בעל ההשתלשלות נתן חוק וקצבה גם למדה ושעור של יניקות החצונים מאחר שאת זה לעומת זה עשה האלהים כו' והן כ\"ח עתים בחי' טו\"ר עת ללדת ועת למות כו' (וסדרן לכאורה אינו מכוון דב' עתים הראשונים בחי' החסדים קודמים לגבורות והוא מ\"ש עת ללדת ועת לטעת כו' ואח\"כ להפך הגבורות קודמים שהן עת להרוג עת לפרוץ עת לבכות עת ספוד ועת להשליך אבנים כו' ואח\"כ ג' חסדים עת לחבוק עת לבקש עת לשמור ואח\"כ ב' גבורות עת לקרוע עת לחשות ואח\"כ א' בחי' חסד עת לאהוב והב' בחי' גבורה עת מלחמה ובי\"ד עתים השנייים בכ\"ז להפך כו' וזהו בחינת התכללות חו\"ג ומסיים בקו השמאל בעת שלום כו' וד\"ל) וכמ\"ש בזהר ע\"פ ואל יבא בכל עת כו' וזהו קץ שם לחשך שיש שעור וקץ וגבול לכלות אור שפעם הנמדד להם ע\"פ מאמר קו המדה ואז ממילא יאבדו כמ\"ש כי הנה אויביך ה' כו' יאבדו כו' ומ\"ש בפרוח רשעים הוא כדי להשמידם אחר כך וכמ\"ש בלע המות לנצח כו' ואת רוח הטמאה אעביר כו' וכמארז\"ל לע\"ל מביאו הקב\"ה ליצה\"ר ושוחטו והענין ידוע שזהו ע\"פ רצון בעל ההשתלשלות באופן הברור"],[2201340175,"מרפ\"ח נצוצות כו' עד שיושלם הבירור מרפ\"ח כו' שנפלו בשבה\"כ ולזה ניתן זמן קצוב לימי חיי האדם בעוה\"ז כמ\"ש ימי שנותינו בהם שבעי' שנה כו' וכאשר יושלם כל בחי' הבירורים וכמ\"ש והוצאתי את בלעו מפיו כו' אז ממילא אין להחצונים יניקה כלל לפי שזמן וקץ שלהם כבר כלה עפ\"י מאמר קו המדה וכמ\"ש במ\"א בענין כל הקצין כלו כו' שזמן ימות המשיח הרבה קצים כלו מפני שלא נשלם עדיין הברור דנוגה ע\"י תשובה ומע\"ט אבל הקץ אשר שם לחשך כבר כלה כו' ואין קיומם אלא מרפ\"ח נצוצין לבד שעדיין מלובש בהם שצריך ברור והעלאה ע\"י תו\"מ ותשובה (וכמ\"ש בזהר בענין קץ הימין וקץ הימים שנקרא ג\"כ קץ כל בשר כו') וזהו שאמרו רז\"ל זכו אחישנה לא זכו בעתה פי' זכו ישראל בתשובה ומע\"ט בבחי' ברור דעה\"ד טו\"ר בתכלית עד שיוציאו כל הנצוצות דרפ\"ח שנפלו לע' שרים בבחינת תוס' יניקה על זמן הקצוב להם אז אחישנה לזמן הגאולה שזו היא בחי' התגלות מל' דקדושה כמ\"ש בדניאל ועתיק יומין יתב כו' ולה יהב שלטן כו' ומלכותה די לא תתחבל ואע\"פ שבדניאל משמע דזמן גאולה יש לה עת קבוע כמ\"ש עד עת קץ ובסוף מסיים ואתה לך לקץ כו' עד לקץ הימין ולזה מ\"ש אחישנה היינו קודם הזמן ועת קץ הניתן לדניאל אבל לא זכו ישראל בתשובה ומע\"ט אלא אדרבה שמוסיפים בעונות שלהם תוס' יניקה לחצונים שמקבלים מהקדושה יתר על המדה הקצובה להם אזי בהכרח שיתעכב זמן הגאולה עד עת קץ הניתן לדניאל רק שהו' סתום וחתום לא נודע ונגלה בכל העולמות כו' וזהו בעתה עת ה\"א עתה דבחינת המל' בעת הגיע הזמן שלה להיות לה עליה בבחינת פנימית הכתר כמ\"ש וגבה מאד (שזהו בבחינת מל' דא\"ס שבג\"ר דא\"ק כו' כמ\"ש במ\"א) אך בבא עתה דמל' לעלות בפנימית הכתר הגם שאפשר שגם אז לא יושלם הברורים דרפ\"ח מפני שגם אז לא יזכו ישראל בתשובה ומע\"ט כו' עכ\"ז לא ימנע מזה עת קץ הגאולה וזהו שאמרו לא זכו בעתה. דהגם שלא זכו מ\"מ בעתה בהגיע עת קץ הגאולה בהכרח אז שיגאלו אע\"פ שלא זכו כו' והיצה\"ר שבלבם יבוער מעצמו כמ\"ש והסירותי את לב האבן מבשרכם ונתתי לכם לב בשר כו' וכמ\"ש רז\"ל שישחוט ליצה\"ר כו' וד\"ל:\n(צה) <b>וזהו</b> מ\"ש להמן מהר קח כו' היינו שימהר לגמור בחינת הברורים דרפ\"ח שהוא בחי' הלבוש והסוס דנוגה וכשימהר הברורי' ויוציאו כל הטוב מבחי' נוגה ממילא אין להם תקומה עוד כי קצם כבר כלה כנ\"ל ולא היה להם חיות רק מן הטוב שנופל בהם מסטרא דקדושה כמו מעונות ישראל (וכמ\"ש במ\"א שגם באת זלע\"ז יש בחי' סוסים שרצים וגוזלים יניקה וחיות מהקדושה כו' ונק' שודדי לילה כו' ולאחר הברור נהפך לסטרא דקדושה והוא מה שצוה להמן דקליפה ליקח את הסוס להרכיב עליו את מרדכי כו' להיות בבחי' סוס דקדושה כנ\"ל בפי' ואשר נתן כתר מל' בראשו כנ\"ל וד\"ל:\n(צו) <b>ועוד</b> יש לפרש להפך דמ\"ש מהר קח כו' זהו לטובתו דוקא ולא לרעתו דכשימהר הברורים דרפ\"ח כו' שהוא בחינת הלבוש והסוס להלביש את מרדכי היהודי כנ\"ל אזי דוקא יהיה לו תקוה עדיין וכשלא ימהר לא יהיה לו תקוה כלל והענין הוא להפך בפי' בעתה אחישנה דקץ זה אשר שם לחשך ע\"פ מאמר קו המדה כנ\"ל עדיין לא כלה ע\"כ אם זכו ישראל בתשובה ומע\"ט ויתברר על ידם בירורי נוגה במהירות גדול' עד שלא יבא זמן הקץ אשר שם לחשך אז אחישנה לזמן הגאולה והחצוני' לא יאבדו קודם זמנם הקצוב מאחר שעדיין יש להם זמן רב וכבר נתברר הכל ונתהפך מחשוכא לנהורא כו' כל הניצוצות דתהו שלזה היה עיקר כוונת המאציל אז לא יחפוץ בהשתלשלות דאת זלע\"ז כלל והגם שכבר ניתן להם שעור לזמן הרע שבהם יחזור בו מאותו"],[2201340176,"הרצון הקדום שהיה בתחלה כמו בדור המבול דכתיב וינחם ה' כו' וז\"ש בפרוח רשעים כו' להשמדם קודם עת קצם וזהו שא\"ל מהר במהירות גדולה לברר הכל ואז גם לך יש תקוה כמ\"ש אז אהפך אל עמים שפה ברורה כו' כי מ\"ש ואת רוח הטומאה אעביר כו' קאי גם בעכו\"מ שהרי נא' וראו כל בשר כו' ונהרו אליו כל הגוים כי יוסר מהם הרע ג\"כ משום דמה שעכשיו הן בבחי' רע גמור זהו מצד ההשתלשלות דאת זה לעומת זה כו' אבל אחר כל הברורים לא יחפוץ במות המת כו' ומ\"ש להשמדם עדי עד לא קאי רק על בחינת הרע שבהם שיושמד ויבוער לגמרי וכמ\"ש ואת רוח הטומאה אעביר כו' וכמו במזיקין שנא' ואריה כבקר יאכל תבן. לא ירעו ולא ישחיתו כו' וגר זאב עם כבש כו' דאע\"פ שעכשיו יש בזאב וארי רע גמור המזיק וטורף וממית בלי חמלה כלל לעתיד יבוער כל הרע גם בזאב וארי לא יהיה בחי' רע המזיק כלל ע\"כ לא ירעו כו' עד שיגור זאב עם כבש ולא יטרפנה כלל כי יבוער כל בחי' רע מכל הברואים שבעולם שנמשך עליהם רק מצד זוהמת נחש הקדמוני כו' כידוע אבל אם לא ימהר הברורים דרפ\"ח כו' אלא יומשך זמן רב עד שיוקדם זמן עת קץ אשר שם לחשך שיאבדו ממילא הרי אין לך תקו' כלל כי בבא עת קצך תאבד ממילא והיינו כאשר לא זכו ישראל שאז בעתה דוקא ויכלה קצם קודם שיבא עתה דגאולתם (אך א\"כ איך אמר כי אז אהפך אל עמים שפה ברורה ונהרו אליו כו' וכמה כתובים שמורים על הפוך הרע דעכו\"מ לטוב שמזה משמע דאחישנה דודאי זכו דאם לא יזכו ויהיה בעתה הרי יאבדו בזמן קצם ואפשר שכל הכתובי' הללו מדברים גם בלא זכו שיהיה הגאולה בעתה דוקא ואעפ\"כ לא יאבדו החצונים בזמן קצם כי הגם שכלה קצם מקבלים תוס' יניקה ע\"י חטיפה בסוסים הרצים כו' כמ\"ש גוזל אביו כו' או מעונות ישראל וכה\"ג אך א\"כ למה אמר לו מהר כו' אלא מוכרח לאמר לפ\"ז דמהר זה לרעתו ולא לטובתו כפי' דלעיל וד\"ל:\n(צז) <b>ובכ\"ז</b> יובן מ\"ש ראשית גוים עמלק ואחריתו עדי אבד כו' דהנה שרש קליפת עמלק הוא בבחי' הדעת שהוא בחי' ראשית לז' עכו\"מ הכנעני כו' שהן ז' מדות חג\"ת נהי\"מ כו' ולכן קדם עמלק להלחם בישראל ונכנס ראשון יוצא אחרון וזהו ראשית גוים עמלק ואחריתו עדי אבד לגמרי שאחריתו קשה מכל ז' עכו\"מ שהוא עדי אבד בלי תקון כלל משא\"כ לעכו\"מ שיש להם תקוה כמ\"ש אז אהפך אל עמים כו' וגם בעת קצם ששם קץ לא יאבדו לגמרי כי יבוער כל הרע מהם והם יעבדו את ה' כי יבורר ויהופך חשך לאור ולא נא' קץ שם רק לחשך כו' ולע\"ל כתיב גם חשך לא יחשיך כו' אבל עמלק אחריתו עדי אבד לגמרי והטעם הוא לפי שיש הפרש בין ז' עכו\"מ לעמלק דז' עכו\"מ הן ז' מדות רעות וכל מדה רעה בהכרח יש בה תערוב' טוב כל שהוא ולאחר שיבוער הרע מכל וכל ישאר בחי' הטוב שהיה גנוז בהעלם גדול בז' עכו\"מ ומלבד מה שיהופך רע לטוב וחשך לאור שכ\"ז מפני שבמדות חג\"ת כו' יש בחי' עצם ומהות דבר מה כמו החסד הוא מדה ומהות דבר מה רק שחסד דקליפה הוא להתיהר או אהבה רעה כשנהפך לקדושה יהיה מדת אהבה דקדושה כו' וכן הכעס והתפארת והנצוח וכה\"ג כשנהפכין לקדושה הן בחי' מהו' ומציאו' דבר מה משא\"כ מדת עמלק אינה בחי' מדה כלל בעצם ואין בו ממש כלל כי עיקר בחי' עמלק הוא רק בחי' החוצפ' וההתנשאות לבד שבלא טעם כלל ונק' מלכותא בלא תגא כידוע והענין הוא שיש ב' מיני התנשאות הא' ההתנשאות שמצד הגדולה בעצם כמו מלך ושר או עשיר וחכם וגבור וכה\"ג ה\"ז יקרא בשם בחי' יש ודבר אבל ההתנשאות שנק' חוצפה הוא המתנשא רק בדרך חוצפה והעזה לבד שאין לו במה להתנשאות כלל כי חסר מכל מעלה ומדריגה כי הוא"],[2201340177,"פחות הערך וחסר מכל לא חכמה ולא גדולה כלל רק שמעיז פניו בחוצפה לבד וזאת ההתנשאות אין לה ממשות בעצם כלל וכלל ותוכל לפול בקל מאד והענין הוא כי התנשאות הזאת הוא הנק' גסות הרוח שרוחו רמה וגבוה בלתי טעם כלל רק מצד טבע הרוח שהוא מתנשא בטבעו ויובן זה עד\"מ גלי הים שמתנשאים ביותר עד למעלה מעלה כמ\"ש רבב\"ח לדידי חזו לי גלא דימא כו' ש' פרסי כו' והנה ידוע בסבת ההתנשאות וההגבהה של גלי הים שאין זה מצד עצמם כלל וכלל רק מצד הרוח לבד שמגביהם ומנשאם למעלה מעלה ולפי תוקף וחוזק הרוח כן יהיה ערך התנשאות' והגבהתם למעלה עד שברוח סערה חזקה ותקיפה ביותר יגביה הרוח סערה בכחו החזק להגלים הגבה למעלה מעלה ביותר ומיד כשינוח הרוח סערה מזעפו לפי ערך הנחת הרוח כן ערך הנחת הגל מהגבהתו למטה מטה עד שכשישתוק הרוח לגמרי יפול הגל למטה מטה וישתוה עם שאר מי הים כאלו לא היה מעול' כידוע שגלי הים בנוחם יפלו וישתוו לארץ שבשפ' הים כו' שהרי מצד טבע המים הוא להפך שיורדין מגבוה לנמוך ולא לעלות מנמוך לגבוה וא\"כ ההתנשאות ורוממות הגלים מנמוך לגבוה גבוה זהו הפך טבעם לגמרי רק מצד הרוח שמגביה אותם ומיד שינוח הרוח יפלו למטה כפי טבעם שיורדין מגבוה לנמוך וכו' וד\"ל. וכמ\"כ יובן שרש ענין קליפת עמלק שהוא בחינת גסות הרוח רוח גבור' בהתנשאות וחוצפה שאינו מצד עצמה כהתנשאו' של הגדולה וכה\"ג אלא רק הרוח גסה בהתנשאות והגבהה יתירה ע\"כ מעיז בחוצפה בלא טעם כלל לפי שההתנשאות אינה עצמית רק ע\"י הרוח וכשינוח הרוח ממילא יושפל גאותם והתנשאותם למטה מטה כאלו לא היו מעולם כמו גלי הים שע\"י רוח באו וע\"י הנחת הרוח ינוחו ויושפלו ממילא כאלו לא היו מעולם כו' וז\"ש בשוא גליו אתה תשבחם ותורידם כו' כי הרשעים כים נגרש השקט לא יוכל כו' וכמו בכל דור ודור עומדים בעכו\"מ שרים שמתנשאים ומתרוממים כגלי הים ע\"י הרוח שהוא בחינת החוצפה דעמלק מלכותא בלא תגא בלא טעם כלל וכשאון מים כבירים ישאון בשאון ורעש כרעש גלי הים בהתנשאותם הגבה למעלה וכמו המן צורר היהודים שגדלו המלך בהתנשאות וחוצפה בלא טעם והמה שונאי ישראל וצוררי היהודים בתכלית כמו המן בשעתו ואנו רואים שנופלים פתאום מגדולתם ורוממותם למטה מטה כו' כמשל גלי הים לפי שע\"י רוח בא התנשאותם וע\"י רוח ינוחו כו' וכמו שאנו או' והיא שעמדה כו' וד\"ל וכמ\"כ אנו מוציאים במ\"ש בז' מלכי' קדמאין דתהו (ששרש' בבחינת ס\"ג אותיות ג\"ס כמ\"ש כלו ס\"ג כנ\"ל והוא בחינת ס\"ג דס\"ג כו') וימלוך וימת דוימלוך הוא בחינת ההתנשאות יתירה ומיד וימות בבחינת ירידה והשפלה למטה לפי שכל התנשאות שע\"י הרוח מיד בהניח הרוח ינוח ויושפל למטה ממילא כנ\"ל וד\"ל ויובן ד\"ז בתוס' ביאור באופן אחר והוא ממשל הולד בבטן אמו שאנו רואים שהולד נולד מן הברור שבטפה דוקא כידוע דאודם שממנו בשר כו' ולובן שממנו עצמות כו' הכל הוא מן הברור הנברר ממ\"ד ומ\"ן כו' ומן הפסולת גמורים דמ\"ד ומ\"ן שלא נתהווה מזה אפי' צפורניו ושערות כו' הנה מזה מתהווה השליא שהוא עור הולד שמכסה אותו ומקיפו מראשו לרגליו כידוע והנה בהיות הולד בבטן אמו היתה השליא דבוקה בגוף הולד והיה לו ללבוש ומכסה לשמור גופו כו' אך כאשר הולד יוצא לאויר העולם בהולד מבטן אמו אז בהכרח שיופשט גוף הולד מן השליא והשליא תלך לאבוד כי הולד א\"צ לשליא ביציאתו לאויר העולם והשליא מצד עצמה היא מבחינת הפסולת של המ\"ד ומ\"ן כו' לצורך הולד וקיומו בהיותו בבטן אמו בלבד אבל אח\"כ תלך לאבוד ונשלך ארצה כידוע וד\"ל והנמשל מזה יובן ג\"כ בשרש בחי' קליפ' עמלק הנ\"ל דהנה בצאת ישראל ממצרים הדבר דומה לבחינת לידת ולד"],[2201340178,"כמ\"ש ואעבר עליך ואראך מתבוססת בדמיך כו' ובחינת קליפה עמלק שרשו בבחי' הפסולת דשליא כו' בבחינת מקיף כו' אך הגם שבבחינת עבור בבטן המל' שהוא בחינת הגלות דמצרים היה בחינת עמלק ראשית גוים כמו השליא הדבוקה בולד ונעשה שומר כו' אבל אחריתו עדי אבד כמו עד\"מ שמשליכים עור הולד בהולדו וילך לאבוד כנ\"ל וכן יובן גם לעתיד לאחר תשלום כל הברורים דרפ\"ח כו' דהרי ידוע שהשבירה הי' בבחינת המדות שנקרא גופא ויש להם ברור ותקון כנ\"ל אבל בחינת עמלק הוא בחינת השליא שתאבד לגמרי וזהו ואחריתו עדי אבד לגמרי אע\"פ שהו' ראשית גוי' בתחלה כו' וד\"ל ונמצא מובן מב' משלים הללו שאין תקון עצמי לקליפ' עמלק רק אבודו זהו תקונו לפי שמצד עצמו אין בו ממשות כלל ולא כבחי' המדות דז' עכו\"מ כנ\"ל שיש להם תקוה מטעם הנ\"ל בענין ב' משלים אם כמו גלי הים או השליא שאין בו ממש כו' ובזה יובן בתוס' באור ענין מהר קח את הלבוש ואת הסוס כו' דלבוש זה הוא בחינת לבוש דנוגה ששרשו בבחינת חשמל דנוגה שדוגמתו למטה הוא כמו השליא המקיף כו' וכן הסוס הוא ב\"פ ס\"ג אותיות גס כשנהפך בחינת גסות הרוח דהמן לקדושה כמו שאמרו רז\"ל המן מן התורה מנין שנא' המן העץ כו' הוא בחי' הדעת שרש המדות והוא שרש עה\"ד טוב ורע וכמ\"ש ראשית גוים כו' ומטעם הנ\"ל וד\"ל:\n(א) <b>וקבל</b> היהודים את אשר החלו לעשות וארז\"ל אשר החלו במ\"ת כו' וזה פלא גדול לכאורה איך יתכן שבמ\"ת שנא' וכל העם רואים את הקולות כו' ועל כל דבור ודבור פרחה נשמתם כו' כמארז\"ל לא היה רק התחלה כמ\"ש אשר החלו לעשות ובימי אחשורוש קימו וקבלו שגמרו ונתקבל בלבם כו' ויש להבין תחלה שרש ענין מ\"ת הרי אברהם כבר קים כל התורה כמ\"ש עקב אשר שמע אברהם בקולי כו' אך הנה עבודת אברהם הי' באהבה כמ\"ש אברהם אוהבי ובאהבה יש ב' מדרגות רצוא ושוב שנק' אור ישר ואור חוזר והענין ידוע כמ\"ש בס\"י אם רץ לבך שוב כו' שהדביקות הוא ענין המשכת הלב וכלותו כמו כלה שארי ולבבי נכספה וגם כלתה נפשי וכה\"ג והוא מ\"ש אם רץ לבך שהלב חושק ונכסף במרוצה לדבק ולכלל באלקים חיים והוא בחי' רצוא ואחר התשוק' בכלות הנפש שנק' או\"ח מיד הוא בא לבחי' הבטול והוא מה שנסוג אחור מפני האימה עד שלא ימצא מקום לעצמו כלל וכמו וירא העם וינועו ויעמדו מרחק והוא הפך המרוצה שבתשוק' כו' וז\"ש אם רץ לבך שוב כו' וזהו והחיות רצוא ושוב כידוע:\n(ב) <b>ויש</b> להבין למה עבודה זו בבחי' רו\"ש דוקא אך הנה ידוע שיש ב' מדרגות בחי' סובב כ\"ע ובחי' ממלא כ\"ע והן ב' שמות דהוי\"ה ואלקים ועל הרוב לא נזכר שם הוי\"ה רק על בחי' סובב כ\"ע ושם אלקים בבחי' ממלא כ\"ע וגם סובב כ\"ע הוא בבחי' שם היינו שם הוי\"ה שגם הוא נק' שם אלא שהוא שם העצם ושם אלקים הוא שם הפעולה כידוע ומ\"ש והחיות רצוא ושוב כו' דקאי במלאכים זהו מצד שרשם בשם אלקי' חיים שמחי' אותם שכח הפועל בנפעל וכל פעולה בדומה לפועל כו' וכמ\"כ יש בחי' רו\"ש בשם הוי\"ה דסובב כו' וזה היה עבודה דאברהם שנא' בו הלוך ונסוע כו' ועכשיו הוא ענין התו\"מ שהן בבחי' או\"כ לשם הוי\"ה דוקא משא\"כ רצוא ושוב דמלאכים הוא בשם אלקים לבד ויובן זה בהקד' באור ההפרש בין סובב וממלא כו' והוא ע\"פ הידוע במ\"ש יהללו את שם הוי\"ה כי הוא צוה ונבראו לשון ונבראו ממילא ומאליהם שממילא ומאליהם נבראו ואיך יתכן בענין התהוות הבריאה יש מאין שנתהוה מאליו בלי שום כח המהווה אותו כו' ומהו כי הוא צוה למי צוה כו' ומי הוא שצוה כו' אך הוא זה קאי אדסמיך לי' והוא שם הוי\"ה דוקא שהוא צוה ונבראו ממילא כו' והענין הוא כידוע בבחי' סכ\"ע אע\"פ שהוא בחי' מקיף כללי לכל ההשתלשלות"],[2201340179,"דאבי\"ע והוא למעלה מבחי' ההשתלשלות מ\"מ נק' גם הוא בבחינת שם בלבד כמ\"ש את שם הוי\"ה לגבי מהותו ועצמותו ית' ממש ואין לו ערך כלל רק כשם האדם שאינו אלא הוראה על העצם כו' והיינו מפני שגם בחי' סובב שייך לענין ההשתלשלות מאחר שנק' מקיף וסובב עכ\"פ וז\"ש כי עמך מקור חיים כו' כמ\"ש במ\"א אך בזה יתרון מעלתו על בחי' ממלא במה שנקרא סובב ומקיף כעגול המקיף מכל צד שאין בו מעלה ומטה כלל היינו שאין האור והשפע ממנו בא בבחי' השתלשלות עלה ועלול כלל רק בהשוואה אחת לכללות הכל מראש לסוף כא' כידוע וזהו עצמו הטעם שלא נזכר בו ענין הבריאה בלשון התהוות מאתו בפועל אלא בלשון ממילא ומאליו כמ\"ש כי הוא צוה ונבראו ולא אמר וברא בפועל כו' כי הנה דוקא בשם אלקים אמר ברא כמו בראשית ברא אלקים ויברא אלקים כו' וכל העשרה מאמרות הוא דוקא משם אלקים כידוע להיותו בא בבחי' כח השפע אלקי בפ\"מ דהיינו שאותיות הדבור הן עצמן באים בבחי' כח ואור וחיות להחיות ולהוות הבריאה מאין ליש ונקרא כח הפועל בנפעל. בנפעל ממש. שזהו עיקר ענין ההשתלשלות וכמו מאמר יהי אור אותיות הללו דיהי אור הן המהווי' את האור וכן יהי רקיע תדשא הארץ וכידוע בענין יודע הי' בצלאל לצרף אותיות שנבראו בהן שמים וארץ כו' ע\"כ בזה שייך לומר לשון ברא ונקרא בורא הכל או יוצר הכל דהיינו שבורא ומהווה את הכל בפועל מכחו האלקי ממש כו' כמו עד\"מ כח האדם שנמשך בפעולתו אע\"פ שא\"א שיתהווה פעולה מגבלת מבלתי בעל גבול ואין זה כמו כח אדם ממש כמ\"ש במ\"א שגם שם אלקים הוא בא בבחי' אור וזיו לבד אבל הוא בא ג\"כ בשם שפע בפועל והן בחי' המשכת אותיות האלקיים כנ\"ל (ואע\"פ שגם במאמרות דמע\"ב נא' ענין צווי כמו ויאמר אלקים יהי אור וכן ויאמר אלקים תדשא הארץ כו' וכמ\"ש כי הוא אמר ויהי הרי אמירה זו המשכה היא דכאשר אמר בדבור הרי בדבור זה נעשה הבריאה וכמו שאנו אומרים ברוך שאמר והיה העולם ברוך אומר ועושה גוזר ומקים כו' וכן כי הוא אמר ויהי כו' הכוונה שבאמיר' זו עצמה שאמר נעשה כנ\"ל משא\"כ כי הוא צוה ונבראו בשם הוי\"ה הוא ממילא כמשי\"ת) אבל בחי' סובב כ\"ע מאחר שנבדל בערך מבחי' השפעה גם לא בבחי' המשכת אותיות שנק' אור וזיו רק מקיף וסובב הכל כנ\"ל איך שייך לומר בו שבורא ומהווה בפועל מאין ליש מאחר שהוא למעלה מבחי' כח הפועל כו' ע\"כ נאמר בו כי הוא צוה ונבראו ממילא ומאליהם פי' ממילא נמצאו רק ע\"י צווי לבד כי בחי' סובב שהוא מקור כל ההתהוות של הברואים אינה באה שם בדרך כח הפועל כו' כמו בשם אלקים דממלא הנ\"ל רק מאליהם וממילא כמ\"ש כי הוא צוה לבד ונבראו ממילא ומאליהם וד\"ל (ואין זה מובן לכאורה דממ\"נ אם לא שייך כלל ענין התהוות הבריאה בבחי' סובב כי אינו בא בבחי' כח בשם אלקים כלל למה אמר ונבראו גם ממילא לא שייך שם כו' ואם שייך שם ענין הבריאה רק שהוא בא ממילא ומאליו א\"כ במה יש הפרש בין סובב לממלא מאחר שכבר נברא כל בריאת יש מאין ממילא בשם הוי\"ה דבחי' סובב ולמה הוצרך להתהוות הבריא' בבחי' כח הפועל אחר שכבר צוה ונבראו ממילא כו':\n(ג) <b>אך</b> הענין הוא דפי' הוא צוה היינו שצוה ברצונו ומחשבתו שיומשך בדבור באותיות דודאי עיקר התהוות מציאות הנבראים בבחי' יש מאין נמשך מן הדבור אבל קודם שבא אל הדבור הרי נק' מקור החיים שהוא בחי' סובב ומקיף שכולל הכל מה שנברא יש מאין מן הדבור כמחשבה אחת שמקפת כל פרטי אותיות הדבור כידוע אבל מיד שצוה ברצון ומחשבה הרי מה שיצא לגלוי ע\"י הדבור בכח הפועל כנ\"ל כבר נבראו ממילא ומאליהם לפי שאין צמצום אותיות הדבור עושה רק גלוי ההעלם שבמחשבה ונמצא שכל בריאה כבר נמצא"],[2201340180,"ממילא כשהוא במחשבה ואין שייך שם לשון התהוות בפועל אבל כשבא לדבור שייך לשון פועל שבורא כו' וזהו ההפרש בין כי הוא צוה ונבראו ממילא להוא אמר ויהי הוא צוה ויעמוד שקאי על בחינת הפעולה וההמשכה שבאמירה זו וד\"ל:\n(ד) <b>והנה</b> מבואר למעלה שבחי' רצוא ושוב ישנו בב' מדרגות דממלא וסובב והענין הוא דהמלאכים אומרים שירה בכל יום ברו\"ש וכמ\"ש והחיות רצוא ושוב כמראה הבזק כלהב היוצא מן החרסים שיוצא ונכנס וחוזר ויוצא כו' לפי שכח ואור האלקי נכנס בתוך תוכם משם אלקים שהוא לשון כח כמו כח הפועל בנפעל וכן שם אדנ\"י כמ\"ש אדני בם כו' כידוע ומצד שלא יכיל כלי השגתם להכיל האור האלקי יוצא האור מן הכלי בבחי' רצוא וחוזר ונמשך האור ומתישב בהם לפי שאור וחיות אלקי דבחי' ממלא בא ונמשך באופן כזה דוקא שנמשך בהן וחוזר ומסתלק כו' וכל פועל יפעול בפעולתו כדוגמתו ע\"כ גם במלאכים וחיות הקודש נאמר והחיות רצוא ושוב כידוע ובחי' השוב אינו בא מאור העליון מחמת שא\"א להכיל רק אדרבה מאשר יוכל שאת ולהכיל ואח\"כ חוזר האור לצאת כמשל הלהב היוצא שחוזר ונכנס וחוזר כו' (ואע\"פ שנא' בעמדם תרפינה כנפיהן היינו מפני גלוי האור העליון בהם אין בהם כח לעלות עוד בבחי' רצוא אלא מקבלים בתוכם וע\"כ תרפינה כנפיהן כמו הבא לפני המלך שנעשה בבחי' בטול ואינו אלא עומד לקבל אור פניו כו' ונמצא דבחי' הרצוא הוא לאור העליון שלא יכיל הכלי כו' ובחי' השוב הוא מאור העליון שמתישב בהם רק שהוא בבחי' בטול במציאות כו' וכן הוא בבחי' רו\"ש בשם הוי\"ה שלמעלה משם אלקים שנק' סובב כ\"ע והוא כעבודה דאברהם דכתיב ביה והאמין בהוי\"ה דוקא וכל עבודתו היה באהב' ודביקות אמיתית בשם הוי\"ה דבחי' סובב דוק' וכמ\"ש התהלך לפני דוקא ומפני שבחי' סובב הוא למעלה מהשתלשלות כנ\"ל ע\"כ היה באהבתו בחי' רצוא לצאת מן הכלי לגמרי כו' כי לא יכול הכלי להכיל לאור דסובב ולא תוכל לגבול אור האהבה ויוצא מנרתקו וחוזר האור דסובב ומתישב בכלי כנ\"ל ברו\"ש דמלאכים בשם אלקים דממל' שבחי' השוב הוא מאשר האור העליון חוזר ונכנס וחוזר לצאת כו' וד\"ל:\n(ה) <b>והנה</b> כאשר אור האה\"ר לא תוכל להתישב בלב ומוח חוזר האור לצאת כו' כנ\"ל יש בזה ב' אופנים א' מצד רוב התענוג שנקרא אהבה בתענוגים שנכספה וגם כלתה כו' לא יכילנו הכלי או בתענוג שבשכל שלמעל' מכפי המדה שלא יוכל שאת כמו ר\"ע זלגו עיניו דמעות כאשר שמע רזין דאורייתא דלאו כל מוחא סביל כו' והב' מהפוכו והוא מרוב הצער מהעדר האור זה כמה כאשר יראה אור גדול ביותר יבא לידי בכיה בדמעות לפי שזהו למעלה מכלי המוח ידחקו כלי המוח ויצאו דמעות כידוע שהדמעות באות מן המותרות של המוח כו' כאשר ידחקו כלי המוח מהכיל אם עונג או צער כו' והנה לעתיד לבא כתיב בבכי יבואו כו' לפי שלע\"ל יהיה בחי' התגלות דשם הוי\"ה בחי' סובב וכמ\"ש ונגלה כבוד הוי\"ה כו' יהיה בזה ב' האופנים הנ\"ל דבר והפוכו כא' דהיינו שיבכו בדמעות מחמת דחיקת כלי המוח שלא יכילו האור הגדול מרוב ענג ושמחה ואהבה שלא יכיל כלי המוח והלב כלל כנ\"ל בענין סבת יציאת הדמעות והב' מרוב צער ומרירות על העבר אשר היו בחשך בזמן הגלות ומתוך החשך יצאו לראות באור גדול כזה יבכו כמ\"ש העם ההלכים בחשך ראו אור גדול כו' וזהו בבכי יבואו בבכיה של שמחה ובכיה של צער כא' כו' דהא בהא תליא והיו לאחדים וד\"ל:\n(ו) <b>ואמנם</b> הנה כדי שיוכל האור להתישב בכלי ולא יצא האור דשם הוי\"ה בבחינת רצוא כו' הנה זהו עכשיו בקיום התו\"מ שרמ\"ח מ\"ע"],[2201340181,"נקראים רמ\"ח אברין דמלכא ועד\"מ אברי האד' שהאור וחיות הנפש מתישב בהם וכללות האור והחיות נמשך מן המוח לכל האברים כו' כך למעלה במצות הוי\"ה שבכל מצוה מתישב אור דשם הוי\"ה בכלי המצות כמו במצות הצדקה וחסד שנק' דרועא ימינא כו' ולכן מצות ת\"ת כנגד כולן כמו המוח שהוא מקור לכל חיות האברים כידוע וד\"ל ואע\"פ שכל המצות הן בבחינת או\"כ שזהו בחי' השוב מ\"מ אין בחינת השוב אלא אחר רצוא כו' ולכך יש בכללות המצות ג\"כ בחי' רו\"ש שהוא בחינת או\"י ואו\"ח והן ה\"ח דרמ\"ח מ\"ע בכלל וה\"ג דשס\"ה ל\"ת בכלל שזהו נכלל באנכי ולא יהיה לך כו' ורמ\"ח מ\"ע שהן בבחי' החסדים דאור ישר וכך עיקר הענין שלהם הוא בכלים דוקא אבל הל\"ת הוא בבחי' הגבורות דאו\"ח ע\"כ באים רק במניעת המעשה דסור מרע כו' וכמש\"ל בענין שמי עם י\"ה שס\"ה ל\"ת כו' והיינו ענין העוה\"ב שבא מן המצות שנאמר בו להנחיל אוהבי יש דוקא וד\"ל:\n(ז) <b>ובזה</b> יובן כל עיקר ענין מעלת מ\"ת דאע\"פ שאברהם כבר קים כל התו\"מ כמ\"ש עקב אשר שמע אברהם בקולי כו' היינו רק במה שהיתה עבודתו באהבה ודבקות בבחי' רו\"ש כמ\"ש הלוך ונסוע כו' שזהו כללות כל המצות כו' וכידוע דאהבה שרש רמ\"ח מ\"ע ויראה שרש שס\"ה ל\"ת ורו\"ש הן אהוי\"ר שכלולים זע\"ז והיו לאחדים וממילא נכלל באוי\"ר כל מעשה המצות כנ\"ל אבל מ\"מ הרי נעוץ תחלתן בסופן וסופן כו' דהמעשה עיקר והוא כאשר בא האור בכלי דוקא שהיא למעלה מבחינת רו\"ש ברוחניות דמלאכים בשם אלקים כנ\"ל וגם למעלה מבחינת רו\"ש דאברהם בשם הוי\"ה כנ\"ל וזה היה ענין קבלת התורה כאשר אמרו בני ישראל נעשה ונשמע שע\"ז ארז\"ל מי גלה לבני רז זה שמ\"ה משתמשין בו שהקדימו נעשה לנשמע כמ\"ש במלאכים גבורי כח עושי דברו והדר לשמוע בקול דברו כו' והענין הוא דהעשי' היינו בחינת הכלי לאור והוא מעשה המצוה בפ\"מ ואח\"כ השמיעה שהיא בחינת האור כידוע והם הקדימו נעשה לנשמע היינו שהקדימו לעשות בחינת הכלי קודם האור משום דסוף מעשה עלה במחשבה תחלה (וכמ\"ד ארץ קדמה לשמים כמש\"ל) והוא הרז שמ\"ה שנק' גבורי כח עושי דברו והדר לשמוע כו' ומשום דנעוץ תחלתן בסופן דוקא ע\"כ הוא למעלה גם מרצוא ושוב דאברהם וראיה ממ\"ש וארא אל אברהם כו' באל שדי ושמי הוי\"ה ממש לא נודעתי להם רק במ\"ת לבד וד\"ל (ומ\"ש מי גלה לבני רז זה שמ\"ה כו' הלא המלאכים לא יכלו לקבל התו\"מ כידוע בענין תנה הודך על השמים כו' וכנ\"ל בבחינת רו\"ש דמלאכים שהוא רק בשם אלקים לבד למטה ממדרגת רו\"ש דאברהם כו' הענין הוא דמ\"ה הללו הוא שנמשך במ\"ת לעשות לבנ\"י ב' כתרים א' כנגד נעשה וא' כנגד נשמע והוא כשירד ה' על הר סיני כמשי\"ת בסמוך בענין כי תרכב על סוסיך כו' וד\"ל:\n(ח) <b>וזהו</b> וקבל היהודים את אשר החלו לעשות דהנה במ\"ת כשאמרו נעשה ונשמע היה ההתחל' והוא מה שאמרו נעשה תחלה ואח\"כ נשמע שהוא לעשות בחי' הכלים תחלה לאורות והוא כדי שיתלבש האור בכלי ויתישב בו דוקא משום דנעוץ תחלתן בסופן דוקא וכמ\"ש סוף דבר כו' את האלהים ירא ואת מצותיו שמור בפ\"מ כי זה כל האדם דאורות דע\"ס כו' אך במ\"ת לא היה אז רק התחלת המעשה של הכלים וכמו שאמרו נעשה כו' שהוא רק התחלת מעשה לבד אבל בימי אחשורוש קימו וקבלו היהודים את אשר החלו לעשות במ\"ת והוא שגמרו למעשה זו שכבר החלו לעשות במ\"ת כו' דהיינו כשאמרו נעשה לא עשו עדיין גמר המלאכה ובימי אחשורוש גמרו את אשר החלו בזמן מ\"ת כו' וזה פלא גדול דאיך אפשר דבמ\"ת שעמדו בהר וראו ושמעו והקדימו"],[2201340182,"נעשה לנשמע לא היה גמר מעשה ובימי אחשורוש נעשה גמר מעשה. אך הענין הוא כידוע שבימי אחשורוש היה לבנ\"י מס\"נ ממש כל אותה השנה בגזרת המן צורר היהודים שבקש לאבדם שנעשה הסכם אצל כלם מגדול עד קטן נשים וטף והוחלט אצלם שהגם שהם נתונים מדת גזרת המלך ליהרג כלם לא ימירו דתם בשום אופן גם אם יהרגו כולם ויאבדם לגמרי לא עלה מחשבת חוץ בלבם ח\"ו וא\"כ הרי כלם היו מזומנים ומוכנים להריגה על קדה\"ש בפ\"מ שאין זה נקרא מס\"נ בכח ולא בפ\"מ מאחר שהיו מוכנים להריגה בפ\"מ וידוע בענין מס\"נ בפ\"מ ששרשו מגיע למעלה מעלה מאד נעלה גם מתו\"מ והוא במהותו ועצמותו ית' כי מס\"נ בפ\"מ זהו למעלה מן הטעם והרצון לגמרי כו' ולזאת אין מס\"נ נכתב בתורה בשם צווי כי ירושה היא בטבעיות מן האבות ולזאת כאשר עולה למעלה מעלה כ\"כ מצד יציאות האור מן הכלי לגמרי בבחינת או\"ח אל העצמות ממש הרי ודאי חוזר ונמשך להם האור ע\"י עליה זו מאותו מקום ומדרגה העליונה שעלו לשם ע\"י מס\"נ שלהם בהסכם המוחלט כנ\"ל והוא שנמשך להם האור ממהות ועצמות אא\"ס ב\"ה עד שניתן להם התורה כמו שהיא במהותו ועצמותו ממש שהיא בבחינת מקיף ולבוש הגם שהוא האור היותר גבוה כמ\"ש עטה אור כשלמה כו' הרי היותר גבוה יותר יוכל לירד ולהשפיל ולהתישב וזהו שנמשך להם בחינת אור דתורה בבחינת לבוש מלכות כמ\"ש יביאו לבוש מלכות אשר לבש בו המלך כנ\"ל שז\"ש על התורה עטה אור כשלמה שנק' לבוש מל' אשר לבש בו המלך קודם שהאציל וברא כו' וכמו\"כ בעשיית המצות שהן בחינת כלים מכלים שונים לבחינת אא\"ס ב\"ה כמו שהיה בעצמותו ממש ונקרא סוס אשר רכב עליו המלך כנ\"ל וכידוע דאור נקרא רוכב והכלי נקרא סוס לפי שמלביש לאור והאור רוכב עליו כמו אותיות המלבישים לאור השכל או אור המדות וכמ\"ש במ\"א והן רמ\"ח מ\"ע שנק' רמ\"ח אברין דמלכא כו' ומצד בחינת מס\"נ שלהם כנ\"ל זכו שיומשך להם תו\"מ ממקום הנעלה הרבה ביותר מכמו שהיה בזמן מ\"ת אע\"פ שקבלו ברצון כשאמרו נעשה ונשמע כו' וזהו וקבל היהודים בימי אחשורוש את אשר החלו לעשות בזמן מ\"ת שאז לא היה הרצון ע\"י מס\"נ רק שהיה רצונם לקבל ובמעשה דוקא אך זהו רק התחלה אבל ע\"י מס\"נ נגמר קבלת הרצון שהיה אז במ\"ת מטעם הנ\"ל שמס\"נ בפ\"מ עולה על הכל עד שיש בכחו לקים ולגמור כל קבלת תו\"מ שהחלו לעשות בזמן מ\"ת וד\"ל:\n(ט) <b>ולהבין</b> זה בתוס' באור ואיך שע\"י מס\"נ זכו שיומשך בחי' לבוש מל' וסוס אשר רכב כו' שהן בחי' תו\"מ העליונים הנה יש להקדים באור ענין מ\"ש כי תרכב על סוסיך מרכבתיך ישועה פי' סוסיך הן ב' מיני סוס א' הרץ בכחו למעלה כמו בגובה ההר גבוה שלא היה יכול לילך ברגליו כלל והסוס נושא את הרוכב עליו עד למעלה והסוס הב' הוא אשר בגבורתו נושא לעמק כל המשא עליו ולא יכשל וגם במישור רץ במהירות שאין זה בכח אדם (וכך הן בחי' האותיות שנק' סוסים כידוע שיש ב' מיני אותיות שנק' כלים לאור השכל שמגביהים ומנשאים את האור למעלה מעלה בעומק אחר עומק כו' ויש אותיות שבכחן להוריד אור השכל עד למטה מטה ביותר להכיל בתוכן כל הסתום וגנוז כו' להורידו למטה (וכמו ר\"ע היה דורש על כל קוץ כו' להביא לגלוי למטה מטה ביותר ולהפך יש באותיות כמו בטנת\"א רזין וסודות בעלוי אחר עלוי עד רום המעלות והכל היו במ\"ת בי' הדברות וד\"ל) והדוגמא מזה יובן למעלה במרכב' העליונה שנושא את הרוכב שהוא מ\"ש ועל דמות הכסא דמות כמראה אדם כו' שהן כמו ופני אריה אל הימין כו' שיש במרכבה מעלה יתירה להעלות לאדם העליון הרוכב עד רום המעלות כמשל הסוס שרץ"],[2201340183,"למעלה כו' וכן יש במרכבה זו להוריד גלוי האור האלקי למטה מטה כמו גלוי שכינה לנביאים וכה\"ג בגלוי שכינה בהיכל ק\"ק וכן היה במ\"ת דכתיב וירד ה' על הר סיני שירד עם המרכבה שלו (והן המ\"ה הנ\"ל שאמרו מי גלה רז זה כו' וז\"ש על מ\"ת דוקא כי תרכב על סוסיך שהן בחינת מרכבה עליונה שבכחן להוריד את הרוכב כו' כמו שיש בכחן להעלות את הרוכב כנ\"ל ובמ\"ת היו ב' מיני מרכבות הללו ונק' סוסיך והיינו ענין התו\"מ שנקרא מרכבה לרוכב מפני שהן בחינת כלים לאורות עליונים כמו כל מצוה היא בחינת כלי לאור הוי\"ה שביכולתו לעלות לאור לרום המעלות ויש עוד מעלה במעשה המצות שנק' מרכבה והיינו בחינת כלי לאור שהוא הרוכב להוריד ולהמשיך בחינת גלוי אור האלקי למטה מטה ביותר וזהו מרכבתיך ישוע' מרכבתיך ל' רבים לפי שיש הרבה מצות שהן כלים לאורות להעלותם למעלה ויש הרבה מצות שהן כלים לאורות להוריד למטה כמו מצות צצית ותפלין ות\"ת וצדקה הוא להמשיך גלוי אא\"ס למטה במוחין בחכמה וחסד וכן סוכה ולולב וכה\"ג ובתרומות ומעשרות וקרבנות הוא בחינת ההעלאה למעלה מעלה כו' והתורה כלולה משניהם ע\"כ נק' מרכבתיך ל' רבים (וכמ\"ש בזהר פ' בשלח בענין רתיכין ומשריין כו') ומ\"ש מרכבותיך ישועה היינו ישועה לרוכב על המרכבה בשני אופנים הנ\"ל בירידה ועליה הכל ביתר מכפי כח הרוכב בעצמו שלא היה יכול מצד כח עצמו לעלות כ\"כ ולא לירד כ\"כ רק ע\"י המרכבה שנושאו הגבה למעלה ומורידו למטה מטה והוא רק ע\"י התלבשות האורות בכלים מכלים שונים שהן מעשה המצות דוקא וד\"ל וזהו כללות ענין וסוס אשר רכב עליו המלך שזהו בשעת מ\"ת דכתיב ביה כי תרכב על סוסיך כו' כנ\"ל וד\"ל:\n(י) <b>אך</b> הנה יש להבין מ\"ש וסוס אשר רכב כו' סוס א' לבד דלפי הנ\"ל היה במ\"ת ב' מיני סוסים כמ\"ש כי תרכב על סוסיך כנ\"ל אמנם הענין הוא דגם בסוס א' יש ב' מדרגות הנ\"ל בעליה וירידה שזהו העלאה והמשכה בחינת או\"ח ובחינת או\"י דהנה בגימטריא סוס יש ב\"פ ס\"ג וידוע דפי' ס\"ג הוא אותיות גס שהוא בחינת הגאות והתנשאות והיינו א' בבחינת או\"ח וא' בבחינת או\"י שהוא בחינת העלאה ובחינת ההמשכה הנ\"ל בענין המרכבה לגבי הרוכב וזהו וסוס אשר כו' דסוס זה כולל ב' מיני מרכבות הנ\"ל בעליה וירידה שא' ע\"ז כי תרכב על סוסיך ב' סוסים כנ\"ל וד\"ל ובאור הדברים הנה ידוע דאת זלע\"ז עשה כו' דכמו שיש בסט\"א בחינת הגסות והתנשאות כקליפה דעמלק שהוא בחינת חוצפה יתירה כו' וזהו סוס דקליפה כמו סוס ורוכבו כו' וכמ\"ש לסוסתי ברכבי פרעה כו' וכמו\"כ לנגד זה להשפיל גאות דקליפה הוא בחינת סוס דקדושה וכמאמר רז\"ל ע\"פ ביום ההוא יהיה על מצלות הסוס קדש לה' כל מה שהסוס רץ ומיצל כו' והענין הוא כמ\"ש ז\"ל עמ\"ש כי גאה גאה שהוא גאה על גיוותניא שהן עכו\"מ שהן גאים הוא רם ומתנשא עליהם בגאות האלקי כמ\"ש רם על כל גוים ה' שעל הגוים דוקא הוא רם ומתנשא פי' שמסתלק ומתנשא מהם לפי שמטבע הרוממו' העצמות להתגאו' על הגאים דוקא להשפילם ולהגביה שפלים ומפני שהוא ית' נקרא מלך מרומם לבדו ברוממות העצמות שלגדולתו אין חקר ומתנשא מימות עולם כו' ע\"כ על הגאים דוקא הוא מתנשא וע\"כ נקרא רם על כל גוים דוקא הוא בבחינת רוממות והתנשאות וכמ\"ש כי גאה גאה גאה על גיוותניא דוקא אבל על השפלים ונבזים ונמוכי רוח אדרבה שם הוא יורד ושוכן כמו על ישראל שנתונים לעפר מרמס ונבזים ושפלים מאד בעיני העכו\"ם בהם הוא שוכן וכמו על אברהם שאמר ואנכי עפר ואפר כו' שם דוקא יורד ושוכן מן ההעלם לגלוי וכמ\"ש כי רם ה' ושפל יראה וכתיב מרום"],[2201340184,"וקדוש אשכון את מי אשכון את דכא ושפל רוח ואל זה אביט אל עני ונכה רוח כו' כי טבע הרם ברוממות האמתי להגביה שפלים ולרחמם ביותר וכמו שאנו רואים במלך ב\"ו שכל שהוא מרומם במלכותו יותר יותר ישפיל גאים ויתנשא עליהם ביותר ויותר יגביה שפלים לרחמם בהשגחה יתירה וזהו כבודו וגדלו דוקא כידוע וכן יובן למעלה במלכותו ית' דכתיב ה' מלך גאות לבש כי לפי ערך רוממות גאותו והתנשאות עצמותו כך הוא גאה גאה להשפיל גאים ולהגבי' שפלים וכמאמר הזהר דיורא דקב\"ה באנון מאנין תבירין דוקא כעני ונכה רוח דכא ושפל רוח כו' שם דירתו דוקא וד\"ל (וראיה לזה הוא מ\"ש ונפשי כעפר לכל כו' פתח לבי בתורתך ולכאורה מה שייכות יש להם זע\"ז אך באמת הא בהא תליא דכאשר נפשי כעפר ממש בשפלות ורוח נשברה נבזה בעיניו נמאס אזי נפתח לבו בעזר העליון שנמשך התעוררותו לפתוח לבו בתורת ה' וז\"ש ונפשי כעפר כו' אז ודאי פתח לבי בתורתך דפתיחת הלב מלמעלה אינו אלא כשנפשו כעפר דוקא והוא מטעם הנ\"ל דעל גאים הוא מתנשא ומסתלק וז\"ש לא בשמים היא לא תמצא בגסי הרוח כו' אבל על שפלים הוא משפיל את עצמו ונמשך עליהם כי רם ה' ושפל יראה ותועבת ה' כל גבה לב מטעם הנ\"ל וד\"ל):\n(יא) <b>והנה</b> ישראל שבאותו הדור בימי המן היו כל אותה השנה בתכלית השפלות עד שהיו נמשלים לעפר ממש כי הרי היו הפקר גמור להריגה לכל מי שירצה לאבד ולהשחית וללחוץ ולדחוק עד הנפש ועד בכלל (וגם בכל גלות לוחצים ודוחקים ביותר עד הנפש כו' ונבזים ושפלים ביותר וגוזרים גזרות קשות וכמ\"ש לא א' בלבד עמד כו' אבל אינו ניכר ונגלה כלל לישראל כי מה שאמר על עמך יערימו סוד כו' אמרו לכו ונכחידם מגוי ולא יזכר שם ישראל עוד הרי הוא אומר יערימו סוד כו' והם גוזרים כל גזרות קשות בסוד וה' מבטל ואין הנס ידוע אבל בימי המן הרי נודע' הגזרה וקבלו עליהם בפ\"מ כו') וע\"כ זכו לב' דברים להיות מתגלה בהם מבחינת מהותו ועצמותו רוממות אא\"ס ב\"ה ולהיות האור מתישב בכלים שלהם כנ\"ל וזהו דבר והפוכו לכאור' שאם זכו לגלוי אור העצמות ממש איך יכול להיות שישכון בכלי' מוגבלים שלהם אך הענין הוא שיש בכאן ב' טעמים א' ע\"י מס\"נ שלהם שהיו מוכנים להריגה בפ\"מ שבזה עשו העלאת מ\"ן למעלה מעלה ממש שהוא בחינת או\"ח אל העצמות ממש ברום המעלות אך א\"כ לא היה יכול האור דעצמות ממש לבא למטה לשכון בתוך כליהם והטעם הב' לבד המס\"נ שלהם הרי היו אז בתכלית השפלות העמוקה כעפר ממש שזה היה הגורם שירד אור הרוממות העצמו' למטה מטה דוקא להתישב האור בתוך כליהם דוקא לפי שזהו מטבע הרוממות היותר נעלה שישכון דוקא בדבר השפל ביותר כנ\"ל במ\"ש ואל זה אביט כו' ועי\"ז דוקא זכו שיהי' גלוי אור העצמות שוכן בהם לפי אופן כליהם המוגבלים דעומק רום שורה דוקא בעומק תחת כמ\"ש כי רם ה' ושפל יראה כנ\"ל ואם לא היה המס\"נ הרי לא היו מעוררים אתערותא דלעילא במהותו ועצמותו ממש ובמס\"נ בלא שפלות העצום לא היה יורד האור למטה כ\"כ ע\"כ שניהם כאחד טובים היו שבהם וע\"י זכו להיות גלוי אור העצמות בתוכם ממש וד\"ל וזהו וקבל היהודים את אשר החלו לעשות במ\"ת דבשעת מ\"ת הגם דכתיב כי תרכב על סוסיך בבחינת או\"ח ואו\"י כנ\"ל לא היה זה ממקום הגבוה מאד נעלה כזה רק החלו אז לעשות בחינת הכלים לאורות כו' כנ\"ל אבל גמר הקבלה לתכליתה ולהיות בחינת כלים גמורים היה זה בימי אחשורוש דוקא דהיינו שקבלו היהודים ממקום עליון ביותר שהוא עצמות א\"ס ב\"ה ממש ע\"י מס\"נ"],[2201340185,"שלהם ונעשה בחינת כלים גמורים להשראת עצמותו ית' ע\"י בחינת השפלות העצום כנ\"ל עד שמזה נעשה מקור קיום חזק לתו\"מ שיהיו כלים לאורות כנ\"ל וזהו וקבל היהודים ל' יחיד ולא אמר וקבלו היהודים לפי שהקבלה הוא מבחינת יחיד חי העולמים ונעשים בחינת כלל א' כאיש א' ממש כי השפלות העצום שוה ומשוה קטן וגדול כו' וד\"ל:\n(יב) <b>וזהו</b> וסוס אשר רכב עליו המלך דהנה מ\"ש במ\"ת כי תרכב על סוסיך הן ב' מיני סוס הנ\"ל א' בבחינת או\"ח בעליה למעלה מעלה והב' בבחינת או\"י בירידה מטה מטה וזהו שנחלקו לשנים במ\"ת בענין התו\"מ כנ\"ל אך שרש שרשם הוא בבחינת סוס א' אשר רכב עליו המלך דהיינו שנמשך מן בחינת התנשאות דמל' דקדושה כמ\"ש ה' מלך גאות לבש והיינו יביאו לבוש מל' הוא התנשאות העצמות ממש אך מה שמצד רוממות העצמות הוא גאה גאה גאה על גיוותניא דוקא להשפיל גאים זהו בחינת ס\"ג דקדושה שהוא בחינת גס והוא כמו המשל של הסוס הא' שהוא רץ בגובה כו' שהוא בבחינת או\"ח דוקא ומה שמצד הרוממות וההתנשאות דוקא הוא יורד לשכון בשפלים ולהגביהם כנ\"ל זהו בחינת הסוס הב' שהוא כמשל היורד לעמק כו' והוא בחינת ס\"ג הב' דבחינת או\"י ושניהם היו לאחדים דהא בהא תליא ממש כנ\"ל וע\"כ נכללו שניהם בסוס א' שהוא ב\"פ ס\"ג כנ\"ל וזהו שאז\"ל כל מה שהסוס רץ ומיצל כו' שהוא הסוס אשר רכב עליו המלך להשפיל גאים ולהגביה שפלים כו' שמזה נמשך ממילא ב' מיני סוס דאו\"י ואו\"ח שבתו\"מ שע\"ז אמר בשעת מ\"ת כי תרכב על סוסיך דבסוס הא' הוא מ\"ש לא יהיה לך כו' מפני שירדה שנאה לעכו\"ם להשפיל גאים וסוס הב' בבחינת או\"י דאנכי שכולל רמ\"ח מ\"ע כדי להגביה שפלים כו' ומטעם הנ\"ל בענין וקבל כו' ע\"כ אמר כאן דוקא וסוס שכולל ב' מיני סוסים שבמ\"ת וד\"ל (וזהו שבקי\"ס אמר סוס ורוכבו רמה בים שהן סוס ב\"פ ג\"ס דקליפה רמה ל' רוממות ול' השלכה כמ\"ש במ\"א והיינו דבר והפוכו כא' והוא כאשר ירצה ה' להשפיל גאים ומרומם אותם בתחלה להיות גאים ומתנשאים כו' ואז גאה גאה מתנשא עליהם להשפילם וכמו בסנחרב ונבוכדנצר וכמו שמצינו בכתובים רבים וכמו\"כ ממש הוא בכל דור ודור ממש ומה שלהשפיל גאים דס\"ג דקליפה שהוא סוס ורוכבו תחל' רמה להיות רם על כל גוים הנ\"ל ואח\"כ השלכ' להשפיל' משום דאת זה כו' וזהו לסוסתי ברכבי פרעה דמיתיך רעיתי שכמו שפרעה היה סוס ורוכבו כן נלחם עמהם בבחינת ב\"פ ס\"ג דקדושה):\n(יג) <b>ובכל</b> זה יובן מה שעיקר קיום התו\"מ תלוי בישראל דוקא ולא בעכו\"ם שהרי עכו\"ם שמניח תפלין ועוסק בתורה אינו ממשיך כלום (רק ז' מצות ב\"נ לבד) וגם במצות הצדקה שנאמר צדקה תרומם גוי היינו לישראל דוקא ואדרבה כתיב וחסד לאמים חטאת ואע\"פ שחסד זה מחיה רוח שפלים ולמה נחשב לחטאת אם מחיה נפש כמו החסד דישראל אך מפני שלא נצטוו על הצדקה וחסד ע\"פ התורה רק מה שעושין חסד מצד טבען הרי אמרו בזהר דכל חסד דעבדין לגרמייהו עבדין וראיה לדבר ממ\"ש האומר סלע זה לצדקה בשביל שיחיה בני ה\"ז צדיק גמור ודוקא בישראל כו' לפי שכח זה דבחי' הבטול מכל וכל רק לעשות רצון ה' לבדו כמ\"ש במ\"ת כל אשר דבר ה' נעשה אין זה רק בישראל לבדם כו' והוא מפני בחינת השפלות באמת שיש בהם ירושה כמו טבע בנפשם מאבותיהם מאברהם שעשה עצמו עפר כו' שמחמת זה נפתח כוונה שבלב במצות רק לעשות רצון ה' לבד וכנ\"ל בפי' ונפשי כעפר או פתח לבי שהיא כוונת הלב במצוה דמצות צריכות כוונה אבל עכו\"מ שירושתם מאבותיהם בבחי' הגאות וההתנשאות שלזה נאמר בהם רם על כל גוים כנ\"ל ע\"כ א\"א שיעשו"],[2201340186,"המצוה בכוונה דבטול רצון כנ\"ל ע\"כ אינם ממשיכים כלום ולא להם ניתנו כי בלא שפלות ורעותא דלבא אין שום המשכה מלמעלה וכידוע בפי' אם ישים אליו לבו דוקא אזי רוחו כו' וכמו\"כ הוא בכל א' מצד הגסות שבו לא יוכל לעשות מצוה בכוונה ורעותא דלבא (רק לגרמיה ולהתנשאות כחסד לאמים חטאת שמוסיף יניקה ושפע להיכלות החיצונים הנק' חטאת כמ\"ש לפתח חטאת רובץ מפני שזה החסד הוא מטוב שבנוגה וזהו דלגרמייהו עבדין להוסיף להם יניקה כו') (וכמו\"כ גם בישראל א' אמרו אחיכם שנאיכם מנדיכם למען שמי יכבד ה' שעושין מצות רק לגרמיי' למען שמי כו'):\n(יד) <b>ובכ\"ז</b> יובן מה שאמר המן יביאו לבוש מל' כו' וסוס אשר רכב כו' דהמן הוא בחי' הגסות דקליפה ולכן אמר המן בלבו למי יחפוץ המלך לעשות יקר יותר ממני כו' דהנה מבואר למעלה דלבוש מל' הוא אור לבוש דתורה והסוס אשר כו' הן בחינת המשכות המצות באו\"י ואו\"ח כנ\"ל שזה שייך לישראל דוקא מצד השפלות העצמית ומצד מס\"נ שלהם בעצם כנ\"ל והוא אשר אנו אומרים בברכת המצות אשר קדשנו במצותיו קדשנו דוקא וקדושה זאת היא בחי' רוממות קדושת העצמות ממש כמ\"ש כי גאה גאה למעלה מעלה גם מגאות דמל' דה' מלך גאות לבש הרי הוא בבחינת לבוש לבד וגאה גאה מתנשא ומרומם בקדושת עצמותו ממש וזהו שבחינת קדש זה נקרא יקר והוא שנקרא יקר תפארת כו' כתרגום כבודו זיו יקריה כו' והנה מפני גאותו והתנשאותו ביותר רצה שיומשך אליו בחינת יקר קדושה עליונה זו והוא רק חוצפה יתירה מצד הגסות שבו ולכ\"א איש אשר המלך חפץ ביקרו דוקא שהוא יקר קדושה עליונה הנ\"ל יביאו לבוש מלכות וסוס כו' שהן התו\"מ שנקרא אור לבוש קדש העליון ביותר ומגודל גאותו סבר בלבו למי יחפוץ המלך הקדוש לעשות יקר שלו יותר ממני ושגה ברואה כי לישראל דוקא ניתן היקר העליון הזה שהוא קדושת התו\"מ ולא יחפוץ לעשות יקר זה לזולתם כלל וכמו כי אם חפץ בה המלך ונקראה בשם כתר מל' וע\"כ צוה להמן להלביש את מרדכי היהודי היקר הזה דלבוש מל' וסוס כו' כי מרדכי אמן את הדסה כו' ולע\"ל כתיב ואתם תהיו לי ארץ חפץ תקרא חפצי בה דוקא וד\"ל וזהו שעתידים המלאכים לומר לפני הצדיקים קדוש וזה פלא דאיך ידמו צדיקים לעצמות האלקות לומר לפניהם קדוש כו' אך ידוע דקדוש בוי\"ו הוא בחינת המשכה קטנה מקדש העליון הנ\"ל מהעלם קדושת העצמות לגלוי קצת והיינו כמו ענין לבוש מל' אשר לבש בו המלך והסוס אשר רכב עליו כו' שהן לבושי יקר דקדושת העצמות שמלבישים לנשמות הצדיקים בתו\"מ בעה\"ז כי חפץ המלך לעשות להם יקרו דוקא וכמ\"ש אשר קדשנו דוקא וע\"כ המלאכים יאמרו לפניהם קדוש היינו להלבישם מלבוש קדש ויקר העליון דתו\"מ וכמו שהמלך יצוה לשריו לעשות יקר שלו למי שיחפוץ ביקרו שמביאין לבוש מל' כו' וכמ\"ש ונתון הלבוש והסוס על יד איש משרי המלך הפרתמים דוקא וכמו\"כ לע\"ל המלאכים יאמרו לפני הצדיקים קדוש וד\"ל:\n(טו) <b>והנה</b> המן אמר עוד ונתון הלבוש והסוס על יד איש משרי המלך הפרתמים דוקא והלבישו את האיש כו' דפשוטו מובן דד\"ז שייך דוקא אל הכבוד והיקר שיחפוץ המלך לעשות באיש שחפץ ביקרו לבד מה שלבוש מל' והסוס כו' שילבש האיש הוא יקר גדול אין זה שלמותו עדיין עד שילבישנו האיש משרי כו' ויקרא לפניו ככה יעשה לאיש כו' והענין הוא כי האיש משרי המלך הפרתמים משמע שהוא הראש והעליון משרי המלך הפרתמי' ולמעלה הוא השר העליון מיכאל כהנא רבא שהוא שר של חסד העליון בחינת כהנא רבא כו' שהוא המלביש לכל הנשמות בג\"ע בלבושי יקר שנעשה מכל מעשה"],[2201340187,"המצות שעשו בעוה\"ז דוקא כמבואר במדרש וגם בס' הקבלה מוזכר בחי' מיכאל זה הוא ענף החסד עליון דאצילות ולכן נקרא כה\"ר כידוע שכה\"ג ברב חסד דע\"י כו' וע\"כ ע\"י דוקא נמשך האור להלביש לכל הנשמות בבחינת מקיף דלבוש מל' דתו\"מ שנקרא לבוש אשר לבש בו המלך וסוס אשר רכב עליו כו' לכל נשמה ונשמה בפרט אשר המלך חפץ ביקרה מלבישה בלבוש מל' כו' לפי שזה שייך לענין שלמות היקר העליון דלבוש מל' כאשר ניתן הלבוש והסוס כו' ע\"י איש זה מיכאל כה\"ר משרי המלך כו' דוקא וד\"ל. וזהו ונתון הלבוש והסוס על יד איש כו' כי זהו יקר וכבוד הרבה יותר כשלבוש מל' ניתן ע\"י מיכאל כה\"ר יותר מע\"י זולתו כו':\n(טז) <b>ובכל</b> הנ\"ל יובן מ\"ש וקבל היהודים וקבל ל' יחיד דוקא ועוד יש להבין למה בכל מגלת אסתר נק' בשם יהודים דוקא ולא ישראל ויעקב וכה\"ג כמו שמזכירם בשאר הכתובים והנה מבואר למעלה שע\"י ב' דברי' מס\"נ ושפלות עצומה שהיה בהם זכו שיהיה גלוי אור העליון דתו\"מ להתישב בהם וזהו וקבל היהודים כו' והנה ב' קושיות הנ\"ל יתורץ בהקדמה א' והוא במה שמצינו שבשעת מ\"ת היו כללות נש\"י כלולים באחדות גמורה כאיש א' ממש וכמ\"ש ויחן שם ישראל נגד ההר ישראל כמו איש ישראל א' ע\"כ א' ויחן ל' יחיד וכמו\"כ גם עתה אנו אומרים ברכנו אבינו כלנו כאחד באור פניך כלנו כאחד כאיש א' כו' והיינו בדוגמא דמ\"ת שהוא באור פניך דוקא וכמ\"ש כי באור פניך נתת לנו תורת חיים כו' והענין הוא לפי שבחינת אור פניו ית' שבתורה הוא בתכלית היחוד העליון הנקרא אח\"פ בתכלית כידוע דאין גלוי אא\"ס ב\"ה עצמי כ\"א בחכמה שבתורה דוקא שכולל הכל באחדות כו' ולכן לא היה ביכולת כנ\"י לקבל אז בחינת הארת פנים העליונים בי' הדברות כ\"א כאשר היו כלולים תחלה כולם יחד בתכלית האחדות והתכללות כאיש א' ממש ולא כאשר היו בבחינת הפרוד שנק' רבים שהוא הפך היחוד כו' כדי למהוי אחד באחד שיהיה בחי' אח\"פ שורה בהם והוא בחינת אור פנים העליונים כמ\"ש באור פניך ממש נתת לנו כו' וד\"ל:\n<b>אך</b> הנה מהיכן היה בהם בחינת האחדות האמתית הזאת עד שנחשבו כאיש א' ולא בבחינת רבים כלל הענין הוא לפי שכל עיקר סבת הפרוד וההתחלקות בא מסבת שנוי אופני הצרופים באותיות שזהו נקרא רבוי התחלקות האורות בכלים רבים עד\"מ אור השכל א' מתחלק בכמה אופני' בצרופי' בדבורים שונים כי א\"א שיהיה השכל בא באותיות המחשבה רק באופן א' לבד (וכמו המפרשים שעל דבר א' שבגמרא זה מפרש באופן זה וזה מפרש באופן זה כחילוקי הפירושים דרש\"י ותוספו' והכל א' רק שבא באופנים צרופים שונים וזהו כאשר השכל והסברא א' היא רק שמתחלק בצירופים שונים בלשון מדברת אך כאשר אור השכל עצמו בא ממקור השכל בחלוקים שונים כמו זה נוטה אור שכלו לזכות וזה נוטה שכלו לחוב או גם בשכל הנוטה לחסד זה יתפוס באופן כך וזה יתפוס באופן אחר הרי זהו שאור השכל עצמו הוא מתחלק לכמה אופנים שונים מפני שגוף השכל עצמו יוצא מחדושו ממקורו ברבוי התחלקות אופנים כו':\n(יז) <b>וכמו\"כ</b> יובן בכללות נש\"י שהן ס\"ר שאין דעותיהן שוות בהשגת שכל האלקי זה שכלו בהשגת אלקות באופן כך כו' וזה שכלו באלקות באופן אחר נבדל ומחולק מזולתו כמו שא' תוכן רוחות ה' ותוכן לבות כו' כאו\"א לפי דעתו וכמ\"ש נודע בשערים בעלה בכאו\"א לפום מה דמשער בלבו ודעתו כו' (וגם מי שמתאחד עם חברו משרש א' בבחי' החסד וכה\"ג אין א' דומה לחברו כידוע ודוגמא לדבר בד' מחנות דמחנה מיכאל מתחלק לק\"פ א' כו' מפני שגם במקור החכמה שנמשך לכללות נש\"י הרי מתחלק לכמה אופנים שונים כנ\"ל"],[2201340188,"במשל וכל אופן מתחלק לצרופים רבים) אך הנה במ\"ת היו כל הס\"ר נשמות מתאחדים כאיש א' ולכאורה איך אפשר שיתאחדו רבוי ההפכים כאלה כו' הענין הוא דאע\"פ שמצד השכל והשגה באה ברבוי גדול מאד אין זה רק כאשר האור האלקי אינו בא רק בבחי' ההשגה והדעת אבל בבחי' הרצון הפשוט שאיננו מורכב בשכל וטעם כלל וכלל הרי בזה כל הס\"ר נשמות מתיחדים ומתכללים כא' ממש לפי שכאו\"א יוצא מכלי מוחו ודעתו להתפעל בנקודת הרצון שבלב שהוא למעלה מבחי' התחלקות בשכל וצרופי אותיות אלא פשוט בתכלית וא\"כ כל הרצונות שבס\"ר נעשה כמו רצון א' באיש א' כמו עד\"מ העם היוצאים למלחמה שיחדיו יהיו כאיש א' במס\"נ ואין הפרש כלל בין א' לזולתו כו' וכן היו במ\"ת שהיה בהם ההתכללות כאיש א' ממש בנקוד' לרצון הפשוט בהשוואה א' ואז האיר בהם מבחי' אחדות הפשוט בתכלית מבחי' אור פנים העליונים למהוי אחד באחד ממש וד\"ל וזהו באור פניך כי רציתם ברצון הפשוט אך במ\"ת היה מפני שכל העם רואים כו' אבל בזמן אחשורוש היה מצד שהפקירו עצמן להריגה יצאו כלם מכלל הגוף לנקודת הרצון העצמי לבא במס\"נ כנ\"ל שבזה כלם משתוי' והיו כאיש א' ממש ברצון א' כו' ע\"כ זכו לקבל בתוכם מבחי' אח\"פ ממהותו ועצמותו ממש כנ\"ל אע\"פ דלית מחשבה תפיסא ביה כלל היינו בחכמה ודעת שנק' מחשבה אבל בבחי' רעותא דלבא בנקודת הרצון הפשוט הוא נתפס ולכן נא' וקבל ל' יחיד דוקא וד\"ל:\n(יח) <b>ובזה</b> יתורץ גם הקושיא השניה הנ\"ל למה לא נזכרו במג\"א רק בשם יהודים דוקא דהנה פי' יהודים ל' הודאה כמו יהודה אתה יודוך כו' ובנחמי' נא' יהודה בחולם וכמ\"ש לאה הפעם אודה כו' כי הנה ידוע ההפרש בין ברכה להודאה דהברכה הוא בחי' השפע וההמשכה מעילה לעלול בבחי' הגלוי מן ההעלם כמו ברוך ה' מן העולם כו' מעלמא דאתכסיא שהוא בחי' ההעלם לעלמא דאתגליא כו' וכמו והמלך שלמה ברוך ל' נפעל כו' וכן פי' ברוך אתה כו' ברכו את ה' וזהו דרך כלל וגם עד\"ז ממש הוא בדרך פרט בפרטי ההשתלשלות מעילה לעלול שבחי' העלם שבעליון בא לגלוי בתחתון וזהו הנק' ברכה עד שנמצא מחמת זה רבוא רבבות עולמות מצד רבוי השתלשלות מעולם לעולם וכמ\"ש ועלמות אין מספר א\"ת עלמות אלא עולמות כו' אך בחי' ההודאה הוא למעלה הרבה מבחי' הברכה כי ההודאה הוא כלפי העצמות ומקור הראשון שהוא מהות ועצמות א\"ס ב\"ה שהוא מאד נעלה למעלה מבחי' וירידת אור ושפע מן ההעלם לגלוי אדרבה הוא בבחי' העצמות ממש שנק' סדכ\"ס דלית מתב\"כ וא\"א שיבא ויומשך לגלוי כלל ע\"כ שם שייך ענין ההודאה וכמאמר הטוב שמך ולך נאה להודות הרי חלק לשתים דבשמך שהוא בחי' גלוי אור וזיו השפע מן ההעלם לגלוי להיות מקור ברכה לחיי העולמות נק' טוב כמו אמרו צדיק כי טוב כי מטבע הטוב דוקא להטיב ולהשפיע וזהו עיקר ומקור סבת ההשתלשלו' עו\"ע כידוע וזהו הטוב שמך אבל לך למהותו ועצמותו ממש נאה להודות בבחי' ההודאה בלבד להיותו למעלה מבחי' שם הרי א\"א לבא לגלוי אור המושג ע\"כ אין מגיע שם רק ההודאה וכמ\"ש הפעם אודה את ה' בבחי' שלמעלה מן השכל כו' וזהו ענין ש\"ע בלחש וכמ\"ש במ\"א ע\"פ יהודה אתה כו' וד\"ל וזהו שנקראו בשם יהודים דוקא כי מצד בחי' מס\"נ שהיה אז בכולם כא' שזה היה למעלה מן השכל ע\"כ לא נק' אז רק בשם יהודים שהיה מדרגתם אז בבחי' ההודאה שהוא במהות ועצמות אלקות ממש שלמעלה מעלה מכל ההשתלשלות וד\"ל וזהו שנזכרו רק בשם יהודים כמו ליהודים היתה אורה כו' וקבל היהודים מטעם שהיו בבחי' מס\"נ בנקודת הרצון הפשוט וד\"ל:"],[2201340189,"(יט) <b>ובכ\"ז</b> יובן מ\"ש וימי הפורים האלה לא יעברו מתוך היהודים וזכרם כו' כי הנה בתחלת הענין אמר והחדש אשר נהפך להם מיגון לשמחה כו' לעשות אותם ימי משתה ושמחה כו' ומסיים וימי הפורים האלה כו' דמובן שזה שאמר שלא יעברו היינו שיעשו אותם ימי משתה ושמחה גם לע\"ל דוקא (וכמאמר כל המועדים בטלים חוץ ממגלת אסתר כנ\"ל) וזה פלא מדוע גדלה מעלת הפורים כ\"כ שגם לע\"ל לא יעברו מתוך היהודים לעשות אותם ימי משתה ושמחה כו' אך הנה מבואר למעלה במ\"ש בבכי יבואו דמצד עוצם בחי' גלוי אור אלקות ממקום ומדרגה העליונה ביותר שהוא מהותו ועצמותו ממש ע\"כ לא יכיל הכלי וידחק המוח ויצאו דמעות שנקראו בכיה של שמחה כו' וכנ\"ל אבל בזמן אסתר הרי זכו לקבל האור דמהות ועצמות בתוך תוכם ממש שהוא התישבות האור בכלי מטעם מס\"נ ומטעם השפלות העצומה כנ\"ל באריכות ולזאת עשו ימי הפורים ימי משתה ושמחה דוקא הפך הבכיה דלע\"ל כי מה שלע\"ל לא יוכלו לקבל האור כי רב הוא מהכיל כו' וע\"כ בבכי יבאו כנ\"ל אבל בימי אסתר יכלו לקבל האור הגדול ונתישב בתוכם כנ\"ל וע\"כ עשו משתה ושמחה דוקא כי הנה השמחה הוא דוקא בחי' גלוי האור גם מן ההעלם ביותר כמו שנראה בחוש שבעת שמחת האדם יגלה כל מצפוניו ואשר לא יוכל לגלות סוד סתום בדבור בעת השמחה יבא הכל בגלוי גם היותר נעלם וסתום הרי ע\"י השמחה יש גלוי גם לאורות סתומים בכלים וכן ע\"י המשתה דנכנס יין יצא סוד היותר סתום כו' שלמעלה מן ההשגה כו' וע\"כ עשו לימי הפורים ימי משת' ושמחה דוקא להיות שבא להם התישבות האור העליון יותר בכלי המוח והלב שהוא ענין המשתה ושמחה הפך הבכיה דלע\"ל הנ\"ל וד\"ל:\n(כ) <b>וזהו</b> וימי הפורים האלה לא יעברו כו' שיעשו אותם ימי משתה ושמחה גם לע\"ל שיתגלה כבוד ה' כו' מפני שיוכלו לקבל האור הגדול בכלי שלהם כנ\"ל אך א\"כ יש להבין למה אמר בבכי יבאו כו' מפני שלא יוכלו להכיל כו' ואם כבר קבל היהודים והכילו לאור הגדול בזמן אסתר כו' אך הנה מ\"ש בבכי יבאו הוא בקבוץ גליות לימות המשיח שלא יכילו האור הגדול מפני שהיו הולכי' בחשך בזמן הגלות וכמו שלא יכלו לקבל גלוי האור העליון דמ\"ת כמ\"ש וירא העם וינעו ויעמדו מרחוק וזה שעל כל דבור ודבור כו' והנה מה שהיה גלוי האור במ\"ת לא היה רק במ\"ת ולא היה נצחי כי מיד שחטאו בעגל התנצלו את עדים כו' וכ\"ש בחורבן בית ראשון ושני כו' וע\"כ בהחזיר להם האור הזה בימות המשיח לא יכלו להכיל ולקבל וז\"ש בבכי יבאו כו' אך מה שקבלו בזמן אסתר מפני שהיה ממדרגה העליונה ביותר שלמעלה מבחי' החכמה שבתו\"מ מפני מס\"נ ושפלות שמפני זה הטעם נתיישב האור בכלי דוקא ולא נתיישב האור בכלי במ\"ת כמ\"ש על כל דבור כו' הוא עצמו הטעם שמפני זה נשארה בחי' רשימו קיימת ונצחית בכנ\"י דימי הפורים האלה להיות בחי' המשכה זאת דאור העליון בכלי שלהם לעולם בל תמוט לנצח דהכל טעם אחד הוא דמפני שזכו לקבל ממהותו ועצמותו ממש שהוא בחי' נצחיות חי וקיים לעד ע\"כ גם ברושם האור שקבלו היהודים מאורו העצמי לא יעבור לעולם אבל מה שקבלו במ\"ת הגם שהיה מבחי' אור הארת פנים העליונים שבחכמה לא נשאר הרושם נצחי וכמ\"ש בבכי יבאו על העדר האור על העבר והעדר הקבלה להכיל כו' אבל ימי הפורים לא יעברו כו' וזכרם גם זכר רושם שלהם לא יסוף כו' וזהו קימו וקבלו היהודים את אשר החלו לעשות במ\"ת בקיום נצחי שנשאר קיים לעול' וד\"ל:\n(כא) <b>ולהבין</b> ענין ופירוש קיום ואיך יתכן ל' קיום על התור' וכמו שאמרו ושנו בלשון חכמים כל המקים את התורה כו' וכן קים א\"א"],[2201340190,"כל התורה כו' וכן קים זה מ\"ש בזה דלכאורה אין התורה צריכה קיום שכל עיקר ופירוש קיום הוא לקיים ולחזק הדבר בל ימוט לעולם וזהו עיקר הקיו' שקיומו לעד כמו ודבריו חיים וקיימים כו' וכ\"ה לקיים כל דבר שלף כו' וכידוע שכל דברים שצריכים חזוק הוא הנקרא קיום כמו הכל שריר וקים ואז עושה מעש' לקים הדבר כמו שלף כו' (ובאמת ל' המקים את התורה אין הכוונה רק לקים בפועל המעשה לבד כמו קים זה מ\"ש בזה כידוע וא\"כ זה יפלא יותר למה המעש' נקרא קיום לחזק הדבר תורה מעיקרו ושרשו בל ימוט כו' הלא דבריו חיים וקימים בלא\"ה כו') אך הנה ידוע בזהר דרמ\"ח פקודין רמ\"ח אברין דמלכא ושס\"ה ל\"ת הן שס\"ה גידין כו' וידוע מארז\"ל דשמי עם י\"ה הן שס\"ה ל\"ת וזכרי עם ו\"ה הן רמ\"ח מ\"ע וא\"כ שרש הל\"ת למעלה מרמ\"ח מ\"ע שהרי אותיות י\"ה למעלה מאותיות ו\"ה כו' ולכאורה ד\"ז יפלא שהרי הל\"ת אינו רק מניעת המעשה לבד (ובע\"ח א' דרמ\"ח מ\"ע הן בחי' ה\"ח ושס\"ה ל\"ת הן בחי' ה\"ג ולפ\"ז ג\"כ אינו מובן למה ה\"ג בי\"ה כו') ולהבין זה הנה כתיב ועל דמות הכסא דמות כמראה אדם כו' עד\"מ האברים בגוף אדם התחתון שנברא בצלמו בצלם אלקים כו' הנה כל אבר ואבר הרי אור חיותו ממוזג לפי מזג תכונת האבר דוקא כמו אור חיות כח הראי' בכלי העין ואור חיות כח השמיעה בכלי האזן וכה\"ג בכל האברים ואנו רואים שבכל אבר אור חיותו בא בו בבחי' גלוי גמור הנק' בחי' א\"פ ונמצא בחי' האור והחיות ממוזג ומתחלק ברבוי הכלים מכלים שונים והן רמ\"ח אברים שהן רמ\"ח כלים לאורות כו' כמו\"כ יובן בדוגמא באדם דאצי' אע\"פ שאין לו גוף כו' הרי דברה תורה כלשון בנ\"א וכמ\"ש דמות כמראה אדם כו' ובחי' רמ\"ח אברים שלו הן רמ\"ח פקודין כמו חסד דרועא ימינא דקב\"ה ה\"ז ע\"י בחי' מעשה הצדקה והחסד שלמטה נמשך ג\"כ מלמעלה מבחי' עצמות אא\"ס אור החסד דאצי' שיתלבש בכלי כמו עד\"מ יד האד' שמשפיע חסד גשמי וזהו הנק' חסד דרועא ימינא כו' ועד\"ז כל המ\"ע כמו שאמרו מנין שהקב\"ה מניח תפלין ונתעטף בטלית ויושב ושונה כו' הרי ע\"י למוד התורה שיושב ועוסק ג\"ש ביום נמשך מאא\"ס בחכמה וע\"י התפלין שמניח נמשך בחי' ד' מוחין כו' וכללות רמ\"ח מ\"ע העליונים שנק' מצות כו' כמ\"ש במ\"א הן בחי' רמ\"ח אברין דמלכא שבהן בחי' גלוי אור מעצמו' אא\"ס בכל אבר לפי מה שהוא כמו עד\"מ באברי אדם התחתון וכמ\"ש במ\"א ע\"פ אלה המצות אשר יעשה אתם האדם כו' וכמ\"ש ועשיתם אתם כאלו עשאוני כו' וד\"ל וענין שס\"ה ל\"ת הן בחי' שס\"ה גידין שברמ\"ח אברים כו' והענין הוא עד\"מ הגידים שבאברים שנק' גידי הדם והנה ידוע דמ\"ש כי הדם הוא הנפש אין הכוונה שהדם עצמו הוא הנפש המחי' שהרי הוא אנו רואים שהדם מצד עצמו ומהותו אינו מחיה לדבר מה רק הכוונה שהנפש החיונית מלובשת בדם החומרי וכמ\"ש רביעית דם שהנפש תלויה בו כו' והנפש רוחנית היא ומורכבת בחומריות הדם בדרך הלבשה בהעלם גדול וז\"ש כי הדם הוא הנפש שבו הנפש מלובשת בהעלם דוקא וא\"כ לכאורה יפלא מאין בא בחי' גלוי החיות דנפש החיונית באברים אם הוא בהעלם דוקא בדם כנ\"ל אך הנה מבואר במ\"א באריכות בענין חיות האבר מן הדם שאין זה מן מהות ועצם הדם שהרי לא נמצא בגלוי בכל חלקי האבר התפשטות דם (ודם האברים שנגלה מיד כשיחתוך זהו חיצוניות הדם ואין זה עיקר חיות האבר) אלא הענין הוא דבדם מורכב יסוד המים והלחלוחית הנמצא מן הדם הוא בחי' יסוד המים שבו והוא עיקר המתפשט בבחי' חיות לכל האברים בגלוי גמור ואם לא בחי' יסוד המים שבו לא היה הדם מתפשט באברים כלל כי הדם מצד עצמו ומהותו הרי בחי' החיות של הנפש גנוז בו בהעלם בהעדר ההתפשטות"],[2201340191,"דוקא והן הן גידי הדם שהן בחי' מקוריים עומדים בפ\"ע שבהן הדם והוא הנפש בבחי' ההעלם דוקא וכידוע דגידי הדם אינם מתפשטים באברים בהתגלות בחלקי האברים ואדרבה הדם כנוס בהם כמו שכנוס וטמון הכסף בתיבה כי הגידין הן מכסין ומעלימין על הדם שבתוכו לבלתי יתפשט באבר רק הלוכו הוא בתוך האבר דרך מעבר לבד (וגם העורקים שאין בהם דם ונק' מיתרים ועצבים הנק' נערוי\"ן בל\"א גם הם בלתי מתפשטים בגלוי בכל אבר רק בהעלם ושרשם מרוח החיים שבחלל הימני שבלב ושרש גידי הדם מחלל השמאלי שבלב כמ\"ש במ\"א ואמנם מ\"ש כי הדם הוא הנפש היינו בגידי הדם דוקא ולא בעורקים כי בעורקים שם משכן בחי' הרוח שבחלל הימני וזהו בחי' רוח ונפש כו' (ובמ\"א ג\"כ מבואר בענין אכל ולא שתה אכילתו דם שהמאכל כשנהפך לדם אם לא שתה אין בו רק חלק הדם בלא יסוד המים כלל ע\"כ אינו מתפשט בגלוי החיות רק בהעלם וצמצום העדר ההתפשטות וזהו אכילתו דם שהאוכל הדם לא יחיה כי נפש הוא אוכל כמ\"ש אך בשר בנפשו דמו כו' וד\"ל והענין הוא כי ב' חללים דלב מקבלין מב' מוחין חו\"ב חסדים דאבא וגבורות דאמא וזהו אדם אדם כו' וא\"כ המים שבדם מבחי' החסדים דאבא וז\"ש קול דודי דופ\"ק קפ\"ד אחוריים דאבא והוא הדפק שביד שבו גלוי החיות והדם עצמו גבורות דאמא וא' דאדם הוא בחי' רוח ודם הוא הנפש בהעלם וזה י\"ה דהיינו חו\"ב שרש שס\"ה ל\"ת ששרשם בגידי הדם כנ\"ל) ואמנם הגם שהדם עצמו בלתי מתפשט באברים אבל שולח אור ושפע מבחי' יסוד המים שבו להתפשט בכל אבר ואבר אם בצמצום או בהרחבה לכל אבר כפי מזגו בבחי' גלוי גמור כנ\"ל אבל מצד עצם הדם הרי בטבעו ומהותו הוא בלתי מתפשט כלל ואינו בא בגדר המשכה והתפשטות לאברים כלל אדרבה הוא בבחי' העדר הגלוי וההתפשטות מפני שהנפש בו בבחי' ההעלם דוקא העדר הגלוי כנ\"ל וד\"ל:\n(כב) <b>וע\"ד</b> כ\"ז יובן למעלה בבחי' אדם העליון דאצי' שכל האורות דאצי' שנאצלו מן המאציל ובאו בבחי' גלוי גמור בכלים מכלים שונים שהן רמ\"ח פקודין כמו חכמה מוחא חסד דרועא וכה\"ג הרי הן בבחי' אור החסדים המתפשטים מעצמות המאציל שזהו כמשל בחי' יסוד המים שבדם כו' אבל שס\"ה ל\"ת הן כמו בחי' גידי הדם באדם העליון שבהם ישכון בחי' ההסתר וההעלם של אור המאציל כמו שהוא בבחי' עצמותו שאינו בא בבחי' התפשטות שפע בגלוי למטה עדיין כנ\"ל בענין כי הדם הוא הנפש כו' וד\"ל (ומבחי' יסוד המים שבדם שבגידין הוא המתפשט ברמ\"ח אברים דמלכא כנ\"ל במשל כו') ולפ\"ז הרי מובן דשרש השס\"ה ל\"ת גבוהים מרמ\"ח מ\"ע אע\"פ שהן רק בבחי' מניעת המעשה לבד אבל שרשן הוא בבחי' הסתר והעלם אור המאציל כמו שהוא בעצמו סתום ונעלם ומונע א\"ע מלהתמשך ולהתפשט לרמ\"ח אברי' דמלכא (והיינו ע\"י מניעת המעשה בל\"ת שהוא העדר ההתפשטות ג\"כ כו') שזהו בבחי' העצמות שלמעלה מבחי' ההתפשטות עדיין וזהו הטעם שהל\"ת הן בי\"ה שלמעלה מרמ\"ח מ\"ע שהן בו\"ה (כי ו\"ה הוא בחי' גופא דמלכא וי\"ה הוא בחי' חו\"ב שמתפשטים בב' חללי הלב ומשם לכל האברי' כנ\"ל בפי' אדם א' דם כו') והנה כתיב הנסתרות לה' אלקינו והנגלות לנו כו' פי' ה' אלקינו הוא בחי' י\"ה חו\"ב שנק' נסתרות ונק' עלמין סתימין דלא אתגליין והנגלות הן בחי' ו\"ה שבא בבחי' גלוי אור בכלי כו' ונק' עלמין דאתגליין ונמצא ששס\"ה ל\"ת נק' עלמין סתימין ורמ\"ח מ\"ע נק' עלמין דאתגליין כי כל מצוה היא בחי' גלוי רצון העליון למטה בכלים מכלים שונים כמשל האברי' כנ\"ל אבל שרש מניע' והעדר המעשה דל\"ת הוא בבחי' העלם העצמות כנ\"ל אך עכ\"ז נק'"],[2201340192,"עלמין כמו עלמין דאתגליין רק שנק' עלמין סתימין כו' כי הגם שהוא בבחי' העלם אור העצמות אין זה בחי' העצמות ממש אלא שהוא רק האר' בעלמא מבחי' העצמות והוא מאיר בהעלם והסתר ג\"כ אבל גם הוא נק' עולם ואין לו ערוך לגבי העצמות ממש שהרי גם הוא בבחי' אור וכלי כמשל גידי הדם שהן בחי' כלים להשראת אור חיות הנפש הנעל' בהם כו' והרי גם אור וחיות הנפש הנעלם בהן אין זה מהות ועצמות הנפש ממש כמו שהיא טרם בואה לגוף אלא רק הארה בעלמא כו' אבל אור זה נק' אור נעלם כו' ולא שנק' העלם העצמות ממש שהרי בחי' העצמות ממש נק' סתימו דכל סתימין כו' דהיינו שבחי' ההעלם והגלוי שוין לפניו כו' וכמ\"ש כחשיכה כאורה חשך העלם ואור גלוי ואמר גם חשך לא יחשיך כלומר לא יעלים משום דקמי עצמותו נגלו כל תעלומו' להיותו למעלה מבחי' העלם וגלוי דכל בחי' העלם לא יתכן רק לגבי המקבל שלא נודע ונגלה אליו והיינו בבחי' עילה ועלול כו' משא\"כ בעה\"ע עצמו דאפי' אור צח כו' ולית מחשבה תפיסא ביה כלל הוא למעלה בבחי' עלמין אפילו מעלמין סתימין כו' וזהו כי ביה ה' צור עולמים פי' י\"ה בחי' עלמין סתימין ו\"ה הוא בחי' עלמין דאתגליין וזהו צור עולמים עלמא דאתכסיא ועלמא דאתגליא כמ\"ש ברוך ה' מן העולם ועד העולם כו' וידוע דעלמין סתימין ועלמין דאתגליין מאחר שנק' עלמין הרי נאצלו ונבראו מאין ליש עכ\"פ ע\"כ בין באצי' בין בבי\"ע נק' בשם עלמין אך אין להם ערוך כלל לגבי בחי' עצמות המאציל שאינו בגדר ובחי' עלמין לא בבחי' העלם ולא בבחי' גלוי אלא בב' אותיות די\"ה צור עולמים כו' מאין ליש כו' וד\"ל:\n(כג) <b>וזהו</b> ג\"כ מ\"ש ועל דמות הכסא דמות כמראה אדם ולא אדם ממש כי עצמות אא\"ס ב\"ה לאו מכל אנון מדות כלל וכמ\"ש כי לא אדם הוא כו' רק שנמשך מן העצמות ע\"י צמצומים רבים להיות בבחי' אדם א' דם בשס\"ה ל\"ת שס\"ה גידין ורמ\"ח מ\"ע רמ\"ח אברים כו' ונק' אדם אדמה לעליון שלמותא דכולא כו' (ולפי מ\"ש בע\"ח דרמ\"ח מ\"ע הן בחי' ה\"ח ושס\"ה ל\"ת הן בחי' ה\"ג ג\"כ הוא בבחי' צמצום והתפשטות העלם וגלוי וכ\"ז אין ערוך כלל לגבי עצמות המאציל שלמעלה מבחי' חו\"ג לגמרי דהגם שידוע דאא\"ס למעלה עד אין קץ ולמטה עד אין תכלית משום שהן בחי' חו\"ג שבעצמות כמ\"ש במ\"א אבל אין זה ערוך כלל לגבי העצמות ממש שלמעלה לגמרי מבחי' מעלה ומטה כו' שלא יתכן בו בחי' הירידה ועליה כמשל העגול כידוע וראיה לכ\"ז שהרי אמר במל\"ת ומ\"ע זה שמי לעלם בבחי' ההעלם דל\"ת כנ\"ל וזה זכרי לדר דר בבחי' הגלוי דרמ\"ח מ\"ע וכ\"ז אינו רק שמי וזכרי לבד ולא בחי' עצמותו כלל דלכן נק' בשם עלמין כנ\"ל וד\"ל:\n(כד) <b>והנה</b> ע\"י מס\"נ או ע\"י תשובה עלאה מעומקא דלבא שהוא למסור נפשו בעצמות אא\"ס ב\"ה שלמעלה מבחי' העלם וגלוי דעלמין סתימין ועלמין דאתגליין כנ\"ל בזאת תתעל' הנפש ותדבק למעלה מעלה בבחי' עצמות אא\"ס כמ\"ש אליך ה' נפשי אשא אליך דוקא וכן צמאה לך נפשי כו' וזה היה בימי מרדכי ואסתר שהיה בכנ\"י ומס\"נ ותשובה עלאה מעומקא דלבא ע\"י הצומות וזעקתם כו' ונתעלה שרש נשמתם לבחי' עצמות אא\"ס שלמעלה מבחי' עלמין כנ\"ל אפי' מבחי' עלמין סתימין כו' שהוא למעלה מבחי' אדם שכולל רמ\"ח מ\"ע ושס\"ה ל\"ת כנ\"ל וזהו קימו וקבלו כו' שהיה ביכולתם אז לקיים את התורה כנ\"ל בפי' קיום שהוא לחזק את הדבר מעיקרו ושרשו לפי שהגיעו אז במס\"נ שלהם לבחי' עצמות אא\"ס שהוא מקור ושרש התורה והמצות והיינו פי' מקיים את התורה שהוא מהווה ומקימה בקיום חזק משרש מקור חוצבה שמשם נתהווה"],[2201340193,"התור' בבחי' עלמין סתימין ועלמין דאתגליין כי גם אורייתא סתים וגלייא כמ\"ש הנסתרות לה' אלקינו והנגלות לנו ולבנינו כו' כידוע דשרש התורה מח\"ע נפקת והמצות הן בחי' תרי\"ג ארחין כו' שזהו בחי' כתר תר\"ך עמודי אור שהן בחי' גלוי רצון העליון ורצונו וחכמתו זה שבתו\"מ הרי נמשכו מבחי' העצמות ממש שלמעלה מעלה מבחי' רצון וחכמה כו' וע\"י מס\"נ המשיכו מחדש ממקור התו\"מ להיות קיום והתהוות חדשה לתו\"מ מעצמות בעל הרצון לפי שמס\"נ הוא מסירת וביטול הרצון מכל וכל כו' שזה מגיע למעלה ג\"כ בעצמות בעל הרצון כידוע. וז\"ש קימו וקבלו מכאן מודעא רבא לאורייתא פי' כמו מקיים את התורה שהוא מהווה אותה ממקור חוצבה שהוא בחי' עצמות אא\"ס ב\"ה ע\"כ מכאן מודעא רבא לאורייתא להיות שזה בבחי' מקור התו\"מ וד\"ל:\n(כה) <b>ועד\"ז</b> יתפרש מ\"ש קים זה מ\"ש בזה דאע\"פ שלכאורה אין התורה צריך קיום וחזוק כי דבריו חיים וקיימים משעת מ\"ת אך עכ\"ז מה שהתורה כבר ישנה במציאות בקיום דבר היינו רק כמו שהיא בבחי' עלמין סתימין ועלמין דאתגליין בבחי' השתלשלות אבל המקיים אותה הוא המהווה אותה משרש מקור חוצבה בתחלת המשכתה מן העצמות וזהו קיים זה מ\"ש בזה דאע\"פ שהתורה כבר כתובה זה קיים למה שכתוב בה ממקור חוצב הכתיבה כו' וכן קיים א\"א כל התורה וכה\"ג וד\"ל. (ומה שעיקר פי' קיום הוא חוזק הדבר בל ימוט לעולם וזהו כמו לקים כל דבר שלף כו' בבחי' המעשה דוקא כנ\"ל היינו ג\"כ ע\"י קיום המעשה דתו\"מ בפ\"מ כפשוטו דקיים זה מ\"ש בזה משום דכ\"ז שלא באה התורה לידי קיום המעשה בפ\"מ אין לה קיום בעצמותם עדיין ממקור חוצבה כו' וזהו משום דנעוץ תחלתן בסופן בסוף מעשה דוקא וכמשל דבר המלך שלא נק' קיום אלא כשהביא דברו לידי מעשה בפ\"מ שאז דוקא נתקימו דבריו כו' ובזה מתורץ קושיא דלעיל דאע\"ג דדבריו חיים וקימים עיקר הקיום כשבאין דבריו לידי קיום המעשה דוקא והוא ג\"כ עיקר ענין חזוק הדבר בל ימוט לעולם כו' מטעם זה דנעוץ תחלתן בסופן וסופן בתחלתן כו' וכמ\"ש במ\"א בפי' להקים את דברי התורה. הקימותי את דבר ה' וכה\"ג כו' וד\"ל):\n(כו) <b>ובכ\"ז</b> יובן המאמר דאכלו רעים לעילא שתו ושכרו דודים לתתא כו' דהנה ידוע בפי' רעיתי פרנסתי שישראל מפרנסין לאביהם שבשמים כו' והוא כמשל אדם שאוכל מאכל שנהפך לדם ונתוסף אור וחיות בדמים שבלב ומתפשט מגידי הדם תוס' גלוי חיות לאברים והרי יש כאן ב' דברים הא' מה שהדם הוא הנפש בעצם מהותה כמו שהיא בהשראה בהעלם מתחברת יותר בדם שכל שהדם מרובה הנפש מתלבשת שם ברבוי חיות יותר וממילא נמשך מיסוד המים שבדם תוס' חיות לאברים בבחי' גלוי יותר וכנ\"ל בענין גידי הדם כו' וכן יובן בבחי' רמ\"ח מ\"ע ושס\"ה ל\"ת כמו שהן למעלה באדם העליון שע\"י המצות נתוסף אורות בכלים למעלה וכדוגמא שא' בקרבנות לחמי לאשי כמו הלחם שלבב אנוש יסעד ויתחזק אור וחיות הנפש בדם ובאברים כו' וכ\"ה כל התו\"מ כמו שהן למעלה הם בבחי' אכילה כמ\"ש באתי לגני כו' אכלתי יערי כו' וזהו שישראל מפרנסין לאביהם כו' ע\"י תו\"מ שלהם שמעוררים למעלה ג\"כ בחי' פרנסה ומזון העליון לאדם העליון כו' וכמ\"ש במ\"א באריכות וד\"ל. וזהו אכלו ריעים לעילא פי' לעילא בעלמין סתימין ועלמין דאתגלין שכלולים באדם העליון הרי יש כבר בחי' מציאות השתלשלות עלמין ששם יתכן בחי' האכילה שע\"י תו\"מ להוסיף אור בעלמין הללו וכמו עד\"מ שע\"י המאכל יומשך תוס' אור גם בהעלם הנפש שבגידי הדם כו' ולמעלה נק' זה עלמין סתימין שהוא בבחי' י\"ה שנק' הנסתרות לה' אלהינו כנ\"ל וממילא נמשך תוס'"],[2201340194,"אור בו\"ה שהן רמ\"ח אברין דמלכ' כנ\"ל וזהו אכלו ריעים לעילא ריעים הללו הן חו\"ב דאצי' שנק' תרין ריעין דלא מתפרשין והן שרשי המוחין ומדות שנק' ו\"ה הנגלות כו' וכידוע שמן המאכל שנהפך לדם עולה ללב ומן הלב אל המוח ושם משכן הנשמה וחוזר ונמשך מדם לרוח ונפש שבחללי הלב כו' וכמ\"ש במ\"א בענין מוחא ולבא וכבדא בענין הקרבנות כו' וד\"ל ולפי שמן ההעלם בא לידי גלוי הרי ההעלם עיקר והגלוי ממילא בא כי יש בכלל מאתים כו' לכן לא הזכיר בחי' אכילה זו דתו\"מ רק בריעים שהן חו\"ב י\"ה וממילא נכלל בזה בחי' דודים שהן ו\"ה כו' וז\"ש אכלו ריעים לעיל' כו' וד\"ל:\n(כז) <b>אך</b> כ\"ז הוא כמו שהתו\"מ באין בהשתלשלות דעלמין כו' שהן י\"ה עלמין סתימין כו' והוא מוח ולב העלם וגלוי שהוא עיקר בחי' אדם כנ\"ל אבל ענין המקיים את התורה שהוא לקיים אותה בהתהוות חדשה ממקור חוצבה בעצמות אא\"ס ב\"ה שלמעלה מבחי' עלמין כנ\"ל הנה זהו ע\"י בחי' שתו ושכרו דודים לתתא דוקא דהנה פי' דודים הוא בחי' זו\"נ עלמין דאתגליין בחי' ו\"ה שהוא בחי' גלוי האור בכלי דוקא אך הנה בחי' השתיה דיין וכה\"ג יש בה יתרון מעלה מן האכילה שהאכילה אינה רק בבחי' החכמה והדעת שמחזק המוחין שבראש כנ\"ל במאכל שנהפך לדם כו' אבל השתיה דיין משכר ומגיע בבחי' שלמעלה מן הדעת דוקא כידוע בענין חייב אינש לבסומי בפוריא עד דלא ידע כו' למעלה מן הדעת כו' והטעם הוא לפי שפורים ויוה\"כ שרש א' להם במס\"נ ותשובה עלאה שלמעלה מן הדעת רק בטול רצון מכל וכל למעלה מן הטעם והדעת כו' וע\"כ יוה\"כ אין בו אכילה כו' מפני שהוא בבחי' שלמעלה מבחי' אכילה דתו\"מ דמה שהתו\"מ הן בבחי' אכילה כנ\"ל בפי' מפרנסין לאביהם כו' היינו בזמן הגלות דוקא שנתלבש וירד בבחי' האכילה כו' אבל יוה\"כ שהוא כמו העוה\"ב אין בו אכילה כו' וכמ\"ש בזהר באתריה לאו אורחיה למיכל כו' וכ\"ה בחי' ומדרגה דפורים לפי שהיה בהם מס\"נ שלמעלה מן הטעם והדעת שמגיע בעצמות ממש שמשם נמשך מקור התו\"מ שבבחי' החכמה ודעת כו' ע\"כ חייב לבסומי עד דלא ידע כו' שזהו למעלה מבחי' האכילה שהיא רק בבחי' החכמה והדעת כנ\"ל. וזהו שתו ושכרו דודים לתתא. פי' שתו ושכרו בחי' השתיה דיין המשכר דוקא שלמעלה מן הדעת כו' בזה מעוררים למעלה בבחי' ומדרגה שלמעלה מן הדעת דהיינו למעלה מבחי' הדעת וחכמה דתו\"מ כשבאין בבחי' השתלשלות עלמין שכבר נמשך כו' אלא במקור חוצב התו\"מ בבחי' העצמות שלמעלה מן החכמה שמשם נתהווה התו\"מ בהתהוות חדשה ממקורם הראשון וכנ\"ל בענין המקיים את התורה כו' ונמצא דשתו ושכרו דודים לתתא הוא למעלה מבחי' אכלו ריעים לעילא משום דבחי' לתתא שהוא למטה מן הדעת שרשו בלמעלה מן הדעת כו' והיינו מטעם הנ\"ל שנעוץ תחלתן בסופן דוקא ע\"כ בשתיה דדודים לתתא דוקא שם מתקיים התורה במקור חוצבה יותר מבבחי' י\"ה שנק' ריעים כו' וד\"ל:\n(כח) <b>וזהו</b> קימו וקבלו היהודים כו' וארז\"ל קימו מה שקבלו כבר במ\"ת וזהו את אשר החלו לעשות בזמן מ\"ת כו' דהנה לכאורה יש להבין במארז\"ל דבמ\"ת כפה עליהם ההר כגיגית דמשמע שקבלו באונס והרי יש סתירה לזה ממקרא מפורש שאמרו למשה כל אשר דיבר ה' נעשה ונשמע כו'. ועל כל דבור ודבור פרחה נשמתם כו' משמע שקבלו באהבה וברצון גמור כידוע. אך הענין הוא שבזמן מ\"ת היה בחי' התגלות אא\"ס על כנ\"י בבחי' מקיף מלמעלה למטה בבחי' חבוק לעורר בנשמתם בחי' הרצון במס\"נ מלמטה למעלה והוא אשר השיבו למשה כל אשר דבר ה' נעשה ונשמע. שזה לא היה מכח התעוררות עצמם אלא"],[2201340195,"מאתדל\"ע שבעצמות שנמשך עליהם לעשות אתדל\"ת זאת והיינו שעל כל דבור ודבור פרחה נשמתן על כל דבור דוקא מפני הארת דבור העליון שהאיר עליהם בבחי' מקיף וזהו שכפה עליהם ההר כגיגית בבחי' מקיף עליהם (וכמשי\"ת בסמוך באריכות) וזהו אשר החלו לעשות במ\"ת ע\"י בחי' מקיף דכפה עליהם ההר כגיגית עתה קימו מה שקבלו כבר כו' כי בפורים היה להם מס\"נ מצד עצמם דוקא שלא ע\"י אתדל\"ע לעוררם ולזאת קימו את התורה ממקור חוצבה בהתחדשות מעצמות המאציל שלמעלה מהשתלשלות דעלמין שהתורה שקבלו כבר במ\"ת שבאה בהשתלשלות דעלמין כמ\"ש וירד ה' על הר סיני וידבר. בחכמה ודבור כו' העלם וגלוי כו' וזאת התורה עצמה שכבר קבלו בסיני שבאה להם בבחי' השתלשלות קיימו אותה בפורים בהתהוות חדשה ממקור התורה כי במ\"ת נשתלשלה להם המשכת אור דתורה בבחי' עלמין משום דמס\"נ שלהם קבלו מלמעל' למטה כו' אבל בפורים קבלו ברצון עצמם במס\"נ מלמטה למעלה והגם שלכאורה אין הפרש בין זה לזה דזה וזה מס\"נ הוא עכ\"פ ומה הפרש אם סבתו בא מלמעלה או למטה כו' אך הענין הוא משום דנעוץ תחלתן בסופן וסופן בתחלתן כידוע וכנ\"ל בפי' המקיים את התורה דבסוף מעשה דוקא שם נעוץ התחלת המחשבה ורצון הפשוט שצמצם א\"ע בתחלה לרצון וחכמה דתורה כו' שנק' מקור התורה כו' וע\"כ במס\"נ של ישראל מצד עצמם דוקא שם מאיר בחי' מקור התורה שבעצמות וזהו קימו מה שקבלו כבר בסיני אבל בסיני לא נתקיימה התורה עדיין ממקורה מצד שלא היה מס\"נ שלהם מצד עצמם רק מלמעלה שאין בזה מהארת מקור התורה כמו שהיא קודם שבאה בהשתלשלות מאין ליש בבחי' עלמין כו' וד\"ל. וזהו שאמרו ע\"פ קימו וקבלו כו' מכאן מודעא רבא לאורייתא פי' לאורייתא שכבר קבלו בסיני מכאן נמצא מודעא רבא אליה במה שקימו מה שקבלו בסיני לפי שבמ\"ת כפה עליהם כו' ולא היה עדיין מודעא רבא לאוריית' אבל בפורים ע\"י מס\"נ שלהם נתהווה התורה ממקורה שהוא הנק' מודעא רבא לאורייתא שכבר באה בהשתלשלות כנ\"ל וד\"ל (ולא שבמ\"ת היה אונס וכפיה ע\"י שכפה עליהם כו' שהרי אמרו נעשה ועל כל דבור ודבור כו' אלא שמס\"נ שלהם אז כמו אונס נחשב מצד שכפה עליהם בבחי' מקיף עד שהרצון שלהם היה בהכרח כמו ע\"ד שא' ובעבור תהיה יראתו על פניכם לבלתי תחטאו כו' כאדם שמחבק את חברו לבלתי יוכל להפרד וכמשי\"ת) (וזהו שמתחלה אמר וקבל היהודים ל' יחיד את אשר החלו לעשות במ\"ת ולא אמר קיימו עדיין עד כי ספר עיקר ענין פורים במ\"ש כי המן כו' והפיל פור כו' ובבואה לפני המלך במס\"נ של עצמם כנ\"ל אז אמר עם הספר ישוב מחשבתו כו' ע\"כ קראו לימים האלה פורים על שם הפור כו' ואז אמר קימו וקבלו קימו מה שקבלו כבר בסיני והקרי קבלו ל' רבים לפי שקבלו עליהם ועל זרעם כו' משא\"כ וקבל ל' יחיד שזה כמו במ\"ת שלא קבלו רק אותו הדור לעצמם מפני שכפה עליהם כו' ומטעם כל הנ\"ל וכמ\"ש במ\"א באריכות וד\"ל:\n(כט) <b>וזהו</b> ליהודים היתה אורה ושמחה כו' ולכאורה יש להבין ל' היתה אורה ל' נקבה ולא אמר היה אור ל' זכר אך הענין הוא דפי' אורה הוא ל' מפעיל כמו מאכיל משכיל כו' כך אורה מפיק ה\"א פועל יוצא להפעיל את האור שהוא ענין מאיר שממנו נמצא מציאות האור וזהו היתה אורה להאיר לכל כמו ועינינו מאירות וכמו אספקלריא המאירה כו'. ובאור הדברים הנה יש להבין תחלה בתוס' באור בענין הנ\"ל במארז\"ל במ\"ת שכפה עליהם ההר כגיגית כו' ויש להקדים לזה ענין א' המבואר במ\"א שיש ב' מדרגות בבחי' אתדל\"ע הא' אתדל\"ע הבאה מסבת אתדל\"ת דוקא והב' אתדל\"ע שבאה מצד עצמה שלא ע\"י אתדל\"ת כלל ולכאורה יש להבין מהו הצורך כלל בבחי' אתדל\"ת לעורר אתדל\"ע מאחר שיוכל להיות אתדל\"ע"],[2201340196,"מצד עצמו שבודאי לכאו' אתדל\"ע שמצד עצמה הרבה יותר נעלה במדרגה מאתדל\"ע שאינה באה רק מסבת אתדל\"ת בלבד וכידוע דבחי' אתדל\"ת שמעורר אתדל\"ע הוא הנק' בחי' העלאת מ\"ן שמעורר המשכת מ\"ד כו' ולפי ערך ההעלאה כן ערך ההמשכה כי רוח אייתי רוח ואמשיך רוח כו' רק כפי ערך אופן ההעלאה דוקא ועד\"מ התלמיד שמשיבין לו רק כפי שאלתו בלבד וכמ\"ש במ\"א בענין יעננו ביום קראינו כו' וידוע דהעלאת מ\"ן מהעולמות אין לו ערך לגבי בחי' אתדל\"ע שמצד עצמו שהוא בבחי' א\"ס ממש כו' וד\"ל:\n(ל) <b>אך</b> הנה באמת נהפוך הוא שאתדל\"ע הבאה מצד אתדל\"ת גבוה ונעלה במדרגה הרבה מאתדל\"ע שמצד עצמה שלא ע\"י אתדל\"ת דהיינו שמגיע בבחי' העצמות דא\"ס יותר מכפי המדה הראשונה שהיה חפץ חסד מעצמו כו' והטעם הוא דהגם שהעלאת מ\"ן של העולמות הוא בתכלית קטנות הערך לגבי העצמות כנ\"ל אבל מפני שנעוץ תחלתן בסופן וסופן בתחלתן עי\"ז יתעורר בעצמות אא\"ס בבחי' ומדרג' עליונה בעצמותו יותר משהיה מתעורר מצד עצמותו שלא ע\"י העלאת מ\"ן כו' וכמ\"ש במ\"א בענין אשת חיל עטרת בעלה וכן נקבה תסובב גבר. שבינה יתירה ניתן באשה כו' שבחי' העלאת מ\"ן שלה מעורר בבחי' עצמות אא\"ס במדרגה היותר נעלה שלא היה כן מצד התעוררות רצון וחפץ חסד עצמותו כ\"כ כו' משום דסוף מעשה דוקא הוא אשר עלה בתחלת המחשבה שמחמתו נתעורר להיות לו רצון וחפץ בהשתלשלות כו' וכמ\"ש בענין במי נמלך בנשמתן של צדיקים פי' במי נמלך בתחלת המחשבה אם להיות רצון וחפץ חסד זה להשתלשלות העולמות כו' נמלך בנשמתן של צדיקי' שעלו בתחלת המחשבה כמארז\"ל ישראל עלו במחשבה פי' עלה במחשבה מה שעתידין נשמות ישראל לקיים תו\"מ כו' ונתאוה הקב\"ה להיות לו דירה בתחתונים כו' ונתאוה זה היינו בחי' העונג הנעלם בעצמותו להיות לו דירה בתחתונים דוקא וע\"כ סוף מעשה דתו\"מ בעוה\"ז הוא מגיע בתחלת המחשבה להיות לו רצון וחפץ חסד בהשתלשלות העולמות וכמ\"ש אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי כו' וזהו שאתדל\"ע שבאה מצד אתדל\"ת דוקא מעורר בעצמותו אותו עונג הנעלם שבעצמותו להיות לו דירה כו' שהוא למעלה מעלה מבחי' אתדל\"ע שמצד עצמו כי חפץ חסד הוא אדרבה אותו חפץ חסד מקבל מזה העונג הנעלם שעלה במחשבה תחלה (וזהו מ\"ש בע\"ח דבתחלת ההשתלשלות היה חפץ חסד מעצמו ואח\"כ תלוי במעשה התחתונים לעורר אותו חפץ חסד כי שרש מעשה התחתונים למעלה מאתדל\"ע זו שמצד עצמו כו' מטעם הנ\"ל וד\"ל) ולפ\"ז אתדל\"ע שמצד אתדל\"ת גבוה הרבה מאתדל\"ע שמצד עצמו מטעם זה דנעוץ תחלתן בסופן וסופן בתחלתן כנ\"ל וז\"ש אשת חיל עטרת בעלה כו' וד\"ל. וראיה ברורה לזה הוא מה שמצינו בזהר וכתבי האר\"י ז\"ל בהשתלשלות העולמות מאא\"ס עצמו שאין זה מאא\"ס עצמו כ\"א ע\"י בחי' צמצום גדול הנק' מק\"פ וחלל ריקן כו' ואח\"כ צמצם א\"ע עוד להיות ההמשכה רק בבחי' קו וגם קו הזה הוא אחר הצמצום דבחי' יו\"ד כו' וכידוע בע\"ח בפרטי רבויי הצמצומים וההעלמות בצמצם והעלם אחר העלם עד שנעשה בחי' מקור לאבי\"ע שאז נמשך האור רק לפי ערך המקבלים לבד שהן ד' עולמות דאבי\"ע לפי שאין ערוך כלל לנאצלים ונבראים כו' לגבי עצמות המאציל וא\"כ הרי ע\"י בחי' אתדל\"ע שמצד עצמותו כי חפץ חסד הוא כו' אין השפע באה רק ע\"י רבוי הלבשות והעלמות וצמצומים רבים דוקא עד שיהא רק לפי ערך הגבלת המקבלים לבד כו' משא\"כ מה שע\"י אתדל\"ת בהעלאת מ\"ן נעשה אתדל\"ע הרי ע\"י אתדל\"ע זו נמשך למטה בעולמות מבחי' אור העצמות ממש שלא ע\"י הלבשות והעלמות וצמצומים כלל כי האור בא מלמעלה מעלה מבחי' סדר ההשתלשלות"],[2201340197,"דאבי\"ע ממקורם כו' וכמו כל הנסים והנפלאות דכתיב עושה נפלאות לבדו דוקא דהיינו כמו שהוא בבחי' עצמותו ממש שהוא לבדו ואין עוד כו' שלא כפי סדר ההשפעה הבאה בבחי' השתלשלות עו\"ע מתגלה למטה ע\"כ נעשה נס נפלא למעלה מגדר ההשתלשלות כידוע וכן היה הנס הנפלא בימי מרדכי ואסתר שהוא למעלה מעלה מן ההשתלשלות דאבי\"ע שלא לפי ערך המקבלים כלל כו' לפי שאתדל\"ע שהיה אז היה ע\"י אתדל\"ת שלהם במס\"נ מצד עצמות דוקא כנ\"ל ואתדל\"ע שמצד אתדל\"ת שרשה מגיע בבחי' העצמות ביותר מבחי' אתדל\"ע שהיא בסדר ההשתלשלות דאבי\"ע מטעם שנעוץ תחלתן בסופן דוקא כנ\"ל וד\"ל:\n(לא) <b>ובכ\"ז</b> מובן בתוס' באור ענין כפה עליהם ההר כגיגית כו' דהנה בזמן מ\"ת היה בחי' אתדל\"ע שמצד עצמו כי חפץ ורצה בישראל לזכותם מצד אהבתו אליהם כאב את בן ירצה כו' כמ\"ש כי רוצה ה' בעמו כו' וז\"ש ואשא אתכם על כנפי נשרים כו' כנשר יעיר קנו על גוזליו כו' וכן ישאהו על אברתו כו' וזהו שכפה עליהם ההר כגיגית פי' הר כמו שאמרו ז\"ל לא כאברהם שקראו הר כו' דהנה ידוע דמדת האהבה נמשל להר כמו ההר הגשמי הנה הוא בעצם בחי' דומם כשאר דומם שבשטח הארץ רק שמקומו של הר נגבה בגובה יותר משאר שטח הארץ מפני שהוא בחי' צומח שבדומם כמ\"ש במ\"א וכמו\"כ האהבה הוא בחי' עליית והגבהת אור וחיות הלב בתשוקה בעלוי אחר עלוי ונק' זה קרוב הנפש שמתקרבת ועולה למעלה כמו ההר שעולה בגובהו עד למעלה כאילן גבוה בקומה כו' ויש הרים קטנים ויש הרים הגדולים ביותר כמו הרי אררט כו' וזהו לא כאברהם שקראו הר ע\"ש בחי' מדתו מדת האהבה והקירוב לה' כמ\"ש אברהם אוהבי כו' ע\"כ אמר בהר ה' יראה כו' וכה\"ג היה בשעת מ\"ת מלמעלה למטה שכפה עליהם ההר כגיגית פי' שנתעורר ונמשך בחי' אהבה רבה דעצמות אא\"ס מלמעלה למטה מצד עצמו שלא ע\"י אתדל\"ת כלל וזהו שא' כפה עליהם בבחי' כפיה כאלו מס\"נ שלהם הכרחית היא כי לא היה בהם התעוררות זאת דנעשה ונשמע מצד עצמם כלל רק מצד הארת אור עליון דאה\"ר שבעצמות אא\"ס שירד למטה וחפף עליהם בבחי' מקיף שלא לפי ערך כלי המקבלים כלל מאחר שלא היה בהם התעוררות עצמותם כו' ומה שפרח' נשמתן כו' היינו על כל דבור ודבור דוקא דהיינו שהיה מאיר אור מקיף שמכל דבור די' הדברות על כל נפש מישראל ונעשה בחי' מקיף על נפשו כמו גיגית ממש להקיפו מכל צד עד שמתעורר ממילא בנפשו רצון ותשוקה גדולה לה' אחד כו' עד שפרחה נשמתן בבחי' מס\"נ ממש כו' ולפי שלא היה זה המס\"נ שלהם כלל אלא רק מלמעלה נמשך להם ע\"כ נאמר וקבל היהודים את אשר החלו לעשות שבזמן מ\"ת לא היה רק התחלה שהוא התחלת התעוררות מלמעלה למטה לבד ולכן לא היה אז בחי' קיום התורה ממקור חוצבה מעצמות אא\"ס ב\"ה רק החלו לעשות בלבד כי עיקר בחי' קיום התורה היה בפורים ע\"י מס\"נ שמצד עצמם דוקא כנ\"ל ואתדל\"ת שמעורר אתדל\"ע הרי נעוץ תחלתן בסופן וסופן בתחלתן שמפני זה בחי' אתדל\"ע זאת היא בבחי' העצמות במעלה ומדרגה היותר נעלה משהיה אתדל\"ע מצד עצמו לבד כנ\"ל הטעם בענין במי נמלך בנשמתן של צדיקים שלכן אמר קימו וקבלו קימו עכשיו דוקא מה שקבלו כבר בסיני וכנ\"ל באריכות בענין ישראל עלו במחשבה כו'. ובכ\"ז מובן בתוס' באור ענין קימו וקבלו כו' שקיום התורה היה בפורים דוקא ואת מי קימו למה שקבלו כבר בסיני מה שהיה אז ע\"י כפייה דהר כגיגית מלמעלה בבחי' חבוק נתקיים עתה בימי הפורים ע\"י מס\"נ דישראל מלמטה למעלה וכנ\"ל דאותו בחי' חפץ חסד שמצד עצמו מקבל ממעשה התחתונים שלזה נתאוה כו' כי סוף מעשה עלה במחשבה תחלה כו' וד\"ל:"],[2201340198,"(לב) <b>וזהו</b> ליהודים היתה אורה כו'. פי' כי הנה התורה נק' אור וכמ\"ש ותורה אור ויש להבין למה נק' התורה בשם אור דוקא. אך הנה פי' ל' תורה הוא ענין ההוראה כמו יורו משפטיך כו' ולהבדיל כו' ולהורות כו'. והענין הוא כמו עד\"מ מן אור הגשמי שאין תועלתו לדבר עצמו רק להורות הדרך להולך באישון לילה שלא יפול בבור וכה\"ג וכן יש באור החכמה שהיא להורות ולהבדיל בין טוב לרע כו' וע\"כ התורה נק' אור כמו אור הנר כן אור התורה מאיר להורות הדרך הישר לפני ה' ולא לנטות ימין ושמאל ולכן נא' דרכיה דרכי כו' ונק' אורחות ה' דרכי ה' כמ\"ש כי ישרים דרכי ה' כו' ולכן נק' תורה ל' הוראה וכן אור השכל מאיר בכל דבר נבוך ומבולבל המעורב טו\"ר גם בתערובת דקה ביותר ואור החכמה תברר ותבדיל בין טוב לרע בתכלית הבירור וההבחנה הזאת היא ע\"י ראיית השכל כמו שרואין לאור הנר וכמו\"כ חכם הרואה את הנולד להבא וכה\"ג בכל דבר נעלם וסתום כמו חשך ע\"י אור החכמה יתגלה כו' וכמ\"ש כיתרון האור מן החשך דוקא ולמעלה היינו מ\"ש ישת חשך סתרו בבחי' ההעלם בעצמות והחכמה מאין תמצא מאין ליש בבחי' גלוי אור וז\"ש יהי אור שהוא אור דתורה וכמו שהאור הגשמי הוא בבחי' בריאה ע\"י מאמר יהי אור כך אור דתורה דמח\"ע כו' ע\"י מאמר יהי אור כו' נתהווה מאין ליש כמ\"ש והחכמה מאין כו' וד\"ל:\n(לג) <b>אך</b> עדיין יש להבין למה נק' אור החכמה בשם תורה ל' הוראה כנ\"ל הרי אין ענין ההוראה וההבחנה נמצאת רק בדבר חכמה שכבר ישנה במציאות כמו כל מיני ההשכלות שהלמוד בהן הוא ע\"י הוראת אור השכל להתחכם בחכמות והשכלות הללו להבדיל כל טעות ושקר ולהעמיד הדבר חכמה על אמתותה דוקא שזהו ע\"י השכל שמוציא לאור אמתת הדבר כידוע אבל כאשר עדיין לא היתה מציאות חכמה בעולם קודם שנברא עדיין ע\"י מאמר יהי אור כנ\"ל איך יתכן לקרות להתהוות אור החכמה בשם תורה להבדיל ולהורות בתערובות טוב ורע שבשכל אחר שאין עדיין דבר חכמה לברר ולהבחין בו כו' אלא מוכרח לומר דמאמר יהי אור קאי על בחי' החכמה שנק' אור וכאשר כבר נתהווה בחי' החכמה ונתחלק לל\"ב נתיבות כו' אז שייך ענין ובחי' חכמה דתורה שנק' ג\"כ אור כמ\"ש ותורה אור אבל הוא למעלה הרבה מבחי' אור דחכמה עד שהוא מורה ומברר בכל מיני אור דל\"ב נ\"ח בכל תערובת טו\"ר שנפל בהן וה\"ז כמו משל בחי' הלמוד במושכלות שכבר במציאות לבררם ולהעמידם על האמת להוציא השקר והטעות כנ\"ל וראיה לד\"ז ממה שמצינו שהתורה קדמה לעולם כמ\"ש כאשר יאמר משל הקדמוני כו' ובראשית בשביל התורה כו' וכמ\"ש ואהיה אצלו אמון. אמון מופלא כו' כמ\"ש במ\"א ומאמר יהי אור הוא אחר מאמר דבראשית שהוא בא בבחי' ההשתלשלות וא\"כ א\"א לומר דמאמר יהי אור קאי על אור דתורה כו' אלא על בחי' אור דחכמה סתם ומ\"ש אורייתא מח\"ע נפקת היינו מבחי' חכמתו העצמית שלמעלה מבחי' אור ולכן אמר ותורה אור שביכולתה לברר בבחי' אור דחכמה שכל מברר בהכרח שהוא גבוה מן המתברר כו' וד\"ל:\n(לד) <b>וזהו</b> ואהיה אצלו אמון אמון מופלא כו' כידוע דאאלפך חכמה הוא ענין הלמוד שבחכמה הנ\"ל בפי' ותורה אור כי תרגום למוד אולפנא כו' והוא בחי' מקור החכמה שנקרא אין וכמ\"ש והחכמה מאין כו' שמשם נמצא מציאות החכמה מאין ליש ולכן ביכולתה להאיר אור בכל חכמה כמ\"ש ותורה אור שהוא ההוראה והלמוד כנ\"ל (וכמ\"ש וכל בניך למודי הוי\"ה שהוא מקור להוי\"ה דחכמה כמ\"ש ה' בחכמה כו' והוא ע\"י למוד התורה שמלמדין להמשיך שם הוי\"ה כמו בחי' אולפנא ממש כמ\"ש ואאלפך חכמה כו') אך זהו דוקא כאשר כבר"],[2201340199,"ירדה התורה להיות בבחי' אור בבחי' למוד שנק' אולפנא כנ\"ל אבל כמו שהתורה היתה קודם שנאצל ונברא העולם בחכמה שלא ירדה עדיין להאיר למטה ואז נק' פלא בהיפוך אותיות אלף כידוע והוא בחי' ההסתר וההעלם בעצמות המאציל כמו כי יפלא ממך וזהו אמון מופלא בחי' פלא העליון כו' והוא הנקרא אורה מקור האור דתורה הנ\"ל וזהו ליהודים היתה אורה בחי' נוק' לפי שע\"י מס\"נ מלמטה למעלה שבזה קימו את אור דתורה ממקור חוצבה בבחי' פלא מטעם הנ\"ל דנעוץ תחלתן בסופן דוקא שלזה היה תחלת המחשבה והרצון הפשוט כו' ע\"כ נאמר אורה ל' נוקבא כמ\"ש אשת חיל עטרת בעלה כו' שהאור הזה ע\"ש כנ\"י נקרא אור שלה (כמ\"ש בזהר ויהיו חיי שרה דילה אנון כו') וזהו מפני שאתדל\"ת שלהם עשה אתדל\"ע שזהו יותר עולה בבחי' העצמות כו' מטעם הנ\"ל באריכות ולכן אמר ליהודים דוקא היתה אורה בחי' נוק' שלמעלה גם מבחי' ותורה אור בחי' דכר משפיע למטה כי פלא למעלה מאאלפך חכמה כנ\"ל וד\"ל:\n(לה) <b>ושמחה</b> וששון ויקר. הנה בזמן מ\"ת נאמר ביום חתנתו וביום שמחת לבו כו' הרי היתה השמחה בלבו בהעלם ולא באה עדיין בגלוי למטה בעולמות וגם לפי דברי רז\"ל דביום שמחת לבו קאי על בנין בהמ\"ק גם אז לא היתה השמחה בגלוי רק שמחת לבו לבד ואף גם זאת לא היתה השמחה רק במשפיע שנק' חתן כמ\"ש ביום חתנתו אבל לא נא' שמחה בכנ\"י שנק' כלה רק בזמן מרדכי ואסתר דכתיב ליהודים היתה אורה ושמחה שהיה בכנ\"י בחי' שמחה בהתגלות וכמ\"ש אם הבנים שמחה ועיקר השמחה נק' על שם הכלה משא\"כ במ\"ת שע\"ז אמר משמח חתן עם הכלה שהכלה מקבלת שמחה מן החתן וכמ\"ש אשה בעלה משמחה כו' אבל כאשר אשת חיל עטרת בעלה כו' כמו בפורים ע\"י מס\"נ שלהם באתדל\"ת שעשו אתדל\"ע דנעוץ תחלתן בסופן דוקא כנ\"ל הרי נהפוך הוא שעיקר השמחה דוקא ע\"ש כנ\"י וזהו ליהודים דוקא היתה כו' ושמחה והטעם הוא כי עיקר שמחה הוא רק גלוי ההעלם כי נתגלה אז דוקא בחי' עונג הנעלם שבעצמות להיות לו דירה בתחתוני' כו' משא\"כ במ\"ת שלא היה רק שמחת לבו בהעלם כו' וד\"ל. וההפרש בין ששון לשמחה ידוע שהשמחה היא בהתגלות גמור לעשות סעודה ומשתה וששון הוא בלב ואמנם שניהם באים על גמרו של דבר דוקא עד\"מ מלך שעושה משתה וסעודה להיות הכל שמחין בשמחה בהתגלות לפי שכבר גמר הדבר כמו גמר בנין גדול או גמר נצוח מלחמה וכה\"ג אבל כ\"ז שלא נגמר הדבר הטוב אע\"פ שבלבו מתענג על טוב הדבר אבל אינו שמח שמחה גלויה עדיין עד שיגמור הדבר דוקא וכמ\"ש במ\"א ע\"פ ויספו ענוים בה' שמחה כו' וגם כאן לפי שקימו מה שקבלו והחלו לעשות בזמן מ\"ת כנ\"ל הרי עיקר גמר הדבר היה עכשיו בזמן פורים ולכן נאמר ליהודים היתה אורה ושמחה וששון כו' וד\"ל:\n(לו) <b>ומעתה</b> יש להבין למה גדלה שמחת פורים מכל שמחת יו\"ט דכתי' בהדיא כו' עד שחייב אינש לבסומי כו' דהנה כל שמחת יו\"ט הוא ע\"פ התורה דכתיב ושמחת בחגך וכן ושמחתם לפני ה' כו' בהיות ידוע בשרש בחי' י\"ט שהוא בחי' מוחין דאמא דכתיב בה אם הבנים שמחה כו' לפי שהשמחה הוא בחי' גלוי ההעלם כידוע ובכל מועד ורגל יש גלוי ההעלם מאא\"ס בבחי' בינה בפסח בבחי' החסד כו' וזהו ע\"פ בחי' סדר ההשתלשלות דסובב וממלא וע\"כ בא' מצות השמחה בי\"ט ע\"פ התורה ושמחת כו' אבל בפורים עיקר השמחה הוא למעל' מבחי' ההשתלשלות דסובב וממלא דהיינו רק מבחי' עצמותו ומהותו ית' ממש דוקא כנ\"ל שזהו ע\"י בחי' מס\"נ שלמעלה מן הטעם ודעת וע\"כ אין השמחה בבחי' טעם ודעת כמו שמחת י\"ט שהוא בחי' בינה אם הבנים שמחה כו' אלא"],[2201340200,"למעלה מן הטעם ודעת (וע\"כ אין אומרים הלל והודאה בפורים שההלל הוא השמחה שמצד הדעת אם הבנים שמחה כו') וכל בחי' שמחה שלמעלה מן הדעת לגמרי גדולה ביותר להיותה למעלה מבחי' השתלשלות לגמרי ולכן הפליגו רז\"ל בשמחת פורים כי חייב אינש לבסומי עד דלא ידע כו' להיותה למעלה מבחי' הדעת מטעם הנ\"ל ע\"כ חייב לבסומי כ\"כ עד שתהיה השמחה למעלה מן הדעת ולא ידע בין ארור המן כו' ולא תהיה השמחה ע\"פ הדעת כו' וד\"ל ומה שתלו ענין השמחה שלמעלה מן הדעת בהבחנה זו שבין ארור המן כו' אין הכוונה שישתווה ח\"ו לטעות בין ארור המן כו' שבודאי המן ארור לעולם כו' אלא תהיה השמחה מצד עצמותו ית' דוקא דקמיה כולא כלא כו' כחשיכה כאורה שוין ממש מפני העדר תפיסת מקום כו' כמ\"ש במ\"א ושם אין הפרש בין ארור המן כו' וזהו עד דלא ידע ההפרש בין כו' וד\"ל:\n(לז) <b>אך</b> הנה מעתה יש להבין למה מותר בעשיית מלאכה בפורים ולא גזרו עליה כמו ביו\"ט והלא ק\"ו הוא מיו\"ט שאם בפורים השמחה גדולה משמחת יו\"ט יותר ראוי לאסור המלאכה שמונע השמחה ובפרט מאחר שקבלו היהודים את אשר החלו שקבלוה ברצון ולא באונס הרי יותר ראוי ע\"פ התורה לשמוח בפורים מבחג השבועות כו' אמנם הנה שרש הענין בהיות ידוע בטעם אסור מלאכה ביו\"ט הוא לפי שיו\"ט נק' מקרא קדש מבחי' שבת שנק' קדש מלה בגרמיה כו' בחי' המנוחה והשביתה מן העבודה וז\"ש כל מלאכת עבדה לא תעשו כו' והוא למעלה בחי' הבירורים דט\"ל מלאכות חורש וזורע כו' והוא עצמו הטעם לענין השמחה ביו\"ט כמ\"ש במ\"א והנה לפ\"ז יש מניעה אל השמחה מצד העבודה במלאכה לפי שהמה ב' הפכים כי עובדין דחול הוא לברר ברורים שהוא בחי' ירידה דו\"ק דז\"א וביו\"ט הוא בחי' עליות לו\"ק דז\"א כו' וז\"ש הטעם ג\"כ לאיסור מלאכה ביו\"ט מפני שממנו השמחה כו' אך הנה כ\"ז לא שייך רק בבחי' השמחה בחי' קדש הבא בבחי' השתלשלות דחו\"ב כו' שנמשך מבחי' סובב בממלא כו' כנ\"ל אבל בחי' פורים שהשמחה היא מצד עצמותו ית' דוקא שלמעלה מן ההשתלשלות דסובב וממלא כו' הוא בבחי' שלמעלה מן הדעת דשם שוין חשך ואור כמ\"ש כחשיכה כאורה כו' משום דכולא קמיה כלא כו' כנ\"ל א\"כ אין עשיית מלאכה בטול ומניעה כלל וכלל לבחי' שמחה הגדולה הזאת למטה כי דוקא בשמחה שמצד הדעת יש לה מניעה ובטול בעשיית מלאכה כנ\"ל אבל בשמחה שלמעלה מן הדעת אין בחי' עבודה נחשב ליש כלל ולמעלה ג\"כ ענין הבירור דל\"ט מלאכות לאהפכא חשוכא לנהורא כו' שנק' עובדין דחול אין זה בחי' מניעה וביטול כלל לבחי' השמחה שמצד עצמו' אא\"ס ממש דקמיה כחשיכה כאורה כו' ולהיות כי הוא למעלה מבחי' השתלשלות כו' גם חשך לא יחשיך כו' ע\"כ מותר בעשיית מלאכה שאין זה תופס מקום כלל כו' רק מרדכי רצה לגזור על המלאכה לעשות לפורים דאורייתא והוא להיות השמחה ע\"פ תורה דווקא משום דהדר קבלוה ברצון והוא להיות בחי' מרדכי בחי' החכמה לברר בירורים כנ\"ל בפי' אשר כתב מרדכי ולדעתו המלאכה ביטול ומניעה קצת אבל לא בעו לקבולי מיניה גזירה זו מטעם הנ\"ל ששרש שמחת פורים למעלה משמחת יו\"ט דאוריי' כו' וד\"ל:\n(לח) <b>ויקר</b> הנה כתיב אדם ביקר בל ילין כו'. וזה קאי על אדה\"ר כשהיה בג\"ע קודם שחטא בעה\"ד כו' שלא היה יכול לעמוד שם לקבל בחינת יקר העליון כו' ובאור הדברים הנה פי' יקר הוא בחינת הארת אא\"ס כשהוא בא בבחי' ומדרגה הגבוה מאד הוא שנקרא יקר כמו עד\"מ כשמשתעשע האדם בדבר היקר מאד נעלה כי עיקר היקר הוא רק הפלגת הערך כמו יקר תפארת גדולתו כו' כל הון יקר כו' ושרשו הוא בחינת השעשועים המופלגים"],[2201340201,"מצד יוקרו המופלג כמו הבן יקיר לי כו' ילד שעשועים כו' כמו ע\"ד דוגמא אבן טוב יקר הערך בהפלגה גדולה שאין לו שעור כלל הנה השעשועים בו ג\"כ מופלג ביותר עד אין שעור כלל כו' וד\"ל ובאמת בתיבת יקר יש ב' פירושים א' ענין יקרות כמו הון יקר כו' וכה\"ג רבות והב' ענין כבוד וגדולה מופלגת ביקר הערך מאד כמו ואת יקר תפארת גדולתו כו' למי יחפוץ המלך לעשות יקר כו' מה נעשה יקר וגדולה למרדכי כו' וכתרגום כבודו זיו יקריה וכמו\"כ ענין זיו השכינה בג\"ע הנה בחי' הזיו הזה הוא בחינת זיו יקריה שהוא בחינת יקר הערך בהפלגה גדולה מאד וב' הפי' עולים לסגנון א' שמצד בחינת יקר הערך והחשיבו' כמו בחינת כבוד ויקר וגדולה יתירה כנ\"ל יפול בו ג\"כ ל' יוקר ממש שהוא יקרות הדבר לגודל עוצם חשיבותו וגדולתו בעיני הכל וכמו ולי מה יקרו ריעיך כו' מאשר יקרת בעיני נכבדת וכה\"ג שזה סובל ב' הפירושים ענין יקרות ממש וענין יקר הערך בגדולה וחשיבות מופלגת כי כל דבר חשוב ביותר נקרא יקר והוא יקר ערכו שזהו ג\"כ סבת יוקרו כמו אבן טוב שמפני יקר ערכו ביותר מצד עוצם חשיבותו בעיני הכל לכן הוא נמכר ביוקר גדול ביותר ולפי ערך החשיבות ויקר ערכו ממש כן ערך מקחו ביוקר ונמצא הא בהא תליא ועולין לסגנון א' וכידוע וד\"ל:\n(לט) <b>וכן</b> יובן ג\"כ בענין זיו השכינה שנקרא כבוד ה' זיו יקרא דקוב\"ה שנק' יקר תפארת גדולתו כו' שזהו ג\"כ בחינת יקר הערך בהפלגה גדולה בלי שעור שזהו בחינת אא\"ס שלגדולתו אין חקר וז\"ש בזהר בכמה דוכתי לאסתכלא ביקריה דמלכא כו' וע\"כ מפני גודל המעלה והחשיבות נקרא יקר ע\"ש בחינת היקרות כמו ולי מה יקרו כו' והכל ענין א' וע\"ז אמר אדם ביקר בל ילין שלא היה אדה\"ר יכול לעמוד בבחינת יקר העליון כי בחי' ההסתכלות ביקר הוד תפארת גדולת א\"ס ב\"ה הוא בחי' שעשועים גדולים שאין לו שעור כמו ע\"ד דוגמא בהסתכלות על אבן יקרה ביותר שעל ראש המלך או בשאר יקר גדולתו העצום שהתענוג בזה מופלג ביותר עד שלא יכילנו כלי המוח והלב ולפי ערך היקר כ\"ה ערך התענוג והשעשועים ולמעלה ביקר תפארת גדולת עצמות אא\"ס נק' שעשועי המלך בעצמותו כו' שא\"א למקבל בע\"ג להכילו כלל להיותו בחי' ומדרגה גבוה מאד נעלה ממדרגת המקבלים עד שיוכל המקבל להתבטל לגמרי ממציאותו להיות בו כלות הנפש ממש שנק' מיתה כמו שמצינו בבן עזאי שהציץ ומת ועליו אמרו יקר בעיני ה' המותה לחסידיו כמבואר בדרז\"ל והענין הוא שאותן ד' שנכנסו לפרדס הגיעו למדרגת הארת אא\"ס ב\"ה שבכתר עליון ע\"י העלאת פנימית חכמה שבנפשם עד בחינת פנימית ח\"ע דאצילות כמ\"ש במ\"א ובן עזאי לא היו כלי מוחו ולבו ונפשו יכולים לקבל אור יקר המופלג הזה כי מאד נעלה הוא עד שנתבטל רוחו ממציאות ויצא מכלי גופו ומת וזהו הציץ ומת הציץ בהסתכלות ביקרא דמלכא ולגודל השעשועים לא עמד רוחו ויצא מגופו ולכן אמר הכתוב עליו דוקא יקר בעיני ה' המותה כו' פי' כי מי שמקבל בחי' יקר העליון נקרא גם הוא יקר בעיני ה' אך מצד שלא יוכל להכיל בא לכלל מיתה שהוא בטול מופלג וז\"ש יקר בעיני ה' הוא הגורם להיות המותה כו' וזוהי מעלה ומדרגה יתירה לחסידי עליון כשמותה לחסידיו ע\"י בחינת יקר העליון שנכלל ממש ביקר העליון ולפ\"ז בן עזאי למעלה מבן זומא שהציץ ונפגע כו' וד\"ל:\n(מ) <b>אך</b> א\"כ יש להבין איך יכולים הנשמות בג\"ע לקבל בכלי מוחם והשגתם את זיו השכינה שהוא אא\"ס שבמל' דאצילות כידוע שבודאי מוכרח שיתבטלו ממציאותם לגמרי כמו בן עזאי וכה\"ג אמנם הענין הוא דאם היה"],[2201340202,"בא אור המאיר מיקר העליון כמו שהוא על הנשמות בג\"ע העליון ודאי היו מתבטלים ממציאותם לגמרי כבן עזאי וכה\"ג אך בחינת אור יקר זה מתלבש בלבוש הנקרא מסך או רקיע המבדיל ומעלים את עצם אור יקר הזה ואין הארתו אליהם רק ע\"י מסך זה שנקרא הארה דהארה כידוע והוא הרקיע החקוק בכ\"ב אתוון שנטוי על הנשמות בג\"ע שבו ועל ידו מסתכלין ביקרא דמלכא מדי שבת וחדש שיבא כל בשר להשתחוות כו' וד\"ל וע\"י בחינת הארה דהארה יכולי' לקבל בהשגתם להיות נהנין מזיו אור יקר הזה וגם זה אפס קצהו לבד דהיינו רק מבחינת האותיות שבו כו' וד\"ל וזהו מארז\"ל ע\"פ להנחיל אוהבי יש שהן ש\"י עולמות כידוע והענין הוא כי הנה יקר בגי' ש\"י וב\"פ ש\"י גי' תר\"ך שהוא גי' כתר וכידוע שבחינת הכתר נחלק לחצאין ה' ספירות הראשונות שבו עולין למעלה בעצמותו וה\"ס האחרונות יורדין ומתלבשין למטה דהיינו כח\"ב וחו\"ג עולים למעלה ותנהי\"מ יורדין למטה ע\"כ מבחינת ת\"ת שבכתר יוצא ראשית גלוי אורו להאיר למטה כידוע שמתחתון שבעליון נעשה כתר לתחתון כו' ולזה בחינת ש\"י חציו הראשון אינו יורד למטה כלל אלא נשאר בהעלם עצמותו אך חציו הב' שהוא ש\"י הב' יורד למטה כמו להנחיל אהבי יש לנשמו' שבג\"ע שיוכלו לקבל מזיו השכינה כנ\"ל שהן מקבלין מבחינת כתר מל' שנקרא זיו יקריה כו' וג\"ז אינם מקבלים רק ע\"י מסך שהוא המתצמצם לבא לפי ערך כלי השגתם המוגבל המצומצם וז\"ש להנחיל אוהבי יש בהפוך אתוון מבחינת ש\"י כי מה שמשיגים אור הכתר בהשגתם המצומצם נקרא יש ודבר מה ובאמת הרי אמר דלית מחשבה תפיסא ביה כלל ומה שנתפס בהשגתם אין זה מבחינת האין דאור א\"ס כלל אלא בחינת יש כי הרי האור מאיר ובא דרך מסך המעלים עצם האור כנ\"ל וזהו עיקר תענוג הנשמות שנהנין מזיו כו' ונק' ש\"י עולמות כו' וד\"ל:\n(מא) <b>אך</b> הנה לע\"ל כתיב ולא יכנף עוד מוריך והיו עיניך ראות כו' וכן כתיב כי עין בעין יראו כו' דהיינו שלא יהיה התגלות אור וזיו יקר העליון דעצמות אא\"ס ע\"י לבוש ומסך וזהו ולא יכנף עוד כו' אלא עיניך רואות בעצם אור יקר העליון כו' והענין הוא דלע\"ל יתגלה אא\"ס כמו שהוא למעלה בעצמותו למטה אל המקבלים בלי הסתר ולבוש כלל משום דבבחי' סובב הכללי מעלה ומטה שוין בו וכמ\"ש ומתחת זרועות עולם כו' אני ראשון ואני אחרון כו' כמשל העיגול שאין בו מעלה ומטה וכידוע ובחי' לבוש והסתר אינו אלא כאשר מתצמצם להאיר בבחי' קו וחוט כו' שאז מתצמצם בעצמו והאור אינו מאיר רק ע\"י צמצום שנק' מסך וכמ\"ש הנה אלהינו זה קוינו לו כו' וזהו תרגום מלא כל הארץ כבודו זיו יקריה זיו דהוד שמו כמ\"ש הודו על ארץ כו' שזהו בחי' הארה דהארה לבד כנ\"ל אבל לע\"ל יתגלה בחי' יקר העליון כמו שהוא בעצמו והוא הנק' יקר גי' ש\"י אבל הוא בחי' הפנימי' כמו שהוא טרם בואו להתלבש בלבוש וצמצום לפי ערך קבלת כלי השגת הנשמות בג\"ע להנות מזיו כו' וזהו עיקר ההפרש בין יקר לש\"י שנק' י\"ש כו' והנה בפורים מפני שהיה לכנ\"י בחי' מס\"נ בעצמות אא\"ס ממש זכו לקבל מבחי' יקר תפארת גדולת עצמותו בלי הסתר ולבוש כלל אלא כמו שהוא בבחי' הפנימי' בלי לבוש מעלים כלל ע\"ד שיהי' לע\"ל דכתיב ולא יכנף עוד כו' כנ\"ל וזהו ליהודים היתה אורה אור ה' מקור האור דתורה שזהו בחי' אור יקר העליון כמו שהוא בבחי' הפנימית מטעם הנ\"ל וזהו וששון ויקר הוא בחי' יקר העליון שבעצמותו כו' וד\"ל:\nת' ו' ש' ל' ב' ע'"],[2201340203,"<h2>קיצורי הספר שערי אורה</h2>\nהקדמה. יבאר שדרך חיים הוא להאיר הנפש באור האלקי, ב' מדריגות במס\"נ א' אהבה רבה בתפלה ותשובה, ובה ב' אופנים, הא' אהבתי אתכם, והב' אהבת כנס\"י, ב' מס\"נ בפו\"מ על תו\"מ. וגם היא בב' אופנים, הא' הבאה מצד המשפיע והוא הנס דפורים. והב' מצד המקבלים, והוא הנס דחנוכה. ויבאר ענין ברכת התורה. שקודם הקריאה מברך אשר בחר, והוא שרש ישראל באותיות התורה, ואחר הקריאה אשר נתן, שהתקבל האור בתוכיות.\n<b>תוכן.</b> במס\"נ ב' מדרי' הא' מצד המשפיע, והב' מצד המקבל. ב' מדרי' במס\"נ בפו\"מ. והם ב' מיני נסים דחנוכה ופורים.\nשער החנוכה\nדרוש הראשון בכ\"ה בכסלו יומי דחנוכה. ובו נ\"ט פרקים\nפרק א. יקשה העיקר הוא הניצוח, ולמה תלוי במציאות השמן. וקבעו הלל. מקדים נרות המקדש. וכי לאורה הוא צריך, אלא דאהרן מעלה הנשמות, דשרשם בז\"מ דקדושה, ובעבודה זלעו\"ז יש זמ\"ר דקליפה, וע\"י הבירור מוסיפים אור, ומבררים גם ק\"נ.\nתוכן. נרות המנורה נשמות. ז\"מ דקדושה. זמ\"ר דקליפה.\n<b>פרק</b> ב. יבאר דהבירור דזמ\"ר ע\"י ז\"מ דקדושה הוא רק לפי שעה. וכחלום פרעה שהי' מראיהן רע כבתחלה, שלא ניתוסף לטובתם, וכמו בההולך בשרירות לבו, דגם כשעושה טוב, נבלע בו ואינו ניכר, ולפעמים עושה רושם ברע, והם ב' מיני בליעה, הא' ונבל כי ישבע, שנתוסף בהקליפה וע\"ש, והב' ובטן רשעים תחסר, כי חיל בלע ויקיאנו.\nתוכן. הבירור שע\"י מדות דקדושה רק לפי שעה. ב' מיני בליעה."],[2201340204,"<b>פרק</b> ג. ובכדי להפוך זמ\"ר לגמרי הוא ע\"י החכ' דוקא, שנקראת אב למדות ונקראת אור. ובכח מ\"ה שבנפש מזדככים המדות לגמרי, והחכמה מאירה גם בחשך להאירו, וכמו חכם הרואה את הנולד, ומאיר גם בחומר הגס. ונקודת אור זה ישנו בכאו\"א בשלימות.\nתוכן. חכמה אור. ושלימה בכאו\"א.\n<b>פרק</b> ד. פני המנורה הוא אור החכמה מחצב הנשמות, וכשמגיע בכל המדות אז חיל בלע ויקיאנו, ועז\"נ וכבודי לאחר לא אתן, וגם ההולך בשרירות לבו, הנה נקודת היהדות שבנפשו מתעורר תמיד, אמנם בימי חשמונאי שהקליפות התגברו, הוצרכו להמשיך אור חדש ממקור החכמה, שהוא אור שבעת הימים. וזהו שעיקר הדלקת המנורה בלילה, משא\"כ ביום מספיק נר הששי, וג' מדרי' אור חסד וטוב כולם בחכמה.\nתוכן. אור החכמה מחצב הנשמות.\n<b>פרק</b> ה. עולם הוא חיצוניות העולמות שהם מלאכים וע\"ש, והעלאת הנרות שע\"י אהרן הוא בע' נפש דיעקב שהוא הפנימיות, ונמשך גם תועלת בחיצוניות העולמות להאירם, וכמו שהוא בכל אחד בפרט דכשמאיר כח מ\"ה שבנפשו, גם חומר גסות גופו מזדכך מעט, ועיקר הדלקת הנרות ליתן כח בע' נפש דיעקב, להאיר היו\"ד גם בעקב, וזהו שאמר דוד נר לרגלי דבריך.\nתוכן. הדלקת הנרות להאיר יעקב יו\"ד עקב.\n<b>פרק</b> ו. לפי אופן ההשתלשלות בציור אדם דקדושה, הנה בכל דור מתבררים הקליפות, ומתבררים גם העקביים, ויקשה דלכאו' הם עקבות עשו, דעשו כתר ופרעה ונבוכדנצר חו\"ב דקליפה כו' ומבאר דידו אוחזת בעקב עשו, דכאשר יו\"ד דחסד שבחכ' מתפשט' למטה, מבררת גם עקבי עשו, בכח וגבורה דחסד, דלא זה בלבד שלא יהי' בעשו ההילוך בעומק רע, אלא עוד שיתברר, וזהו המשכת אור החכמה בז' נרות.\nתוכן. עקבי יעקב ועקבי עשו.\n<b>פרק</b> ז. יבאר דקטרת היתה אחר הטבת הנרות, ומקשה שייכותם. מבאר כי הקטרת העלאת אותיות המדות, דאותיות המחשבה מלבישים למדות ושכל, והמחשבה לעצמה כח מיוחד בנפש, ולכן משוטט"],[2201340205,"תמיד, וגם בענינים שאינם לא שכל ולא מדות, היראה מתחיל במוח ומסתיים בלב, והאהבה מתחיל בלב ומסתיים במוח (ואין זה מוכרח, דהכעס לפעמים בלב תחלה, כן הרחמנות במח' תחלה) הכעס והקפידא תחלתה במח' שעלולה להתפעל יותר, והלב יוכל לכבוש בנקל יותר.\nתוכן. מחשבה כח מיוחד בנפש.\n<b>פרק</b> ח. מבאר שהאותיות דמו\"ד דזמ\"ר, יכול להיות דאף גם אם המדות יתעלו ישארו בתקפם, להיותם בלתי מחוברים עם עצם המדות, ולכן אפשר שהמדות יתבררו על ידי אור החכ', והאותיות דמו\"ד ישארו, ותיקונם ע\"י כף הקלע שקשה מגיהנם.\nתוכן. אותיות מחו\"ד מתתקנים ע\"י כף הקלע.\n<b>פרק</b> ט. מקשה למה מד\"ר יכולים להזדכך ע\"י אור החכמה, ואותיות מו\"ד אינם יכולים להזדכך ע\"י אור החכ', ומבאר דמדות תולדותם מאו\"א, ויסוד אבא ארוך ומסתיים ביסוד ז\"א ואור החכ' אף שמגיע בהאותיות שהם דומם, אבל בריחוק ובהעלם (מקשה, הלא אבא יסד ברתא, דשרש הדיבור מהחכ').\nתוכן. מדות תולדותם מאו\"א.\n<b>פרק</b> י. מבאר מה שאבא יסד ברתא הוא רק בצירוף האותיות אבל בשרשם הם מעצמות הנפש, ובא בגילוי, דיבור בחכ' ומח' בבינה, אור אימא מסתיים בהבל הלב, ויסוד אבא ארוך מסתיים בחזה הלב לפעול הביטול דכח מ\"ה, ושרש האותיות דמו\"ד הם בעצם הנפש, שלמעלה מחו\"ב, ומשו\"ז חו\"ב אפשר שיתעלו, והאותיות ישארו, (ומצד ההתלבשות כל היחודים ע\"י האותיות, אותיות דקדמות הרצון, אותיות דכתר, אותיות השכל דחו\"ב, אותיות המדות, שהם דצח\"מ שלמעלה, האותיות עצמיים דומם, דהם למעלה מתענוג ורצון, צומח התפעלות רצון וענג, חי התפעלות חו\"ב ומדות, מדבר דיבור).\nתוכן. שרש האותיות מעצמות הנפש, והם דצח\"מ שלמעלה.\n<b>פרק</b> יא. והנה ב' בחי' שבמח' הנ\"ל הם בת ציון, המקושרת ומיוחדה בדביקה, וחומת בת ציון, דשניהם נבנים מאבנים שהם האותיות, דבתים אותיות מסודרים וחומה בחי' מקיף, וזהו חומת בת ציון הורידי"],[2201340206,"כנחל דמעה, דאף שקומת ב\"צ התתקנה, הנה תיקון החומה בחי' מקיף הוא ע\"י דמעות שמכבסות (וזהו הרהורי עבירה שקשין מעבירה עצמה) וכן עיר וחומה דקדושה.\nתוכן. עיר וחומה באותיות המחשבה.\n<b>פרק</b> יב. יקשה מהו כנחל דמעה, ומבאר דנחל הוא מחשבה, שמשוטטת בהתגברות יתירה דעש\"ז נק' לאה, שנלאה להכיל מרוב הנביעה, הן בענג הנפש שבאה בהתפשטות גדולה, והן בהיפוכו שבאה בצער כיווץ ביותר, ומזה נמצא הדמעות, שהם תיקון האותיות.\nתוכן. המחשבה נקראת נחל.\n<b>פרק</b> יג. יבאר מעלת הקטרת על הקרבנות שנק' לחם, וכמו הלחם שסועד, כמו\"כ הקרבנות בירור המדות ע\"י ארי' דאכיל קורבנין שהוא בחי' ראי' דחכ', אבל קטרת באה מסמים חריפים, שאין בו טעם וריח דאכילה שיש בו עריבות, וריח דקטרת הנשמה נהנה ולא הגוף, והוא הבירור די\"א (ארורים) סממנים, ע\"י הקטרת, דאין אור החכ' מגיע לשם, ונעשים ריח טוב וחזק כקיוהא וחריף המשיב את הנפש, שהבירור הוא שמגיע למעלה יותר מאור החכמה שנעשה ע\"י הקרבנות (וכן בתפלה שבמקום קרבנות נעשה העלי' רק במוחין ומדות, ולא במו\"ד עצמן).\nתוכן. מעלת הקטרת על הקרבנות.\n<b>פרק</b> יד. יבאר דתחלה צ\"ל הבירור דפנימיות הרצון שכל ומדות, ואח\"כ לבושי המו\"ד, ולכן הטבת הנרות קודמת לקטרת, ויקשה דלכאו' מהראוי שיתברר הקשה (לבושי מו\"ד) תחלה, ומבאר דיש ב' מדרי' במח', והא' מה שהמח' מלביש למוחין ומדות (פ\"ז) והוא בריבוי אור וחיות, ולכן צריך להתברר תחלה, ע\"י המוחין ומדות, (א\"פ מזכך חצי הכלי מבפנים, ואו\"מ חצי הכלי מבחוץ, וכן בתשובה תחלה לעקור הרצון, ואח\"כ וידוי פה באותיות מו\"ד).\nתוכן. טעם הקדמת הטבת נרות לקטרת.\n<b>פרק</b> טו. יקשה, למה בהקרבת התמיד הנה בין דם לאבריו מפסיקים בהטבת ב' נרות (לאחר הטבת ה' נרות שקודם גם לדם התמיד) וקטרת באמצע, הנה קרבנות ונרות הוא הכל בבירור החכ' כנ\"ל והיו"],[2201340207,"צריכים להקדים הקרבת האברים ג\"כ, ומבאר דבשרש ענין התפלה במקום קרבן, הנה בק\"ש ב' מיני מס\"נ הא' של נפה\"א שתודבק באח\"פ בעצומ\"ה במס\"נ דאחד, והב' מס\"נ דבכל נפשך בואהבת שגם הנפש הטבעי יפשוט כל רצון זר, ויכלול בה', וזה הי' בקשת וצער רע\"ק מתי יבוא לידי מס\"נ זה שיהי' לבו ונה\"ט שלו מוכן למס\"נ.\n<b>תוכן.</b> מס\"נ דאחד בנשמה אלקית, מס\"נ דואהבת בנפש הטבעית, בקשת רע\"ק שיהי' לבו מוכן למס\"נ.\n<b>פרק</b> טז. והנה הביטול דנה\"ט במקורו הוא בפני אדם שבפני שור שבמרכבה, דשרשו במל' דברי' ויצי', וא\"כ ההפרש דמס\"נ באחד שהוא במהו\"ע (ע\"י המל') והמס\"נ דואהבת הוא בבחי' מל' דבי\"ע, ומס\"נ דרע\"ק שהאריך באחד שגם מצד הגוף יהי' בבחי' ומדרי' אחד, מבאר להבין בב' מדרי' מס\"נ דיח\"ת ויחו\"ע שהם סובב וממלא, דשניהם הם רק זיו והארה, שזהו משובח ומפואר בעילוי עדי עד, וכן משובח ומפואר בלשון חסידיו ועבדיו בהמשכה וגילוי למטה, דב' בחי' אלו דסובב וממלא נמשכי' ממל' דא\"ס, אבל עצמותו יחיד ומיוחד.\n<b>תוכן.</b> דזיו הוא הן בעילוי והן בהמשכה, סובב וממלא המשכתם ממל' דא\"ס, המס\"נ דרע\"ק בגוף דוקא.\n<b>פרק</b> יז. מבאר דחסידיו הן הנשמות דשרשם בפנימיות העולמות ונק' מהלכים שעולים בעילוי אחר עילוי מג\"ע לג\"ע עד עצומ\"ה, ועבדיו הם המלאכים דשרשם בחיצוניות ונק' עומדים, והם מבחי' דיבור העליון, וא\"כ עלייתם רק במקורם בחי' מל' דבי\"ע, ובאמת הנה גם בזה עליות עד אין קץ, דהרי א\"ס להתפשטותו, כמו שא\"ס לרוממותו, וכ\"ז בעליות העולמות בפנימיות ע\"י הנשמות ובחיצוניות ע\"י המלאכים שכולם משתחוים כו' אבל למטה יותר הוא בחי' נגה, אחורי הפרגוד מקור מחצב נפש החומרי, שהאור האלקי בהסתר, וא\"כ איך יהי' בו הביטול להאין האלקי, דלולי המסך הי' האור אלקי מאיר גם בגסות דק\"נ.\nתוכן. ההפרש שבין נשמות ומלאכים, נגה שבכל עולם.\n<b>פרק</b> יח. הצעה. הנשמה עצמה אינה צריכה תיקון כי צרורה בצרור החיים, ויורדת לפעול ולתקן בהנה\"ט, העבודה מצד הנשמה שנק' נר הוי', בשרשה בהוי' דאצילות, וענינה להשיג ביחו\"ע דע\"ס במהוע\"צ, בהאין ערוך, ובאיכות יחודם, ותכלית העילוי דנה\"ט הוא ביטול היש"],[2201340208,"לאין, וכמו המלאכים שביטולם רק במקור חוצבם במל' דבי\"ע, אשר לפי ערך זה הוא גם בתכלית העילוי דנה\"ט, והוי כטפל לעבודת הנשמה שהוא עיקר, וא\"כ למה ירידה זו לצורך עלי' להנשמה עצמה, ע\"י שתזכך את הנה\"ט.\nתוכן. עבודת הנשמה בהשגת איכות הע\"ס במהוע\"צ.\n<b>פרק</b> יט. ירידת הנשמה לתקן הנה\"ט שיבוא לביטול אמיתי ביחו\"ת, אשר כחה רב מהביטול דנשמה עצמה ביחו\"ע, דשרש הנה\"ט מפני שור, שהחיות נושאות בכח שרשם שבתהו שקדום לתיקון, את האדם שעה\"כ בבחי' כי לא אדם, וכמו הבע\"ת דמשכין לי' בחילא יתיר, מצד שרש הנה\"ט, שהוא בחי' ס\"ג שלמעלה מצדיקים גמורים שהוא מ\"ה דאדם דתיקון, שהוא אור החכ' אב הנשמות, וכתי' וזרעתי כו' זרע אדם מ\"ה וזרע בהמה ב\"ן, וע\"י התשובה גם הרע נהפך לטוב, יש בו עילוי משרשו הקדום, וז\"ש דוד בהמות הייתי עמך.\nתוכן. מעלת ביטול היש דנה\"ט שמוספת עילוי בהאין דנשמה.\n<b>פרק</b> כ. וזהו שרש הטעם דקרבנות דלכאו' איך בהקרבת בהמה שאינה בר דעת בעד האדם יתוקן פגמו, אך אדם שהוא שם מ\"ה, כי יקריב כו' בהמה שם ב\"ן, קרבן להוי' דוקא, והוא שהנה\"א שנק' אדם יקריב להנה\"ט שהוא בהמה, ויכולת הקרבה זו באדם דוקא, הנה אז מתעורר כח וניצוץ הנעלם שבבהמה, משרשו הקדום לתקן נפש האדם, וכמו באכילה שתחלה מקרב את המאכל שיוכלל ע\"י הכנה וברכה, ואח\"כ המאכל מחזק אותו (ותשו' הוא עוד למעלה מקרבנות, שמהפך את הרע לטוב ממש).\nתוכן. טעם הקרבנות, הקרבנות ע\"י אדם דוקא.\n<b>פרק</b> כא. מבאר הטעם שהקרבנות טעונות צפון, וכן השולחן בצפון, ולכאו' היו ראוים להיות בדרום שהוא ימין, ולמה שם בצפון ציוה הוי' את הברכה והגילוי אור עליון שבא ע\"י העלאת תמיד, וכתיב צפונה, ונקראת לפני הוי', למעלה מהוי', צפונ'ה שצפון בה\"א, ה\"א אחרונה שהוא הצמצום, והוא סיבת התגברות תשוקת העלי' דשרפים וחיות, ועי\"ז עולים הקרבנות בהצפון ומוסתר שבה\"א אחרונה, לבחי' לפני הוי' דאדם, וכן בעבודת התפלה שהנה\"א מעלה את הנה\"ט להיות נכלל באש של מעלה.\nתוכן. הצמצום וההתעלמות סיבת ההתגברות."],[2201340209,"<b>פרק</b> כב. מבאר כי האדם שהוא הנה\"א מעלה ומקריב לבהמה דנה\"ב, שבההשגה דיחו\"ת יש עלי' להנה\"א למעלה משרשו בבחי' יחו\"ע, והוא הביטול עצמי דיחו\"ע שזהו אדם ובהמה תושיע ה' שלמעלה משניהם, שעוזר להאדם הנה\"א שיוכל להקריב ולהעלות את הבהמה דנה\"ב, ועוזר לשם ב\"ן שתתברר, וגם יברר למ\"ה דאדם, וכמו החיות שנושאות את הכסא, וארון שנשא את נושאיו, ועזרת הוי' כולל הפכיים מ\"ה יברר ב\"ן, וב\"ן יתברר ויברר מ\"ה.\n<b>תוכן.</b> שע\"י העבודה דיחו\"ת מגיעים למעלה מיחו\"ע, שהוא הביטול עצמי דיחו\"ע, ג' מדרי' יחו\"ת, יחו\"ע, וביטול עצמי דיחו\"ע.\n<b>פרק</b> כג. ובזה יבאר ג' אהבות שבק\"ש, לבבך, נפשך, מאדך, ומציע כי ב' חללים בלב, הימיני רוח חיים ושרשו במוח החכ', והשמאלי משכן הנה\"ט ומקורן מוח הבינה, וע\"י התפעלות האהבה דלבבך, בלב הגשמי ברתיחה, בדוגמת העלאת דם התמיד, שהתפעלות זו באה ע\"י ההשגה שבמוח ביחו\"ת, אייתי רוח מן אור הנשמה שבמוח, שיהי' למטה כמו למעלה והיא אהבה דנפשך, הבאה אחרי לבבך, וזהו אדם שהוא רוח חיים שבלב דשרשו במוח הבינה מקריב הנה\"ב, ואז גם הנה\"ב באהבה דלבבך מעלה בחי' נפשך, שעי\"ז נעשה עליית הנשמה שבמוח שהוא אהבת מאדך.\n<b>תוכן.</b> ג' מדרי' אהבה, לבבך, נפשך, מאדך, חלל הימיני מקורו במוח החכ' והשמאלי במוח הבינה.\n<b>פרק</b> כד. ובזה יבאר מה שדם התמיד בא בין הטבת ה' נרות וב' נרות, דהנה כדי שאור החכ' יאיר בהמדות, הוא ע\"י דם התמיד, ומ\"מ הטבת ה' נרות קודם לדם התמיד, ומחלק בין הטבה והדלקה, דהכנת הה' נרות בשמן לא יחסר, שהם בהה' מדות, דעד הוד אתפשטת, וההכנה הוא בההשגה דשמע ישראל בבינה לבא, ואחרי הקרבת דם התמיד נמשך גם בהב' נרות שהם יסוד ומל', והדלקת כולם בלילה דוקא.\nתוכן. בטעם הקרבת דם התמיד בין הטבת ה' וב' נרות.\n<b>פרק</b> כה. יבאר שהקטרת הוא בכל מאדך, וכמו שע\"י לבבך מגיע להעלאת דם התמיד שהוא נפשך, דגם שם יאיר האור דחכ', הנה עי\"ז מגיע לקטרת שהוא דומם ואינו ראוי למאכל, רק כשמשימים על האש נעשה ריח חזק המשיב את הנפש, וכמו\"כ הוא מעשה הצדקה"],[2201340210,"(דיש אדם שממונו כו') שבעשי' דוקא הרי יש לה שרש עליון מכל מקור אור הנשמה שבמוח, ומוספת לה תוס' אור, דנעוץ תחב\"ס, וריח הנשמה דוקא נהנית. (ואף שע\"י האכילה יתחזק כלי המוח, הוא רק בחומר של צורה השכלית באו\"כ שהו\"ע הלחם דקרבנות).\nתוכן. מעלת הקטרת, מעלת הריח על האכילה.\n<b>פרק</b> כו. מבאר כי המצות הם כמו הקטרת ריח חזק שאין בו טעם, והוא דוקא משיב את הנפש, כן העלי' דמצות שעושים נח\"ר ובהם ממשיכים העלם העצמות, דמצוה בא\"ת ב\"ש הוא שם הוי', שמוסיף אור בשם הוי', והמצות נקראים צדקה שתרומם גוי, למעלה מאור החכמה, וזהו מעשה ידינו כוננהו, וזהו סדר המערכה, דם התמיד בכל לבבך (כנ\"ל ע\"י ההכנה) נרות בכל נפשך ההארה גם בנפש השכלית, קטרת בכל מאדך במעשה הצדקה שכוללת כל המצות מעשיות.\nתוכן. מצות כמו קטרת שאין בהם טעם ומשיבים הנפש.\n<b>פרק</b> כז. יקשה בסדר הקרבת התמיד, בהפסק נרות וקטרת בין דם התמיד להקרבת אבריו, ומקדים ביאור שרש ענין שהמצות נק' צדקה, ומבאר כי הצדקה נמשלה לשריון העשוי מקשקשים שזהו עיקר החוזק להגין בעד החצים, דכל פרוטה מצטרפת לחשבון גדול, כן רמ\"ח מ\"ע ושס\"ה מל\"ת וריבוי ההידורים שבכ\"א מהם מגנא ומצלא בעידנא דעסיק בה, וכמו שבצדקה מחי' רוח שפלים בכל פרוטה ופרוטה, כן ע\"י המצות מעורר ר\"ר העליונים להחיותו ממקיף דאור החכמה.\nתוכן. מצות נמשלו לשריון.\n<b>פרק</b> כח. יקשה המשך הכתוב וילבש צדקה כו' וכובע ישועה בראשו, ומבאר הכתוב עטרת תפארת שיבה בדרך צדקה תמצא, ומפרש תפארת של שיבה, שהוא מהכובע ישועה שבראשו הנה היא בדרך צדקה תמצא, וא\"כ הכתובים (וילבש צדקה כשריון, ועטרת תפארת) סותרים, דבזה אמר שע\"י הצדקה מגיעים לכובע ישועה, ובזה אמר שתפארת השיבה בא ע\"י הצדקה, ולכאו' הוא רק שריון בלבד.\nתוכן. ההבדל שבין השיבה והדרת פנים.\n<b>פרק</b> כט. יבאר כי בהארת פנים יש ב' מדריגות, דהארת פנים הוא קיבוץ הדמים בהפנים וזה יבוא לב' סיבות, הא' מלמעלה"],[2201340211,"למטה והוא מפני חידוש כח החכ' והשכל שבמוחו, שבזה מתגלה פנימיות התענוג ושמחת הנפש, וכשמחת ר\"ג שמצא תוס' חדתא, (ואידום הפנים לפי שבא בגילוי בדמים שבפנים) והוא הנק' הדרת פנים מצד פנימיות כח ואור דמקור החכ' שמאיר בפנים, והו\"ע הגילוי דמ\"ת כי באור פניך פנים העליונים דאצי' שנמשך מפנימי' השעשועים דעצמות המאציל ב\"ה וזהו שארז\"ל במ\"ת נדמה להם כזקן, וכן הוא גם עתה שמתקבל בכח מ\"ה שבנפשו מהפנים העליונים, שדבריו חיים וקיימים ישראל ואורייתא מתקשראן, וזהו הדלקת הנרות להאיר האור בנשמות.\n<b>תוכן.</b> ב' סבות בהארת פנים, הא' גילוי אור המוח וההשגה, והב' שמחת הלב בבשורה טובה (פ\"ל).\n<b>פרק</b> ל. הסיבה הב' בהארת פנים, הוא מלמטלמ\"ע, שע\"י שמחת הלב יתאדמו פניו, ומבאר כי בלב יש פנימיות וחיצוניות, דחיצוניות הלב מקושרה לעתים בחיצוניות המוח, ולא תמיד ולכן יכול להיות כי יתפעל במוח ולא יתפעל בלב, אבל פנימית הלב מקושרה בפנימיות המוח ולכן כשיתפעל האדם במוחו, והוא שההשגה האלקית בהתפעלות הביטול במוח, מיד יוקלט ביטול זה בפנימיות לבו, וכמו\"כ הלב משפיע בהמוח דלבי ראה הרבה חכמה שנק' עין השכל שבלב, ועושה התפעלות פנימי בהמוח, דכן הוא גם בענין השמחה, שבכח הלב לפעול על המוח ואף שיין המשמח הוא בהדם בלבד, ומ\"מ ע\"י יוצא הסוד הפנימי לחדש שכלים ביותר מכפי כחו בעצם חכמתו, וזהו דשמחה פנימיות שבלב בבחי' או\"ח הוא למעלה מאור הפנים שע\"י החכ' באו\"י, ובמ\"ת שאמור כי באור פניך שהי' גילוי ב' בחי' פנים.\n<b>תוכן.</b> פנימיות הלב מקושר עם פנימיות המוח, ויכול לפעול עילוי בהמוח.\n<b>פרק</b> לא. וזהו שמן וקטרת ישמח לב. והוי ב' דברים דשמן נרות, וקטרת ריח חזק שפועל השבת הנפש בהמוח ולב כא' להיותו מגיע בעצם הנפש והוי לי' לומר ישמחו, אלא דשניהם ב' מדרי' שבהארת פנים הנ\"ל דשמן הוא או\"י אלא שהוא מקור האור, והקטרת מלמטלמ\"ע או\"ח, ישמח לב בפנימיות שלו שמתאחד עם פנימיות המוח, והם ב' מדרי' שמחה ש\"מ, ושמחת התורה, דפקודי ה' דוקא משמחי לב, והוא מעלת הריח על הלחם דתו', ומ\"מ קודם הקטרת צ\"ל שמן, והם יחדיו ישמחו לב אדם העליון."],[2201340212,"תוכן. הריח משיב את הנפש במוח ולב כאחד.\n<b>פרק</b> לב. יבאר דשרש המצות בפנימיות התענוג והרצון שנק' כתר שבכתר, ועצומ\"ה למעלה גם מרצון לרצון, ובמע\"ב נמשך הרצון ע\"י הצמצום, ופנימיות התענוג והרצון ע\"י המצות, וזהו עושין רצונו, שלהיותם מלובשים בענינים גשמיים, ממשיכים האור למטה וכמו העמוד שמחבר הגג עם הרצפה, והמצות תר\"ך עמודי אור בחי' כתר שלמעלה מהאור דתורה.\nתוכן. שרש המצות בכתר שבכתר.\n<b>פרק</b> לג. יבאר דוילבש צדקה כו' וכובע ישועה כו' זהו שאנו אומרים זורע צדקות מצמיח ישועות, שהצדקה זריעה, והישועה צמיחה, בישועה ב' פירושים הא' מל' עוזר ומושיע, והב' מל' פונה כמו וישע אל הבל, ולתפלתם שעה, ושניהם אחד דכאשר פונה לבקשת המבקש הוא העזרה, ונמצא דהישועה הוא המקור להארת הפנים, וזהו ישועה, יו\"ד בראשו שיאיר בה\"א שבסופו.\n<b>תוכן.</b> ב' פירושים בישועה א' עוזר ב' הפונה ושניהם אחד, דכשפונה לקוראיו זהו עזרו.\n<b>פרק</b> לד. יבאר כי ע\"י הצדקה נעשה הכובע ישועה להיות שרשם בפנימיות ועצמות דוקא, וזהו עטרת תפארת שיבה, שתפארת השיבה, שהוא מקור הארת הפנים הנה זה בא ע\"י הצדקה, ונעשה עטרת תפארת המשכת המקיף (ומ\"מ עוד יוקשה איך מהשריון נעשה כובע, ומבאר דבעת המלחמה הוא שריון, ולאחר הניצוח נעשה כובע ישועה) (ואפשר י\"ל בב' אופנים, הא' ע\"ד הקדמת ג' אהבות הנ\"ל שע\"י העבודה דלבבך, ממשיך בנפשך, ואז נעשה עלית הנשמה שהוא מאדך, כן ע\"י הצדקה תחלה נמשך הכובע ישועה שהוא העזר, ועי\"ז ממשיך אח\"כ גם העטרת תפארת. הב' שע\"י צדקה ממשיך כובע ישועה וע\"י דרך הצדקה (וכמו שמנו שמונה מעלות בנותני צדקה) ממשיכים עטרת תפארת).\nתוכן. ע\"י הצדקה נמשך עטרת תפארת השיבה.\n<b>פרק</b> לה. יבאר כי בקרבנות ב' ענינים, הא' השחיטה וזריקת הדם, הב' הקטרת הבשר והחלב, ולזה בהקרבת התמיד בין הדם והאברים הפסיק בנרות וקטרת, שהם בסדר העבודה בב' ענינים הנ\"ל שבקרבן,"]]});
